    // PATCH RSAJ - badge kapsul kelas rawat dengan lebar mengikuti teks.
    private static final class KelasRawatBadgeIcon implements javax.swing.Icon {
        private static final int TINGGI = 26;
        private static final int UKURAN_ICON = 16;
        private static final int PADDING_KIRI = 8;
        private static final int JARAK_ICON_TEKS = 6;
        private static final int PADDING_KANAN = 10;
        private static final java.awt.Font FONT_BADGE =
                new java.awt.Font("Segoe UI Semibold", java.awt.Font.BOLD, 11);
        private static final java.awt.font.FontRenderContext FONT_RENDER_CONTEXT =
                new java.awt.font.FontRenderContext(null, true, true);
        private String teks = "Kelas -";
        private int lebar = hitungLebar(teks);

        public void setTeks(String teks) {
            this.teks = teks == null || teks.trim().equals("") ? "Kelas -" : teks.trim();
            this.lebar = hitungLebar(this.teks);
        }

        private int hitungLebar(String nilai) {
            int lebarTeks = (int) Math.ceil(
                    FONT_BADGE.getStringBounds(nilai, FONT_RENDER_CONTEXT).getWidth());
            return PADDING_KIRI + UKURAN_ICON + JARAK_ICON_TEKS +
                    lebarTeks + PADDING_KANAN + 2;
        }

        @Override
        public int getIconWidth() {
            return lebar;
        }

        @Override
        public int getIconHeight() {
            return TINGGI;
        }

        @Override
        public void paintIcon(java.awt.Component c, java.awt.Graphics g, int x, int y) {
            java.awt.Graphics2D g2 = (java.awt.Graphics2D) g.create();
            try {
                g2.setRenderingHint(java.awt.RenderingHints.KEY_ANTIALIASING,
                        java.awt.RenderingHints.VALUE_ANTIALIAS_ON);
                g2.setRenderingHint(java.awt.RenderingHints.KEY_TEXT_ANTIALIASING,
                        java.awt.RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
                g2.setRenderingHint(java.awt.RenderingHints.KEY_INTERPOLATION,
                        java.awt.RenderingHints.VALUE_INTERPOLATION_BILINEAR);

                // Kapsul biru muda dengan garis tepi halus.
                g2.setColor(new java.awt.Color(232, 244, 255));
                g2.fillRoundRect(x, y, lebar - 1, TINGGI - 1, TINGGI, TINGGI);
                g2.setColor(new java.awt.Color(184, 218, 250));
                g2.drawRoundRect(x, y, lebar - 1, TINGGI - 1, TINGGI, TINGGI);

                // Ikon menggunakan resource standar Khanza /picture/category.png.
                g2.drawImage(ICON_CATEGORY.getImage(),
                        x + PADDING_KIRI,
                        y + ((TINGGI - UKURAN_ICON) / 2),
                        UKURAN_ICON, UKURAN_ICON, c);

                g2.setFont(FONT_BADGE);
                g2.setColor(new java.awt.Color(15, 95, 175));
                java.awt.FontMetrics fm = g2.getFontMetrics();
                int posisiY = y + ((TINGGI - fm.getHeight()) / 2) + fm.getAscent();
                g2.drawString(teks,
                        x + PADDING_KIRI + UKURAN_ICON + JARAK_ICON_TEKS,
                        posisiY);
            } finally {
                g2.dispose();
            }
        }
    }
