    private java.awt.Component tampilkanOverlayBuramPindah(final String judul) {
        final java.awt.Component glassPaneSebelumnya=DlgKamarInap.this.getGlassPane();
        javax.swing.JComponent overlay=new javax.swing.JComponent() {
            private static final long serialVersionUID=1L;
            @Override
            protected void paintComponent(java.awt.Graphics g) {
                java.awt.Graphics2D g2=(java.awt.Graphics2D)g.create();
                try{
                    g2.setRenderingHint(java.awt.RenderingHints.KEY_ANTIALIASING,
                            java.awt.RenderingHints.VALUE_ANTIALIAS_ON);
                    g2.setColor(new java.awt.Color(255,255,255,120));
                    g2.fillRect(0,0,getWidth(),getHeight());
                    g2.setColor(new java.awt.Color(15,23,42,38));
                    g2.fillRect(0,0,getWidth(),getHeight());
                    int lebar=Math.min(420,Math.max(240,getWidth()/3));
                    int tinggi=58;
                    int x=(getWidth()-lebar)/2;
                    int y=Math.max(26,getHeight()/8);
                    g2.setColor(new java.awt.Color(255,255,255,222));
                    g2.fillRoundRect(x,y,lebar,tinggi,18,18);
                    g2.setColor(new java.awt.Color(206,218,232));
                    g2.drawRoundRect(x,y,lebar-1,tinggi-1,18,18);
                    g2.setFont(new java.awt.Font("Segoe UI Semibold",java.awt.Font.BOLD,14));
                    g2.setColor(new java.awt.Color(41,60,84));
                    java.awt.FontMetrics fm=g2.getFontMetrics();
                    String teks=(judul==null||judul.trim().equals(""))?
                            "Fokus ke konfirmasi" : judul.trim();
                    int tx=x+Math.max(14,(lebar-fm.stringWidth(teks))/2);
                    int ty=y+((tinggi-fm.getHeight())/2)+fm.getAscent();
                    g2.drawString(teks,tx,ty);
                }finally{
                    g2.dispose();
                }
            }
        };
        overlay.setOpaque(false);
        overlay.addMouseListener(new java.awt.event.MouseAdapter(){});
        overlay.addMouseMotionListener(new java.awt.event.MouseMotionAdapter(){});
        overlay.addMouseWheelListener(new java.awt.event.MouseWheelListener(){
            @Override public void mouseWheelMoved(java.awt.event.MouseWheelEvent e){}
        });
        overlay.setCursor(new java.awt.Cursor(java.awt.Cursor.DEFAULT_CURSOR));
        DlgKamarInap.this.setGlassPane(overlay);
        overlay.setVisible(true);
        return glassPaneSebelumnya;
    }

    private void sembunyikanOverlayBuramPindah(java.awt.Component glassPaneSebelumnya) {
        java.awt.Component overlayAktif=DlgKamarInap.this.getGlassPane();
        if(overlayAktif!=null){
            overlayAktif.setVisible(false);
        }
        if(glassPaneSebelumnya!=null&&glassPaneSebelumnya!=overlayAktif){
            DlgKamarInap.this.setGlassPane(glassPaneSebelumnya);
            glassPaneSebelumnya.setVisible(false);
        }
    }

