     /**
      * Menempatkan daftar rawat inap dan form pemindahan dalam satu CardLayout.
      * internalFrame1 tetap halaman utama, sedangkan internalFrame3 menjadi
      * halaman pemindahan. Dengan cara ini komponen serta event lama tetap
      * digunakan tanpa membuat JDialog pemindahan baru.
      */
     private void siapkanHalamanPindahKamarTerintegrasi() {
         if(panelHalamanDlgKamarInap!=null){
             return;
         }

         java.awt.Container indukDaftar=internalFrame1.getParent();
         if(indukDaftar!=null){
             indukDaftar.remove(internalFrame1);
         }
         java.awt.Container indukPindah=internalFrame3.getParent();
         if(indukPindah!=null){
             indukPindah.remove(internalFrame3);
             indukPindah.revalidate();
             indukPindah.repaint();
         }

         tataLetakHalamanDlgKamarInap=new java.awt.CardLayout();
         panelHalamanDlgKamarInap=new javax.swing.JPanel(tataLetakHalamanDlgKamarInap);
         panelHalamanDlgKamarInap.setOpaque(false);
         panelHalamanDlgKamarInap.add(internalFrame1,HALAMAN_DAFTAR_KAMAR);
         panelHalamanDlgKamarInap.add(internalFrame3,HALAMAN_PINDAH_KAMAR);
         DlgKamarInap.this.getContentPane().add(
                 panelHalamanDlgKamarInap,java.awt.BorderLayout.CENTER);
         tataLetakHalamanDlgKamarInap.show(panelHalamanDlgKamarInap,HALAMAN_DAFTAR_KAMAR);

         internalFrame3.getInputMap(javax.swing.JComponent.WHEN_ANCESTOR_OF_FOCUSED_COMPONENT).put(
                 javax.swing.KeyStroke.getKeyStroke(java.awt.event.KeyEvent.VK_ESCAPE,0),
                 "kembaliKeDaftarKamar");
         internalFrame3.getActionMap().put("kembaliKeDaftarKamar",new javax.swing.AbstractAction() {
             private static final long serialVersionUID=1L;
             @Override
             public void actionPerformed(java.awt.event.ActionEvent evt) {
                 BtnCloseInpindahActionPerformed(null);
             }
         });
         DlgKamarInap.this.getContentPane().revalidate();
         DlgKamarInap.this.getContentPane().repaint();
     }

     private void tampilkanHalamanPindahKamarTerintegrasi() {
         siapkanHalamanPindahKamarTerintegrasi();
         if(!halamanPindahKamarTerbuka){
             judulDlgKamarInapSebelumPindah=DlgKamarInap.this.getTitle();
             tombolDefaultSebelumPindah=DlgKamarInap.this.getRootPane().getDefaultButton();
         }
         halamanPindahKamarTerbuka=true;
         DlgKamarInap.this.setTitle("Pemindahan Kamar Pasien");
         DlgKamarInap.this.getRootPane().setDefaultButton(btnAksiPindahVisual);
         tataLetakHalamanDlgKamarInap.show(
                 panelHalamanDlgKamarInap,HALAMAN_PINDAH_KAMAR);
         internalFrame3.revalidate();
         internalFrame3.repaint();
         javax.swing.SwingUtilities.invokeLater(new Runnable() {
             @Override
             public void run() {
                 if(kdkamarpindah.isEnabled()){
                     kdkamarpindah.requestFocusInWindow();
                 }
             }
         });
     }

