     /**
      * Menyimpan induk dan posisi komponen form kamar asli sebelum komponen
      * dipakai oleh halaman Pemulangan Pasien. Data ini dipakai untuk
      * mengembalikan tampilan Check In tanpa membuat salinan field ataupun
      * mengganti event handler Khanza.
      */
     private void simpanTataLetakLegacyPemulangan() {
         java.awt.Component[] komponen={
             CmbTgl,CmbBln,CmbTahun,cmbJam,cmbMnt,cmbDtk,
             diagnosaawal,diagnosaakhir,cmbStatus,StatusPulang,btnDiagnosa
         };
         for(java.awt.Component item:komponen){
             if(item!=null&&item.getParent()!=null&&
                     !indukKomponenPemulanganLegacy.containsKey(item)){
                 indukKomponenPemulanganLegacy.put(item,item.getParent());
                 batasKomponenPemulanganLegacy.put(item,item.getBounds());
             }
         }
     }

     /** Memasang listener visual sekali saja; tidak mengubah listener bisnis. */
     private void pasangListenerPemulangan() {
         if(listenerPemulanganTerpasang){
             return;
         }
         listenerPemulanganTerpasang=true;

         java.beans.PropertyChangeListener sinkronTombol=
                 new java.beans.PropertyChangeListener() {
             @Override
             public void propertyChange(java.beans.PropertyChangeEvent evt) {
                 perbaruiStatusTombolPemulangan();
             }
         };
         BtnSimpan.addPropertyChangeListener("enabled",sinkronTombol);
         BtnUpPlgBPJS.addPropertyChangeListener("enabled",sinkronTombol);
         BtnUpPlgBPJS.addPropertyChangeListener("visible",sinkronTombol);
         StatusPulang.addPropertyChangeListener("enabled",sinkronTombol);
         StatusPulang.addPropertyChangeListener("visible",sinkronTombol);

         javax.swing.event.DocumentListener listenerRingkasan=
                 new javax.swing.event.DocumentListener() {
             @Override public void insertUpdate(javax.swing.event.DocumentEvent e){
                 perbaruiRingkasanPemulangan();
             }
             @Override public void removeUpdate(javax.swing.event.DocumentEvent e){
                 perbaruiRingkasanPemulangan();
             }
             @Override public void changedUpdate(javax.swing.event.DocumentEvent e){
                 perbaruiRingkasanPemulangan();
             }
         };
         TJmlHari.getDocument().addDocumentListener(listenerRingkasan);
         ttlbiaya.getDocument().addDocumentListener(listenerRingkasan);

         java.awt.event.ActionListener listenerWaktu=
                 new java.awt.event.ActionListener() {
             @Override
             public void actionPerformed(java.awt.event.ActionEvent evt) {
                 perbaruiRingkasanPemulangan();
             }
         };
         CmbTgl.addActionListener(listenerWaktu);
         CmbBln.addActionListener(listenerWaktu);
         CmbTahun.addActionListener(listenerWaktu);
         cmbJam.addActionListener(listenerWaktu);
         cmbMnt.addActionListener(listenerWaktu);
         cmbDtk.addActionListener(listenerWaktu);
     }

