         lblNoRawatPulang=buatLabelNilaiPemulangan();
         lblNoRMPulang=buatLabelNilaiPemulangan();
         lblNamaPasienPulang=buatLabelNilaiPemulangan();
         lblNoSEPPulang=buatLabelNilaiPemulangan();
         lblTanggalMasukPulang=buatLabelNilaiPemulangan();
         javax.swing.JPanel isiIdentitas=new javax.swing.JPanel(
                 new java.awt.FlowLayout(java.awt.FlowLayout.LEFT,10,0));
         isiIdentitas.setBackground(java.awt.Color.WHITE);
         isiIdentitas.setOpaque(true);
         isiIdentitas.add(buatKolomIdentitasPulang("No. Rawat",lblNoRawatPulang));
         isiIdentitas.add(buatPemisahIdentitasPindah());
         isiIdentitas.add(buatKolomIdentitasPulang("No. RM",lblNoRMPulang));
         isiIdentitas.add(buatPemisahIdentitasPindah());
         isiIdentitas.add(buatKolomIdentitasPulang("Nama Pasien",lblNamaPasienPulang));
         isiIdentitas.add(buatPemisahIdentitasPindah());
         isiIdentitas.add(buatKolomIdentitasPulang("No. SEP",lblNoSEPPulang));
         isiIdentitas.add(buatPemisahIdentitasPindah());
         isiIdentitas.add(buatKolomIdentitasPulang("Tanggal Masuk",lblTanggalMasukPulang));
         identitas.add(isiIdentitas,java.awt.BorderLayout.CENTER);

         // Section flat: judul + ikon + garis tipis. Tidak ada border kartu/rounded.
         buatKartuKamarAktifPemulangan(
                 panelKamarPulangForm,warnaBiru,warnaTeks,warnaSekunder);
         buatKartuRingkasanPemulangan(
                 panelRingkasanPulangForm,warnaBiru,warnaTeks,warnaSekunder);
         buatKartuWaktuClinicalReview(
                 panelWaktuPulangForm,warnaBiru,warnaTeks,warnaSekunder);
         buatPanelDiagnosisStatusClinicalReview(panelDiagnosisPulangForm,
                 panelStatusPulangForm,warnaBiru,warnaTeks,warnaSekunder);

         panelKamarPulangForm.setPreferredSize(null);
         panelRingkasanPulangForm.setPreferredSize(null);
         panelWaktuPulangForm.setPreferredSize(null);
         panelDiagnosisPulangForm.setPreferredSize(null);

         java.awt.GridBagConstraints g=new java.awt.GridBagConstraints();
         g.gridx=0;g.weightx=1;g.fill=java.awt.GridBagConstraints.HORIZONTAL;
