    private javax.swing.JPanel buatBarisReviewKlinisPemulangan(
            String judul,javax.swing.JComponent field,
            javax.swing.JComponent aksi,int lebarLabel) {
        javax.swing.JPanel panel=new javax.swing.JPanel(new java.awt.GridBagLayout());
        panel.setBackground(java.awt.Color.WHITE);
        panel.setOpaque(true);
        java.awt.GridBagConstraints g=new java.awt.GridBagConstraints();
        g.gridy=0;g.anchor=java.awt.GridBagConstraints.WEST;

        javax.swing.JLabel label=new javax.swing.JLabel(judul);
        label.setFont(new java.awt.Font("Segoe UI",java.awt.Font.PLAIN,11));
        label.setForeground(new java.awt.Color(79,95,119));
        label.setPreferredSize(new java.awt.Dimension(lebarLabel,30));
        label.setMinimumSize(new java.awt.Dimension(lebarLabel,30));
        g.gridx=0;g.insets=new java.awt.Insets(0,0,0,8);
        panel.add(label,g);

        g.gridx=1;g.insets=new java.awt.Insets(0,0,0,aksi==null?0:8);
        panel.add(field,g);
        if(aksi!=null){
            g.gridx=2;g.insets=new java.awt.Insets(0,0,0,0);
            panel.add(aksi,g);
        }
        return panel;
    }

