     private javax.swing.JLabel buatNomorLangkahPemulangan(final String nomor) {
         javax.swing.JLabel label=new javax.swing.JLabel(nomor,
                 javax.swing.SwingConstants.CENTER) {
             private static final long serialVersionUID=1L;
             @Override
             protected void paintComponent(java.awt.Graphics g) {
                 java.awt.Graphics2D g2=(java.awt.Graphics2D)g.create();
                 try{
                     g2.setRenderingHint(java.awt.RenderingHints.KEY_ANTIALIASING,
                             java.awt.RenderingHints.VALUE_ANTIALIAS_ON);
                     g2.setColor(new java.awt.Color(10,105,214));
                     g2.fillOval(0,0,getWidth()-1,getHeight()-1);
                 }finally{
                     g2.dispose();
                 }
                 super.paintComponent(g);
             }
         };
         label.setForeground(java.awt.Color.WHITE);
         label.setFont(new java.awt.Font(
                 "Segoe UI Semibold",java.awt.Font.BOLD,14));
         label.setOpaque(false);
         label.setPreferredSize(new java.awt.Dimension(36,36));
         label.setMinimumSize(new java.awt.Dimension(36,36));
         label.setMaximumSize(new java.awt.Dimension(36,36));
         return label;
     }

