     private void perbaruiStatusTombolPemulangan() {
         boolean tampilBPJS=BtnUpPlgBPJS.isVisible()&&StatusPulang.isVisible();
         boolean modeUpdateBPJS=pemulanganLokalSudahBerhasil&&tampilBPJS;

         if(btnPulangkanPasienVisual!=null){
             if(modeUpdateBPJS){
                 btnPulangkanPasienVisual.setText("Update Tgl. Pulang BPJS");
                 btnPulangkanPasienVisual.setIcon(
                         buatIkonMasukPindah(16,java.awt.Color.WHITE));
                 btnPulangkanPasienVisual.setIconTextGap(8);
                 btnPulangkanPasienVisual.setToolTipText(
                         "Update tanggal pulang pasien ke BPJS");
                 btnPulangkanPasienVisual.setEnabled(
                         !prosesUpdatePulangBPJS&&BtnUpPlgBPJS.isEnabled());
             }else{
                 btnPulangkanPasienVisual.setText("Pulangkan Pasien");
                 btnPulangkanPasienVisual.setIcon(new IkonKlinisPindah(
                         IKON_PINDAH_PANAH,18,java.awt.Color.WHITE));
                 btnPulangkanPasienVisual.setIconTextGap(8);
                 btnPulangkanPasienVisual.setToolTipText(null);
                 btnPulangkanPasienVisual.setEnabled(BtnSimpan.isEnabled()&&
                         !pemulanganLokalSudahBerhasil&&!prosesUpdatePulangBPJS);
             }
             // Lebar selalu dihitung ulang mengikuti teks aktif; tinggi tetap 30 px.
             aturUkuranTombolSesuaiTeks(btnPulangkanPasienVisual);
         }

         // V23: jangan tampilkan tombol Update BPJS kedua di panel status.
         if(btnUpdatePulangBPJSVisual!=null){
             btnUpdatePulangBPJSVisual.setVisible(false);
         }
         if(lblStatusBPJSPulangVisual!=null){
             lblStatusBPJSPulangVisual.setVisible(tampilBPJS);
         }
         if(StatusPulang!=null){
             StatusPulang.setVisible(tampilBPJS);
         }
     }

     private void perbaruiRingkasanPemulangan() {
         if(!komponenPemulanganTerpasang){
             return;
         }
         if(lblNoRawatPulang!=null){
             lblNoRawatPulang.setText(nilaiAtauStrip(norawat.getText()));
             lblNoRMPulang.setText(nilaiAtauStrip(TNoRM.getText()));
             lblNamaPasienPulang.setText(nilaiAtauStrip(TPasien.getText()));
             lblNoSEPPulang.setText(nilaiAtauStrip(SEP.getText()));
             lblTanggalMasukPulang.setText(
                     gabungTanggalJamPemulangan(TIn.getText(),JamMasuk.getText()));
             lblKamarAktifPulang.setText(
                     nilaiAtauStrip((kdkamar.getText()+" "+TBangsal.getText()).trim()));
             lblMasukKamarPulang.setText("Masuk  "+
                     gabungTanggalJamPemulangan(TIn.getText(),JamMasuk.getText()));
             String tarif=formatRupiahPemulangan(TTarif.getText());
             lblTarifKamarPulang.setText("Tarif / hari  "+tarif);
             lblLamaRawatPulang.setText(
                     nilaiAtauNol(TJmlHari.getText())+" hari");
             lblTarifRingkasanPulang.setText(tarif);
             lblTotalBiayaPulang.setText(
                     formatRupiahPemulangan(ttlbiaya.getText()));
             lblWaktuKeluarPulang.setText("Keluar  "+
                     waktuKeluarPemulangan());
             lblWaktuHeaderPulang.setText(new java.text.SimpleDateFormat(
                     "dd MMMM yyyy HH:mm:ss",
                     new java.util.Locale("id","ID")).format(new java.util.Date()));
             if(panelIdentitasPulangForm!=null){
                 panelIdentitasPulangForm.revalidate();
                 panelIdentitasPulangForm.repaint();
             }
         }
         perbaruiStatusTombolPemulangan();
     }

     private String nilaiAtauStrip(String nilai) {
         return nilai==null||nilai.trim().equals("")?"-":nilai.trim();
     }

     private String nilaiAtauNol(String nilai) {
         return nilai==null||nilai.trim().equals("")?"0":nilai.trim();
     }

     private String waktuKeluarPemulangan() {
         try{
             return CmbTgl.getSelectedItem()+"-"+
                     CmbBln.getSelectedItem()+"-"+
                     CmbTahun.getSelectedItem()+" "+
                     cmbJam.getSelectedItem()+":"+
                     cmbMnt.getSelectedItem()+":"+
                     cmbDtk.getSelectedItem();
         }catch(Exception e){
             return "-";
         }
     }

     private String gabungTanggalJamPemulangan(String tanggal,String jam) {
         String hasilTanggal=nilaiAtauStrip(tanggal);
         if(!hasilTanggal.equals("-")){
             try{
                 java.util.Date nilaiTanggal=
                         new java.text.SimpleDateFormat("yyyy-MM-dd").parse(hasilTanggal);
                 hasilTanggal=new java.text.SimpleDateFormat(
                         "dd-MM-yyyy").format(nilaiTanggal);
             }catch(Exception e){
                 // Format lama dibiarkan apa adanya agar data tetap terbaca.
             }
         }
         String hasilJam=nilaiAtauStrip(jam);
         return hasilTanggal+(hasilJam.equals("-")?"":" "+hasilJam);
     }

     private String formatRupiahPemulangan(String nilai) {
         try{
             String bersih=nilai==null?"0":
                     nilai.replaceAll("[^0-9\\-\\.]","");
             if(bersih.equals("")||bersih.equals("-")){
                 bersih="0";
             }
             double angka=Double.parseDouble(bersih);
             return "Rp"+new java.text.DecimalFormat("#,##0").format(angka);
         }catch(Exception e){
             return "Rp"+nilaiAtauNol(nilai);
         }
     }

