     private javax.swing.border.Border buatBorderBulatFormPindah(
             final java.awt.Color latar,final java.awt.Color garis,final int radius) {
         return new javax.swing.border.AbstractBorder() {
             private static final long serialVersionUID=1L;

             @Override
             public void paintBorder(java.awt.Component c,java.awt.Graphics g,
                     int x,int y,int width,int height) {
                 java.awt.Graphics2D g2=(java.awt.Graphics2D)g.create();
                 try{
                     g2.setRenderingHint(java.awt.RenderingHints.KEY_ANTIALIASING,
                             java.awt.RenderingHints.VALUE_ANTIALIAS_ON);
                     g2.setColor(new java.awt.Color(31,78,121,18));
                     g2.fillRoundRect(x+1,y+3,Math.max(0,width-3),Math.max(0,height-4),radius,radius);
                     g2.setColor(latar);
                     g2.fillRoundRect(x,y,Math.max(0,width-2),Math.max(0,height-3),radius,radius);
                     g2.setColor(garis);
                     g2.drawRoundRect(x,y,Math.max(0,width-2),Math.max(0,height-3),radius,radius);
                 }finally{
                     g2.dispose();
                 }
             }

             @Override
             public java.awt.Insets getBorderInsets(java.awt.Component c) {
                 return new java.awt.Insets(1,1,1,1);
             }

             @Override
             public java.awt.Insets getBorderInsets(java.awt.Component c,java.awt.Insets insets) {
                 insets.set(1,1,1,1);
                 return insets;
             }
         };
     }

