     private String formatNamaKamarBertingkatPindah(String namaKamar) {
         String teks=namaKamar==null?"":namaKamar.trim().replaceAll("\\s+"," ");
         if(teks.equals("")||teks.startsWith("<html>")){
             return teks.equals("")?"-":teks;
         }
         int batas=teks.indexOf(' ');
         if(batas<1||batas>=teks.length()-1){
             return teks;
         }
         String kode=teks.substring(0,batas).trim();
         String bangsal=teks.substring(batas+1).trim();
         return "<html>"+kode+"<br>"+bangsal+"</html>";
     }

