     private javax.swing.border.Border buatBorderGarisBulatPindah(
             final java.awt.Color garis,final int radius,final int padding) {
         return new javax.swing.border.AbstractBorder() {
             private static final long serialVersionUID=1L;
             @Override
             public void paintBorder(java.awt.Component c,java.awt.Graphics g,
                     int x,int y,int width,int height) {
                 java.awt.Graphics2D g2=(java.awt.Graphics2D)g.create();
                 try{
                     g2.setRenderingHint(java.awt.RenderingHints.KEY_ANTIALIASING,
                             java.awt.RenderingHints.VALUE_ANTIALIAS_ON);
                     g2.setColor(garis);
                     g2.drawRoundRect(x,y,Math.max(0,width-1),Math.max(0,height-1),radius,radius);
                 }finally{
                     g2.dispose();
                 }
             }
             @Override public java.awt.Insets getBorderInsets(java.awt.Component c){
                 return new java.awt.Insets(5,padding,5,padding);
             }
             @Override public java.awt.Insets getBorderInsets(java.awt.Component c,java.awt.Insets insets){
                 insets.set(5,padding,5,padding);return insets;
             }
         };
     }

