     private void susunTimelineKamarPindah(java.util.List<javax.swing.JPanel> kartuRiwayat) {
         if(panelTimelineKamarPindah==null){
             return;
         }
         panelTimelineKamarPindah.removeAll();
         panelTimelineKamarPindah.setLayout(new java.awt.GridBagLayout());

         java.awt.GridBagConstraints g=new java.awt.GridBagConstraints();
         // V41: kartu memakai lebar preferred isi dan menempel di kiri, bukan
         // diregangkan sampai selebar panel riwayat.
         g.gridx=0;g.weightx=1;g.fill=java.awt.GridBagConstraints.NONE;
         g.anchor=java.awt.GridBagConstraints.NORTHWEST;
         int baris=0;

         // V38: kamar saat ini selalu paling atas, histori berikutnya tersusun ke bawah.
         if(kartuKamarSaatIniPindah!=null){
             aturUkuranKartuTimelinePindahV42(kartuKamarSaatIniPindah);
             kartuKamarSaatIniPindah.setAlignmentX(java.awt.Component.LEFT_ALIGNMENT);
             g.gridy=baris++;g.weighty=0;g.insets=new java.awt.Insets(0,0,6,0);
             panelTimelineKamarPindah.add(kartuKamarSaatIniPindah,g);
         }
         // Query lama tetap dipertahankan; hanya urutan visual dibalik agar histori terbaru di atas.
         for(int idx=kartuRiwayat.size()-1;idx>=0;idx--){
             javax.swing.JPanel kartu=kartuRiwayat.get(idx);
             aturUkuranKartuTimelinePindahV42(kartu);
             kartu.setAlignmentX(java.awt.Component.LEFT_ALIGNMENT);
             g.gridy=baris++;g.weighty=0;g.insets=new java.awt.Insets(0,0,6,0);
             panelTimelineKamarPindah.add(kartu,g);
         }

         javax.swing.JPanel filler=new javax.swing.JPanel();
         filler.setOpaque(false);
         g.gridy=baris;g.weighty=1;g.fill=java.awt.GridBagConstraints.BOTH;
         g.insets=new java.awt.Insets(0,0,0,0);
         panelTimelineKamarPindah.add(filler,g);
         panelTimelineKamarPindah.revalidate();
         panelTimelineKamarPindah.repaint();
     }


