     private void aturTabelPilihKamarHakKelasV26(javax.swing.JTable tabel) {
         tabel.setSelectionMode(javax.swing.ListSelectionModel.SINGLE_SELECTION);
         tabel.setRowHeight(28);
         tabel.setFont(new java.awt.Font("Segoe UI",java.awt.Font.PLAIN,12));
         tabel.setForeground(new java.awt.Color(31,45,62));
         tabel.setSelectionForeground(java.awt.Color.WHITE);
         tabel.setSelectionBackground(new java.awt.Color(10,105,214));
         tabel.setGridColor(new java.awt.Color(229,236,245));
         tabel.setShowHorizontalLines(true);
         tabel.setShowVerticalLines(true);
         tabel.setAutoCreateRowSorter(true);
         tabel.setFillsViewportHeight(true);
         tabel.setRowMargin(0);
         tabel.setIntercellSpacing(new java.awt.Dimension(0,1));
         javax.swing.table.JTableHeader header=tabel.getTableHeader();
         header.setReorderingAllowed(false);
         header.setResizingAllowed(true);
         header.setFont(new java.awt.Font("Segoe UI Semibold",java.awt.Font.BOLD,12));
         header.setForeground(new java.awt.Color(30,41,59));
         header.setBackground(new java.awt.Color(244,248,252));
         header.setPreferredSize(new java.awt.Dimension(100,32));
         if(tabel.getColumnModel().getColumnCount()>=4){
             tabel.getColumnModel().getColumn(0).setPreferredWidth(150);
             tabel.getColumnModel().getColumn(1).setPreferredWidth(265);
             tabel.getColumnModel().getColumn(2).setPreferredWidth(110);
             tabel.getColumnModel().getColumn(3).setPreferredWidth(150);
         }
     }

     private javax.swing.JPanel buatKartuPenyesuaianHakKelasV25(
             String judul,String badgeTeks,String kodeKamar,String namaBangsal,
             String waktuMasuk,double tarif,boolean tujuan) {
         final java.awt.Color warnaBiru=new java.awt.Color(10,105,214);
         final java.awt.Color warnaHijau=new java.awt.Color(35,142,65);
         final java.awt.Color warna=tujuan?warnaHijau:warnaBiru;
         javax.swing.JLabel badge=buatBadgeTimelineKamarPindah(
                 badgeTeks==null||badgeTeks.trim().equals("")?"-":badgeTeks.trim(),
                 tujuan?new java.awt.Color(232,249,235):warnaBiru,
                 tujuan?warnaHijau:java.awt.Color.WHITE);
         javax.swing.JPanel kartu=buatKartuDasarTimelinePindah(judul,badge);
         kartu.setPreferredSize(new java.awt.Dimension(300,190));
         kartu.setMinimumSize(new java.awt.Dimension(235,175));

         String nama=((kodeKamar==null?"":kodeKamar.trim())+" "+
                 (namaBangsal==null?"":namaBangsal.trim())).trim();
         javax.swing.JLabel labelKamar=new javax.swing.JLabel(nama.equals("")?"-":nama);
         labelKamar.setFont(new java.awt.Font("Segoe UI Semibold",java.awt.Font.BOLD,12));
         labelKamar.setForeground(new java.awt.Color(24,42,66));
         labelKamar.setToolTipText(nama);
         javax.swing.JLabel labelMasuk=new javax.swing.JLabel(
                 waktuMasuk==null||waktuMasuk.trim().equals("")?"-":waktuMasuk.trim());
         labelMasuk.setFont(new java.awt.Font("Segoe UI",java.awt.Font.PLAIN,13));
         labelMasuk.setForeground(new java.awt.Color(24,42,66));
         javax.swing.JLabel labelTarif=new javax.swing.JLabel("Rp"+formatAngkaPindah(tarif));
         labelTarif.setFont(new java.awt.Font("Segoe UI",java.awt.Font.PLAIN,13));
         labelTarif.setForeground(new java.awt.Color(24,42,66));

         javax.swing.JPanel isi=new javax.swing.JPanel(new java.awt.GridBagLayout());
         isi.setOpaque(false);
         java.awt.GridBagConstraints g=new java.awt.GridBagConstraints();
         g.gridx=0;g.fill=java.awt.GridBagConstraints.HORIZONTAL;g.weightx=1;
         g.gridy=0;g.insets=new java.awt.Insets(0,0,8,0);
         isi.add(buatKotakNamaKamarTimelinePindah(labelKamar,
                 tujuan?new java.awt.Color(241,251,244):new java.awt.Color(239,247,255),
                 tujuan?new java.awt.Color(167,220,178):new java.awt.Color(155,203,246),
                 warna),g);
         g.gridy=1;g.insets=new java.awt.Insets(0,0,4,0);
         isi.add(buatBarisInfoKamarPindah(IKON_PINDAH_JAM,"Masuk",labelMasuk),g);
         g.gridy=2;g.insets=new java.awt.Insets(0,0,0,0);
         isi.add(buatBarisInfoKamarPindah(IKON_PINDAH_UANG,"Tarif / hari",labelTarif),g);
         kartu.add(isi,java.awt.BorderLayout.CENTER);
         return kartu;
     }

