     private boolean sesuaikanKamarAktifKeHakKelasV24(
             String noRawat,String kodeKamarAsal,String tanggalMasuk,
             String jamMasuk,KamarHakKelas tujuan,String hakNormal,
             String alasan) {
         boolean autoCommitSebelumnya=true;
         boolean transaksiDimulai=false;
         try{
             if(koneksi==null||koneksi.isClosed()){
                 throw new SQLException("Koneksi database tidak tersedia.");
             }
             if(tujuan==null||tujuan.kodeKamar.equals("")){
                 throw new SQLException("Kamar hak kelas belum dipilih.");
             }
             if(kodeKamarAsal.equals(tujuan.kodeKamar)){
                 throw new SQLException("Kamar penyesuaian sama dengan kamar aktif.");
             }
             autoCommitSebelumnya=koneksi.getAutoCommit();
             if(!autoCommitSebelumnya){
                 throw new SQLException("Koneksi database sedang digunakan oleh transaksi lain. Silakan ulangi.");
             }
             pastikanTabelPindahMendukungTransaksi();
             pastikanTabelAuditPindahTersedia();
             koneksi.setAutoCommit(false);
             transaksiDimulai=true;

             int jumlahAktif=0;
             try(PreparedStatement cek=koneksi.prepareStatement(
                     "select kd_kamar from kamar_inap where no_rawat=? and stts_pulang='-' for update")){
                 cek.setString(1,noRawat);
                 try(ResultSet hasil=cek.executeQuery()){
                     while(hasil.next()) jumlahAktif++;
                 }
             }
             if(jumlahAktif!=1){
                 throw new SQLException("Pasien harus memiliki tepat satu kamar aktif. Ditemukan "+jumlahAktif+".");
             }

             SnapshotKamarInapPindah asal=ambilSnapshotKamarAsalTerkunci(
                     noRawat,kodeKamarAsal,tanggalMasuk,jamMasuk);
             String statusAsal=getStatusKamarTerkunci(kodeKamarAsal);
             String statusTujuan=getStatusKamarTerkunci(tujuan.kodeKamar);

             // Khusus penyesuaian administratif sebelum pemulangan:
             // kamar target boleh ISI maupun KOSONG. Yang wajib adalah master aktif
             // (statusdata=1) dan kelas PERSIS sama dengan hak pasien.
             int statusDataTujuan=0;
             String kelasTujuan="";
             try(PreparedStatement cekTujuan=koneksi.prepareStatement(
                     "select statusdata,coalesce(kelas,'') as kelas from kamar "+
                     "where kd_kamar=? limit 1 for update")){
                 cekTujuan.setString(1,tujuan.kodeKamar);
                 try(ResultSet hasilTujuan=cekTujuan.executeQuery()){
                     if(hasilTujuan.next()){
                         statusDataTujuan=hasilTujuan.getInt("statusdata");
                         kelasTujuan=amanStringPindah(hasilTujuan.getString("kelas"));
                     }
                 }
             }
             if(statusDataTujuan!=1){
                 throw new SQLException("Kamar hak kelas sudah tidak aktif pada master kamar.");
             }
             String kelasDatabase=namaHakKelasV24(hakNormal,hakNormal);
             if(!kelasDatabase.equals(kelasTujuan)){
                 throw new SQLException("Kelas kamar yang dipilih sudah berubah dan tidak sesuai hak kelas pasien.");
             }
             String penghuniLain=getDaftarPasienAktifLainTerkunci(kodeKamarAsal,noRawat);
             String statusAsalAkhir=penghuniLain.equals("")?"KOSONG":"ISI";
             double tarifTujuan=getTarifKamarTransaksi(tujuan.kodeKamar,noRawat);

             simpanAuditPindahTransaksi(2,asal,tujuan.kodeKamar,tarifTujuan,
                     asal.tanggalMasuk,asal.jamMasuk,statusAsal,statusTujuan,penghuniLain);
             try(PreparedStatement ubah=koneksi.prepareStatement(
                     "update kamar_inap set kd_kamar=?,trf_kamar=?,lama=1,ttl_biaya=? "+
                     "where no_rawat=? and kd_kamar=? and tgl_masuk=? and jam_masuk=? and stts_pulang='-'")){
                 ubah.setString(1,tujuan.kodeKamar);
                 ubah.setDouble(2,tarifTujuan);
                 ubah.setDouble(3,tarifTujuan);
                 ubah.setString(4,noRawat);
                 ubah.setString(5,kodeKamarAsal);
                 ubah.setString(6,tanggalMasuk);
                 ubah.setString(7,jamMasuk);
                 pastikanSatuBaris(ubah.executeUpdate(),"menyesuaikan kamar aktif ke hak kelas");
             }
             ubahStatusKamarTransaksi(kodeKamarAsal,statusAsalAkhir);
             ubahStatusKamarTransaksi(tujuan.kodeKamar,"ISI");

             int aktifTujuan=0;
             try(PreparedStatement cek=koneksi.prepareStatement(
                     "select count(*) from kamar_inap where no_rawat=? and kd_kamar=? and stts_pulang='-' for update")){
                 cek.setString(1,noRawat);
                 cek.setString(2,tujuan.kodeKamar);
                 try(ResultSet hasil=cek.executeQuery()){
                     if(hasil.next()) aktifTujuan=hasil.getInt(1);
                 }
             }
             if(aktifTujuan!=1){
                 throw new SQLException("Verifikasi penyesuaian hak kelas gagal.");
             }
             koneksi.commit();
             System.out.println("AUTO PENYESUAIAN HAK KELAS V24 ["+alasan+"] no_rawat="+
                     noRawat+" "+kodeKamarAsal+" -> "+tujuan.kodeKamar+" hak="+hakNormal);
             return true;
         }catch(Exception e){
             if(transaksiDimulai){
                 try{koneksi.rollback();}catch(Exception er){
                     System.out.println("Rollback penyesuaian hak kelas V24 : "+er);
                 }
             }
             tampilkanDialogStatusBPJSModernV27(
                     "Penyesuaian Hak Kelas Gagal",
                     "Penyesuaian dibatalkan dan data kamar sebelumnya tetap dipertahankan.",
                     "Penyesuaian hak kelas dibatalkan. Data kamar sebelumnya tetap dipertahankan.\n\n"+
                     "Penyebab: "+(e.getMessage()==null?e.toString():e.getMessage()),
                     true);
             return false;
         }finally{
             if(transaksiDimulai){
                 try{koneksi.setAutoCommit(autoCommitSebelumnya);}catch(Exception e){
                     System.out.println("Restore autocommit hak kelas V24 : "+e);
                 }
             }
         }
     }

