     private void perbaruiTampilanPindahKamar() {
         if(lblStatusKamarTujuanPindah==null){
             return;
         }

         lblKamarAsalPindah.setText(formatNamaKamarBertingkatPindah(
                 pindahNamaKamarAsal.equals("")?"-":pindahNamaKamarAsal));
         lblKamarAsalPindah.setToolTipText(pindahNamaKamarAsal.equals("")?"Kamar pasien saat ini":pindahNamaKamarAsal);
         lblWaktuMasukAsalPindah.setText(formatWaktuPindah(pindahTglMasukAsal,pindahJamMasukAsal));
         lblTarifAsalPindah.setText("Rp"+formatAngkaPindah(pindahTarifAsal));
         lblNoRawatIdentitasPindah.setText(norawatpindah.getText().trim().equals("")?"-":norawatpindah.getText().trim());
         lblNoRMIdentitasPindah.setText(TNoRMpindah.getText().trim().equals("")?"-":TNoRMpindah.getText().trim());
         lblNamaIdentitasPindah.setText(TPasienpindah.getText().trim().equals("")?"-":TPasienpindah.getText().trim());
         lblTanggalMasukPasienPindah.setText(
                 formatWaktuPindah(pindahTglMasukAsal,pindahJamMasukAsal));
         lblTarifPasienPindah.setText("Rp"+formatAngkaPindah(pindahTarifAsal));
         if(panelIdentitasPindahForm!=null){
             panelIdentitasPindahForm.revalidate();
             panelIdentitasPindahForm.repaint();
         }
         lblWaktuHeaderPindah.setText(new java.text.SimpleDateFormat(
                 "dd MMMM yyyy HH:mm:ss",new java.util.Locale("id","ID")).format(new java.util.Date()));

         String status=TSttsKamarpindah.getText().trim();
         if(status.equals("KOSONG")){
             lblStatusKamarTujuanPindah.setText("KOSONG");
             lblStatusKamarTujuanPindah.setForeground(new java.awt.Color(22,112,74));
             lblStatusKamarTujuanPindah.setBackground(new java.awt.Color(225,247,237));
         }else if(status.equals("ISI")){
             lblStatusKamarTujuanPindah.setText("TERISI");
             lblStatusKamarTujuanPindah.setForeground(new java.awt.Color(176,55,55));
             lblStatusKamarTujuanPindah.setBackground(new java.awt.Color(255,235,235));
         }else{
             lblStatusKamarTujuanPindah.setText("BELUM DIPILIH");
             lblStatusKamarTujuanPindah.setForeground(new java.awt.Color(104,114,126));
             lblStatusKamarTujuanPindah.setBackground(new java.awt.Color(239,242,246));
         }
         lblStatusKamarTujuanPindah.repaint();

         double tarifTujuan=parseAngkaPindah(TTarifpindah.getText());
         lblTarifTujuanPindah.setText("Rp"+formatAngkaPindah(tarifTujuan));
         lblPerhitunganBiayaPindah.setText("Perkiraan kamar tujuan: 1 hari \u00d7 Rp"+
                 formatAngkaPindah(tarifTujuan)+" = Rp"+formatAngkaPindah(tarifTujuan));

         boolean pilihanDua=Rganti2.isSelected();
         CmbTglpindah.setEnabled(!prosesPindahKamar&&!pilihanDua);
         CmbBlnpindah.setEnabled(!prosesPindahKamar&&!pilihanDua);
         CmbTahunpindah.setEnabled(!prosesPindahKamar&&!pilihanDua);
         cmbJampindah.setEnabled(!prosesPindahKamar&&!pilihanDua);
         cmbMntpindah.setEnabled(!prosesPindahKamar&&!pilihanDua);
         cmbDtkpindah.setEnabled(!prosesPindahKamar&&!pilihanDua);

         String waktu=formatWaktuPindah(getTanggalPindah(),getJamPindah());
         if(lblWaktuMasukTujuanV38!=null){
             lblWaktuMasukTujuanV38.setText(Rganti2.isSelected()?"Tetap waktu masuk awal":waktu);
         }
         if(Rganti1.isSelected()){
             lblInfoPilihanPindah.setText("<html>Riwayat kamar lama dihapus <b>hanya setelah</b> kamar baru berhasil disimpan.</html>");
             lblRingkasanKeluarPindah.setText("<html>Kamar saat ini : <b>dihapus setelah transaksi berhasil</b></html>");
             lblRingkasanMasukPindah.setText("Kamar tujuan masuk : "+waktu);
         }else if(Rganti2.isSelected()){
             lblInfoPilihanPindah.setText("<html>Record kamar aktif diganti ke kamar tujuan dan tarif menyesuaikan.</html>");
             lblRingkasanKeluarPindah.setText("<html>Waktu masuk awal tetap : <font color='#0869D6'><b>"+
                     formatWaktuPindah(pindahTglMasukAsal,pindahJamMasukAsal)+"</b></font></html>");
             lblRingkasanMasukPindah.setText("Tidak membuat baris riwayat kamar baru");
         }else if(Rganti4.isSelected()){
             lblInfoPilihanPindah.setText("<html>Kamar lama ditutup dan dihitung menggunakan tarif kamar yang lebih tinggi.</html>");
             lblRingkasanKeluarPindah.setText("<html>Kamar saat ini keluar / kamar tujuan masuk : <font color='#0869D6'><b>"+
                     waktu+"</b></font></html>");
             lblRingkasanMasukPindah.setText("Kamar tujuan masuk : "+waktu);
         }else{
             lblInfoPilihanPindah.setText(
                     "<html>Kamar lama ditutup, kamar baru dimulai pada waktu yang sama, tarif masing-masing tetap.</html>");
             lblRingkasanKeluarPindah.setText("<html>Kamar saat ini keluar / kamar tujuan masuk : <font color='#0869D6'><b>"+
                     waktu+"</b></font></html>");
             lblRingkasanMasukPindah.setText("Kamar tujuan masuk : "+waktu);
         }

         String pesan=validasiAwalPindahKamar();
         boolean valid=pesan.equals("");
         boolean punyaHakAkses=akses.getkamar_inap();
         BtnSimpanpindah.setEnabled(!prosesPindahKamar&&valid&&punyaHakAkses);
         if(btnAksiPindahVisual!=null){
             btnAksiPindahVisual.setEnabled(!prosesPindahKamar&&valid&&punyaHakAkses);
         }
         if(btnBatalPindahVisual!=null){
             btnBatalPindahVisual.setEnabled(!prosesPindahKamar);
         }
         if(!punyaHakAkses){
             lblValidasiPindah.setText("User tidak memiliki hak akses untuk memindahkan kamar pasien.");
             lblValidasiPindah.setForeground(new java.awt.Color(176,55,55));
             return;
         }
         if(valid){
             lblValidasiPindah.setText("Siap dipindahkan. Seluruh perubahan akan dibatalkan otomatis jika proses gagal.");
             lblValidasiPindah.setForeground(new java.awt.Color(22,112,74));
         }else{
             lblValidasiPindah.setText(pesan);
             lblValidasiPindah.setForeground(new java.awt.Color(166,103,25));
         }
     }

     private String getTanggalPindah() {
         return CmbTahunpindah.getSelectedItem()+"-"+CmbBlnpindah.getSelectedItem()+"-"+CmbTglpindah.getSelectedItem();
     }

     private String getJamPindah() {
         return cmbJampindah.getSelectedItem()+":"+cmbMntpindah.getSelectedItem()+":"+cmbDtkpindah.getSelectedItem();
     }

     private LocalDateTime getDateTimePindah() {
         return LocalDateTime.parse(getTanggalPindah()+" "+getJamPindah(),
                 DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm:ss"));
     }

     private LocalDateTime getDateTimeMasukAsalPindah() {
         return LocalDateTime.parse(pindahTglMasukAsal+" "+pindahJamMasukAsal,
                 DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm:ss"));
     }

     private String validasiAwalPindahKamar() {
         if(pindahNoRawatAsal.equals("")||TPasienpindah.getText().trim().equals("")){
             return "Data pasien asal belum lengkap.";
         }
         if(kdkamarpindah.getText().trim().equals("")||TKdBngsalpindah.getText().trim().equals("")){
             return "Pilih kamar tujuan terlebih dahulu.";
         }
         if(kdkamarpindah.getText().trim().equals(pindahKdKamarAsal)){
             return "Kamar tujuan tidak boleh sama dengan kamar saat ini.";
         }
         if(!TSttsKamarpindah.getText().trim().equals("KOSONG")){
             return "Kamar tujuan harus berstatus KOSONG.";
         }
         if(!Rganti2.isSelected()){
             try{
                 LocalDateTime waktuPindah=getDateTimePindah();
                 if(waktuPindah.isBefore(getDateTimeMasukAsalPindah())){
                     return "Waktu pindah tidak boleh lebih awal dari waktu masuk kamar saat ini.";
                 }
                 if(waktuPindah.isAfter(LocalDateTime.now())){
                     return "Waktu pindah tidak boleh melebihi waktu saat ini.";
                 }
             }catch(Exception e){
                 return "Tanggal atau jam pemindahan tidak valid.";
             }
         }
         return "";
     }

     private String formatWaktuPindah(String tanggal,String jam) {
         try{
             LocalDateTime nilai=LocalDateTime.parse(tanggal+" "+jam,
                     DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm:ss"));
             return nilai.format(DateTimeFormatter.ofPattern("dd-MM-yyyy HH:mm:ss"));
         }catch(Exception e){
             return "-";
         }
     }

     private double parseAngkaPindah(String nilai) {
         try{
             return Double.parseDouble(nilai.replace(",","").trim());
         }catch(Exception e){
             return 0;
         }
     }

     private String formatAngkaPindah(double nilai) {
         return new DecimalFormat("#,##0").format(nilai);
     }
 

     /**
      * Membuat modul billing Ranap hanya saat dibutuhkan. Constructor modul ini
      * memuat banyak form turunan dan sebelumnya menahan pembukaan Rawat Inap.
      */
     /**
      * V37 - kompatibilitas DlgKamarInap dengan DlgBilingRanap yang memakai
      * lazy initialization. Event/action lama DlgKamarInap tetap dibiarkan
      * persis seperti sebelum V35/V36; helper ini hanya memastikan field
      * dialog pendukung Billing sudah dibuat melalui getter milik Billing.
      */
     private void pastikanDialogPendukungBillingV37(DlgBilingRanap dialog) {
         if(dialog==null){
             return;
         }
         pastikanGetterLazyBillingV37(dialog,"getRawatInap",dialog.rawatinap==null);
         pastikanGetterLazyBillingV37(dialog,"getCaraBayar",dialog.carabayar==null);
         pastikanGetterLazyBillingV37(dialog,"getBeriObat",dialog.beriobat==null);
         pastikanGetterLazyBillingV37(dialog,"getDeposit",dialog.deposit==null);
     }

     private void pastikanGetterLazyBillingV37(DlgBilingRanap dialog,
             String namaMethod,boolean perluDibuat) {
         if(!perluDibuat){
             return;
         }
         try{
             java.lang.reflect.Method method=dialog.getClass().getDeclaredMethod(namaMethod);
             if(!method.isAccessible()){
                 method.setAccessible(true);
             }
             method.invoke(dialog);
         }catch(Exception ex){
             System.out.println("V37 - gagal menyiapkan "+namaMethod+" DlgBilingRanap : "+ex);
         }
     }

