     /**
      * Lifecycle DlgRawatInap mengikuti pola source resmi SIMRS Khanza:
      * dibuat langsung saat diperlukan, dilepas saat ditutup, dan tidak
      * melewati constructor DlgBilingRanap.
      */
     private DlgRawatInap getFormRawatInap() {
         if (formrawatinap == null || !formrawatinap.isDisplayable()) {
             final long mulaiConstructorRawatV52=System.nanoTime();
             formrawatinap=new DlgRawatInap(null,false);
             System.out.println("[PERFORMA RAWAT INAP V52] Constructor DlgRawatInap: "+
                     ((System.nanoTime()-mulaiConstructorRawatV52)/1_000_000L)+" ms");
             formrawatinap.setDefaultCloseOperation(javax.swing.WindowConstants.DISPOSE_ON_CLOSE);
             formrawatinap.addWindowListener(new java.awt.event.WindowAdapter() {
                 @Override
                 public void windowClosed(WindowEvent e) {
                     formrawatinap=null;
                     if(akses.getform().equals("DlgKamarInap")){
                         tbKamIn.requestFocus();
                     }
                 }
             });
             formrawatinap.setSize(internalFrame1.getWidth()-20,internalFrame1.getHeight()-20);
             formrawatinap.setLocationRelativeTo(internalFrame1);
         }
         return formrawatinap;
     }

     /** Menyiapkan pasien terpilih dengan urutan lifecycle source resmi. */
     private void bukaFormRawatInap(String noRawatTerpilih,int barisTabel) {
         DlgRawatInap dialog=getFormRawatInap();
         if(dialog==null){
             return;
         }
         if(!dialog.isVisible()){
             final long mulaiPersiapanRawatV52=System.nanoTime();
             final long mulaiCekRawatV52=System.nanoTime();
             dialog.isCek();
             System.out.println("[PERFORMA RAWAT INAP V52] isCek: "+
                     ((System.nanoTime()-mulaiCekRawatV52)/1_000_000L)+" ms");
             dialog.setKamar(tbKamIn.getValueAt(barisTabel,7).toString());
             dialog.setJenisBayar(tbKamIn.getValueAt(barisTabel,6).toString());
             if(R1.isSelected()==true){
                 dialog.setNoRm(noRawatTerpilih,new Date(),new Date());
             }else if(R2.isSelected()==true){
                 dialog.setNoRm(noRawatTerpilih,DTPCari1.getDate(),DTPCari2.getDate());
             }else if(R3.isSelected()==true){
                 dialog.setNoRm(noRawatTerpilih,DTPCari3.getDate(),DTPCari4.getDate());
             }
             System.out.println("[PERFORMA RAWAT INAP V52] Total persiapan sebelum setVisible: "+
                     ((System.nanoTime()-mulaiPersiapanRawatV52)/1_000_000L)+" ms");
         }
         if(dialog.isVisible()){
             dialog.toFront();
             return;
         }
         dialog.setVisible(true);
     }

