     /** Membuat form diagnosa hanya ketika fitur diagnosa dipakai. */
     public DlgDiagnosaPenyakit getDiagnosa() {
         if (diagnosa == null) {
             final long mulai = System.nanoTime();
             final DlgDiagnosaPenyakit dialog = new DlgDiagnosaPenyakit(null,false);
             diagnosa = dialog;
             dialog.addWindowListener(new WindowListener() {
                 @Override
                 public void windowOpened(WindowEvent e) {}
                 @Override
                 public void windowClosing(WindowEvent e) {}
                 @Override
                 public void windowClosed(WindowEvent e) {
                     if(akses.getform().equals("DlgKamarInap")){
                         try {
                             key="";
                             psdiagnosa=koneksi.prepareStatement("select diagnosa_pasien.kd_penyakit from diagnosa_pasien where diagnosa_pasien.no_rawat=? order by diagnosa_pasien.prioritas asc");
                             try{
                                 psdiagnosa.setString(1,norawat.getText());
                                 rs=psdiagnosa.executeQuery();                    
                                 while(rs.next()){
                                     key=rs.getString(1)+", "+key;
                                 }
                             }catch(Exception ex){
                                 System.out.println("Notifikasi : "+ex);
                             }finally{
                                 if(rs != null){
                                     rs.close();
                                 }
                                 if(psdiagnosa != null){
                                     psdiagnosa.close();
                                 }
                             }
                         } catch (Exception ex) {
                             System.out.println(ex);
                         }
                         
                         if(WindowInputKamar.isVisible()||halamanPemulanganTerbuka){
                             diagnosaakhir.setText(key);
                             diagnosaakhir.requestFocus();
                         }else{
                             if(Sequel.mengedittf("kamar_inap","no_rawat='"+norawat.getText()+"' and kd_kamar='"+kdkamar.getText()+"' and tgl_masuk='"+TIn.getText()+"' and jam_masuk='"+JamMasuk.getText()+"'","diagnosa_akhir='"+key+"'")==true){
                                 if(tbKamIn.getSelectedRow()!= -1){
                                     tbKamIn.setValueAt(key,tbKamIn.getSelectedRow(),10);
                                 }
                             }
                         }                    
                     }
                 }
                 @Override
                 public void windowIconified(WindowEvent e) {}
                 @Override
                 public void windowDeiconified(WindowEvent e) {}
                 @Override
                 public void windowActivated(WindowEvent e) {}
                 @Override
                 public void windowDeactivated(WindowEvent e) {}
             });
             

             System.out.println("[PERFORMA MODUL] Diagnosa Ranap siap dalam " +
                     ((System.nanoTime()-mulai)/1_000_000L) + " ms");
         }
         return diagnosa;
     }

     /** Membuat pencarian registrasi hanya ketika pasien akan dipilih. */
     private DlgCariReg getReg() {
         if (reg == null) {
             final long mulai = System.nanoTime();
             final DlgCariReg dialog = new DlgCariReg(null,false);
             reg = dialog;
             dialog.addWindowListener(new WindowListener() {
                 @Override
                 public void windowOpened(WindowEvent e) {}
                 @Override
                 public void windowClosing(WindowEvent e) {}
                 @Override
                 public void windowClosed(WindowEvent e) {
                     if(akses.getform().equals("DlgKamarInap")){
                         if(dialog.getTable().getSelectedRow()!= -1){  
                             if(Sequel.cariRegistrasi(dialog.getTable().getValueAt(dialog.getTable().getSelectedRow(),1).toString())>0){
                                 JOptionPane.showMessageDialog(rootPane,"Data billing sudah terverifikasi.\nSilahkan hubungi bagian kasir/keuangan ..!!");
                                 TCari.requestFocus();
                             }else{
                                 norawat.setText(dialog.getTable().getValueAt(dialog.getTable().getSelectedRow(),1).toString());
                                 TNoRM.setText(dialog.getTable().getValueAt(dialog.getTable().getSelectedRow(),6).toString());
                                 TPasien.setText(dialog.getTable().getValueAt(dialog.getTable().getSelectedRow(),7).toString());
                                 if(Sequel.cariInteger("select count(pasien.no_rkm_medis) from pasien inner join reg_periksa inner join kamar_inap "+
                                         "on reg_periksa.no_rkm_medis=pasien.no_rkm_medis and reg_periksa.no_rawat=kamar_inap.no_rawat "+
                                         "where kamar_inap.stts_pulang='-' and pasien.no_rkm_medis=?",TNoRM.getText())>0){
                                    JOptionPane.showMessageDialog(null,"Pasien sedang dalam masa perawatan di kamar inap..!!");
                                    norawat.setText("");
                                    TNoRM.setText("");
                                    TPasien.setText("");
                                    TNoRM.requestFocus();
                                }
                             }
                         }                
                     }
                 }
                 @Override
                 public void windowIconified(WindowEvent e) {}
                 @Override
                 public void windowDeiconified(WindowEvent e) {}
                 @Override
                 public void windowActivated(WindowEvent e) {}
                 @Override
                 public void windowDeactivated(WindowEvent e) {}
             });  
             
             dialog.getTable().addKeyListener(new KeyListener() {
                 @Override
                 public void keyTyped(KeyEvent e) {}
                 @Override
                 public void keyPressed(KeyEvent e) {
                     if(akses.getform().equals("DlgKamarInap")){
                         dialog.dispose();
                     }
                 }
                 @Override
                 public void keyReleased(KeyEvent e) {}
             });
             

             System.out.println("[PERFORMA MODUL] Pencarian registrasi Ranap siap dalam " +
                     ((System.nanoTime()-mulai)/1_000_000L) + " ms");
         }
         return reg;
     }

