     /**
      * V34 - lama inap mengikuti selisih tanggal pulang - tanggal masuk.
      * Minimum 1 hari untuk pasien yang masuk dan pulang pada tanggal yang sama.
      * Jam tidak menambah hari agar kamar_inap.lama dan billing konsisten.
      */
     private int hitungLamaInapTanggalV34(String tanggalMasuk,String tanggalPulang) {
         try{
             java.time.LocalDate masuk=java.time.LocalDate.parse(tanggalMasuk);
             java.time.LocalDate pulang=java.time.LocalDate.parse(tanggalPulang);
             long selisih=java.time.temporal.ChronoUnit.DAYS.between(masuk,pulang);
             return selisih<=0?1:(int)selisih;
         }catch(Exception e){
             System.out.println("V34 hitung lama inap : "+e);
             return 1;
         }
     }

     private void perbaruiLamaInapPemulanganV34() {
         if(TIn==null||TIn.getText()==null||TIn.getText().trim().equals("")){
             return;
         }
         if(CmbTahun.getSelectedItem()==null||CmbBln.getSelectedItem()==null||
                 CmbTgl.getSelectedItem()==null){
             return;
         }
         String tanggalPulang=CmbTahun.getSelectedItem().toString()+"-"+
                 CmbBln.getSelectedItem().toString()+"-"+
                 CmbTgl.getSelectedItem().toString();
         int lamaInap=hitungLamaInapTanggalV34(TIn.getText().trim(),tanggalPulang);
         TJmlHari.setText(String.valueOf(lamaInap));
         isjml();
         if(lblStatusValidasiPulang!=null&&halamanPemulanganTerbuka){
             lblStatusValidasiPulang.setText(
                     "Lama inap dihitung dari selisih tanggal masuk dan tanggal pulang: "+lamaInap+" hari.");
         }
     }

     private void BtnOutActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_BtnOutActionPerformed
         if(tabMode.getRowCount()==0){
             JOptionPane.showMessageDialog(null,"Maaf, data kamar inap pasien sudah habis...!!!!");
             BtnIn.requestFocus();
         }else if(norawat.getText().trim().equals("")){
             JOptionPane.showMessageDialog(null,"Maaf, Silahkan anda pilih dulu data inap pasien yang mau pulang dengan menklik data pada table...!!!");
             tbKamIn.requestFocus();
         }else if(TOut.getText().trim().length()>0){
                  JOptionPane.showMessageDialog(null,"Maaf, pasien ini sudah pulang pada tanggal "+TOut.getText()+" ...!!!");
                  emptTeks();
                  tbKamIn.requestFocus();
         }else if((TOut.getText().length()==0)&&(norawat.getText().length()>0)){
                 norawat.setEditable(false);
                 kdkamar.setEditable(false);
                 i=1;
                 isKmr();
                 diagnosaawal.setEditable(false);                
                 diagnosaakhir.setVisible(true);                
                 btnDiagnosa.setVisible(true);
                 jLabel23.setVisible(true);
                 diagnosaakhir.setText("");
                 cmbStatus.setVisible(true);
                 jLabel26.setVisible(true);
//                 BtnUpPlgBPJS.setEnabled(false);
                 lama=Sequel.cariIsiAngka("select set_jam_minimal.lamajam from set_jam_minimal");
                 hariawal=Sequel.cariIsi("select set_jam_minimal.hariawal from set_jam_minimal");
                 LblStts.setText("Pulang / Check Out");
                 btnReg.setEnabled(false);
                 btnKamar.setEnabled(false);
                 date = new Date();
                 now=dateFormat.format(date);
                 CmbTahun.setSelectedItem(now.substring(0,4));
                 CmbBln.setSelectedItem(now.substring(5,7));
                 CmbTgl.setSelectedItem(now.substring(8,10));
                 cmbJam.setSelectedItem(now.substring(11,13));
                 cmbMnt.setSelectedItem(now.substring(14,16));
                 cmbDtk.setSelectedItem(now.substring(17,19));  
                 tglmasuk=TIn.getText();
                 jammasuk=JamMasuk.getText();
                 // V34: lama inap tidak lagi ditambah 1 berdasarkan hariawal.
                 perbaruiLamaInapPemulanganV34();
                 
                 norawat.requestFocus();   
                 isjml();    
                 
                 // Sebelum tampilkan form
                sedangMemuatForm = true;
                sudahCekStatusBayar = false; // reset flag
                BtnUpPlgBPJS.setEnabled(false);
                cekStatusBayarBPJS(norawat.getText());

                // Tampilkan sebagai halaman terintegrasi di DlgKamarInap.
                System.out.println("DEBUG: sebelum halaman pemulangan, sedangMemuatForm = " + sedangMemuatForm);
                tampilkanHalamanPemulanganTerintegrasi();
                System.out.println("DEBUG: setelah halaman pemulangan, sedangMemuatForm = " + sedangMemuatForm);

                // BARU SELESAIKAN LOADING
                sedangMemuatForm = false;
         }
         System.out.println("DEBUG: saat buka form, BtnUpPlgBPJS enabled = " + BtnUpPlgBPJS.isEnabled());

 }//GEN-LAST:event_BtnOutActionPerformed
 
