     /**
      * V21 - selection JTable dapat menjadi -1 ketika CardLayout berpindah ke
      * halaman Pemulangan. Cari baris model berdasarkan No. Rawat agar
      * penghapusan baris setelah checkout tidak pernah memanggil removeRow(-1).
      */
     /** V22 - memastikan penjamin pasien adalah BPJS tanpa bergantung selection JTable. */
     private boolean adalahPasienBPJSPemulangan(String noRawat) {
         if(noRawat==null||noRawat.trim().equals("")){
             return false;
         }
         try{
             String kdPj=Sequel.cariIsi(
                     "select reg_periksa.kd_pj from reg_periksa where reg_periksa.no_rawat=?",
                     noRawat.trim());
             return "BPJ".equalsIgnoreCase(kdPj==null?"":kdPj.trim());
         }catch(Exception e){
             System.out.println("V23 cek penjamin BPJS pemulangan : "+e);
             return false;
         }
     }

     private String validasiDataUpdatePulangBPJS() {
         if(norawat.getText().trim().equals("")||TPasien.getText().trim().equals("")){
             return "Data pasien belum lengkap.";
         }
         if(SEP.getText().trim().equals("")){
             return "Nomor SEP belum tersedia.";
         }
         if(NoKartu.getText().trim().equals("")){
             return "Nomor Kartu BPJS belum tersedia.";
         }
         if(StatusPulang.getSelectedItem()==null||
                 StatusPulang.getSelectedItem().toString().trim().equals("")){
             return "Status Pulang BPJS belum dipilih.";
         }
         return "";
     }

     /** Snapshot seluruh nilai Swing sebelum request dijalankan di background. */
     private DataUpdatePulangBPJS ambilDataUpdatePulangBPJS() {
         DataUpdatePulangBPJS data=new DataUpdatePulangBPJS();
         data.noRawat=norawat.getText().trim();
         data.noSep=SEP.getText().trim();
         data.noKartu=NoKartu.getText().trim();
         String status=StatusPulang.getSelectedItem()==null?"":
                 StatusPulang.getSelectedItem().toString().trim();
         data.statusPulang=status.equals("")?"":status.substring(0,1);
         data.tglPulang=CmbTahun.getSelectedItem()+"-"+
                 CmbBln.getSelectedItem()+"-"+CmbTgl.getSelectedItem();
         data.jamPulang=cmbJam.getSelectedItem()+":"+
                 cmbMnt.getSelectedItem()+":"+cmbDtk.getSelectedItem();
         data.noSuratMeninggal=NoSuratKematian.getText().trim();
         data.tglMeninggal=TanggalKematian.isEnabled()?
                 Valid.SetTgl(TanggalKematian.getSelectedItem()+""):"";
         data.noLPManual=NoLPManual.getText().trim();
         data.user=akses.getkode();
         return data;
     }

     /**
      * Request BPJS murni. Tidak menampilkan dialog Swing agar aman dipanggil
      * dari SwingWorker#doInBackground().
      */
     private boolean adalahExpireServiceBPJSV32(HasilUpdatePulangBPJS hasil) {
         if(hasil==null){
             return false;
         }
         String pesan=(hasil.pesan==null?"":hasil.pesan).toLowerCase(java.util.Locale.ROOT);
         return pesan.contains("expire service")||pesan.contains("service expired")||
                 pesan.contains("expired service")||pesan.contains("service expire");
     }

     /**
      * V32 - request BPJS tetap memakai payload/alur lama, tetapi bila BPJS
      * menjawab "expire service" satu kali, request diulang sekali dengan
      * X-Timestamp dan X-Signature BARU. Tidak ada retry untuk error bisnis lain.
      */
     private HasilUpdatePulangBPJS kirimUpdatePulangBPJS(DataUpdatePulangBPJS data) {
         HasilUpdatePulangBPJS hasil=new HasilUpdatePulangBPJS();
         for(int percobaan=1;percobaan<=2;percobaan++){
             try{
                 HttpHeaders headerLokal=new HttpHeaders();
                 headerLokal.setContentType(MediaType.APPLICATION_FORM_URLENCODED);
                 headerLokal.add("X-Cons-ID",koneksiDB.CONSIDAPIBPJS());
                 String utcLokal=String.valueOf(api.GetUTCdatetimeAsString());
                 headerLokal.add("X-Timestamp",utcLokal);
                 headerLokal.add("X-Signature",api.getHmac(utcLokal));
                 headerLokal.add("user_key",koneksiDB.USERKEYAPIBPJS());

                 String urlLokal=link+"/SEP/2.0/updtglplg";
                 String jsonLokal="{"+
                         "\"request\":{"+
                         "\"t_sep\":{"+
                         "\"noSep\":\""+data.noSep+"\","+
                         "\"statusPulang\":\""+data.statusPulang+"\","+
                         "\"noSuratMeninggal\":\""+data.noSuratMeninggal+"\","+
                         "\"tglMeninggal\":\""+data.tglMeninggal+"\","+
                         "\"tglPulang\":\""+data.tglPulang+"\","+
                         "\"noLPManual\":\""+data.noLPManual+"\","+
                         "\"user\":\""+data.user+"\""+
                         "}}}";
                 System.out.println("V32 JSON Update Pulang BPJS percobaan "+percobaan+" : "+jsonLokal);
                 System.out.println("V32 X-Timestamp BPJS percobaan "+percobaan+" : "+utcLokal);
                 HttpEntity requestLokal=new HttpEntity(jsonLokal,headerLokal);
                 com.fasterxml.jackson.databind.JsonNode rootLokal=mapper.readTree(
                         api.getRest().exchange(urlLokal,HttpMethod.PUT,requestLokal,String.class)
                                 .getBody());
                 com.fasterxml.jackson.databind.JsonNode metadata=rootLokal.path("metaData");
                 hasil.kode=metadata.path("code").asText();
                 hasil.pesan=metadata.path("message").asText();
                 hasil.sukses="200".equals(hasil.kode);
                 System.out.println("V32 Update Pulang BPJS code percobaan "+percobaan+" : "+hasil.kode);
                 System.out.println("V32 Update Pulang BPJS message percobaan "+percobaan+" : "+hasil.pesan);

                 if(hasil.sukses){
                     Sequel.mengedit("bridging_sep","no_sep=?","tglpulang=?",2,
                             new String[]{data.tglPulang+" "+data.jamPulang,data.noSep});
                     LocalDateTime now=LocalDateTime.now();
                     String waktu=now.format(DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm:ss"));
                     String ipKomputer=InetAddress.getLocalHost().getHostAddress();
                     String insertQuery="INSERT INTO rsaj_update_pulang_bpjs "+
                             "(no_rawat, no_sep, waktu, petugas, ip_komputer) VALUES (?,?,?,?,?)";
                     String[] params={data.noRawat,data.noSep,waktu,data.user,ipKomputer};
                     Sequel.queryu2(insertQuery,params.length,params);
                     return hasil;
                 }

                 if(percobaan==1&&adalahExpireServiceBPJSV32(hasil)){
                     System.out.println("V32 BPJS expire service, ulang sekali dengan timestamp/signature baru.");
                     try{Thread.sleep(250L);}catch(InterruptedException ie){
                         Thread.currentThread().interrupt();
                     }
                     continue;
                 }
                 break;
             }catch(Exception ex){
                 hasil.sukses=false;
                 hasil.kode="EXCEPTION";
                 if(ex.toString().contains("UnknownHostException")){
                     hasil.pesan="Koneksi ke server BPJS terputus.";
                 }else if(ex.getMessage()!=null&&!ex.getMessage().trim().equals("")){
                     hasil.pesan=ex.getMessage().trim();
                 }else{
                     hasil.pesan=ex.toString();
                 }
                 System.out.println("Notifikasi Bridging Update Pulang V32 percobaan "+percobaan+" : "+ex);
                 break;
             }
         }
         if(!hasil.sukses&&adalahExpireServiceBPJSV32(hasil)){
             hasil.pesan=(hasil.pesan==null?"":hasil.pesan.trim())+
                     "\nPeriksa sinkronisasi tanggal/jam komputer atau server SIMRS. " +
                     "Request sudah dicoba ulang dengan timestamp/signature baru.";
         }
         return hasil;
     }

     /** V28 - overlay khusus status BPJS: hanya meredupkan background. */
     private java.awt.Component tampilkanOverlayBuramStatusBPJSV28() {
         final java.awt.Component glassPaneSebelumnya=DlgKamarInap.this.getGlassPane();
         javax.swing.JComponent overlay=new javax.swing.JComponent() {
             private static final long serialVersionUID=1L;
             @Override
             protected void paintComponent(java.awt.Graphics g) {
                 java.awt.Graphics2D g2=(java.awt.Graphics2D)g.create();
                 try{
                     g2.setColor(new java.awt.Color(245,248,252,118));
                     g2.fillRect(0,0,getWidth(),getHeight());
                     g2.setColor(new java.awt.Color(15,23,42,42));
                     g2.fillRect(0,0,getWidth(),getHeight());
                 }finally{
                     g2.dispose();
                 }
             }
         };
         overlay.setOpaque(false);
         overlay.addMouseListener(new java.awt.event.MouseAdapter(){});
         overlay.addMouseMotionListener(new java.awt.event.MouseMotionAdapter(){});
         overlay.addMouseWheelListener(new java.awt.event.MouseWheelListener(){
             @Override public void mouseWheelMoved(java.awt.event.MouseWheelEvent e){}
         });
         DlgKamarInap.this.setGlassPane(overlay);
         overlay.setVisible(true);
         return glassPaneSebelumnya;
     }

