     private void setProsesUpdatePulangBPJS(boolean proses) {
         prosesUpdatePulangBPJS=proses;
         BtnUpPlgBPJS.setEnabled(!proses&&pemulanganLokalSudahBerhasil);
         if(StatusPulang!=null){
             StatusPulang.setEnabled(!proses);
         }
         if(btnUpdatePulangBPJSVisual!=null){
             btnUpdatePulangBPJSVisual.setVisible(false);
         }
         if(btnBatalPulangVisual!=null){
             btnBatalPulangVisual.setEnabled(!proses);
         }
         if(lblStatusValidasiPulang!=null&&proses){
             lblStatusValidasiPulang.setText("Pemulangan berhasil. Sedang memperbarui tanggal pulang BPJS...");
         }
         DlgKamarInap.this.setCursor(java.awt.Cursor.getPredefinedCursor(
                 proses?java.awt.Cursor.WAIT_CURSOR:java.awt.Cursor.DEFAULT_CURSOR));
         perbaruiStatusTombolPemulangan();
     }

     private void selesaiHalamanSetelahPemulanganBerhasil() {
         if(halamanPemulanganTerbuka){
             kembaliKeDaftarKamarDariPemulangan();
         }else{
             WindowInputKamar.dispose();
         }
     }

     /**
      * Menjalankan bridging BPJS di background. otomatisSetelahPulang=true
      * menghasilkan pesan gabungan supaya user tahu data lokal sudah aman.
      */
     private void prosesUpdatePulangBPJSAsync(final boolean otomatisSetelahPulang) {
         if(prosesUpdatePulangBPJS){
             return;
         }
         String validasi=validasiDataUpdatePulangBPJS();
         if(!validasi.equals("")){
             BtnUpPlgBPJS.setEnabled(pemulanganLokalSudahBerhasil);
             perbaruiStatusTombolPemulangan();
             if(otomatisSetelahPulang){
                 if(lblStatusValidasiPulang!=null){
                     lblStatusValidasiPulang.setText(
                             "Pemulangan berhasil, tetapi update BPJS belum dapat diproses.");
                 }
                 tampilkanDialogStatusBPJSModernV27(
                         "Pemulangan Berhasil - BPJS Belum Terupdate",
                         "Data SIMRS sudah aman, tetapi update BPJS belum dapat diproses.",
                         "Pasien berhasil dipulangkan di SIMRS.\n\n"+
                         "Namun update tanggal pulang BPJS belum dapat diproses.\n\n"+
                         "Penyebab: "+validasi+"\n\n"+
                         "Silakan lengkapi data lalu tekan tombol Update Tanggal Pulang BPJS di bagian bawah.",
                         true);
             }else{
                 tampilkanDialogStatusBPJSModernV27(
                         "Update Tanggal Pulang BPJS",
                         "Periksa data yang diperlukan sebelum mencoba kembali.",
                         validasi,true);
             }
             return;
         }

         final DataUpdatePulangBPJS data=ambilDataUpdatePulangBPJS();
         setProsesUpdatePulangBPJS(true);
         new javax.swing.SwingWorker<HasilUpdatePulangBPJS,Void>() {
             @Override
             protected HasilUpdatePulangBPJS doInBackground() {
                 return kirimUpdatePulangBPJS(data);
             }

             @Override
             protected void done() {
                 HasilUpdatePulangBPJS hasil=new HasilUpdatePulangBPJS();
                 try{
                     hasil=get();
                 }catch(Exception e){
                     hasil.sukses=false;
                     hasil.kode="EXCEPTION";
                     hasil.pesan=e.getMessage()==null?e.toString():e.getMessage();
                 }
                 setProsesUpdatePulangBPJS(false);
                 if(hasil.sukses){
                     BtnUpPlgBPJS.setEnabled(false);
                     if(lblStatusValidasiPulang!=null){
                         lblStatusValidasiPulang.setText(
                                 "Pemulangan dan update tanggal pulang BPJS berhasil.");
                     }
                     tampilkanDialogStatusBPJSModernV27(
                             "Berhasil",
                             otomatisSetelahPulang?
                             "Pemulangan dan update BPJS berhasil diselesaikan.":
                             "Tanggal pulang BPJS berhasil diperbarui.",
                             otomatisSetelahPulang?
                             "Pasien berhasil dipulangkan.\n\nTanggal pulang BPJS berhasil diperbarui.":
                             "Update tanggal pulang ke BPJS berhasil.",
                             false);
                     selesaiHalamanSetelahPemulanganBerhasil();
                 }else{
                     BtnUpPlgBPJS.setEnabled(true);
                     if(lblStatusValidasiPulang!=null){
                         lblStatusValidasiPulang.setText(
                                 "Pemulangan berhasil, tetapi update tanggal pulang BPJS gagal. Silakan retry.");
                     }
                     perbaruiStatusTombolPemulangan();
                     String pesan=hasil.pesan==null||hasil.pesan.trim().equals("")?
                             "Tidak ada pesan dari BPJS.":hasil.pesan.trim();
                     tampilkanDialogStatusBPJSModernV27(
                             "Update BPJS Gagal",
                             otomatisSetelahPulang?
                             "Pemulangan lokal berhasil, tetapi pembaruan BPJS belum selesai.":
                             "Pembaruan tanggal pulang BPJS belum berhasil.",
                             otomatisSetelahPulang?
                             "Pasien berhasil dipulangkan di SIMRS.\n\n"+
                             "Namun update tanggal pulang BPJS gagal.\n\n"+
                             "Pesan BPJS: "+pesan+"\n\n"+
                             "Silakan coba kembali melalui tombol Update Tanggal Pulang BPJS di bagian bawah.":
                             "Update tanggal pulang BPJS gagal.\n\nPesan BPJS: "+pesan,
                             true);
                 }
             }
         }.execute();
     }

     private void lanjutSetelahPemulanganLokalBerhasil() {
         pemulanganLokalSudahBerhasil=true;
         perbaruiStatusTombolPemulangan();
         String noRawat=norawat.getText().trim();
         boolean pasienBPJS=adalahPasienBPJSPemulangan(noRawat);
         boolean meninggal=cmbStatus.getSelectedItem()!=null&&
                 "Meninggal".equalsIgnoreCase(cmbStatus.getSelectedItem().toString());

         if(pasienBPJS&&!meninggal){
             // V33: setelah pemulangan lokal berhasil, bridging BPJS TIDAK
             // dijalankan otomatis. User melanjutkan secara manual lewat
             // satu slot tombol utama yang berubah menjadi Update Tgl. Pulang BPJS.
             BtnUpPlgBPJS.setVisible(true);
             StatusPulang.setVisible(true);
             BtnUpPlgBPJS.setEnabled(true);
             perbaruiStatusTombolPemulangan();
             if(lblStatusValidasiPulang!=null){
                 lblStatusValidasiPulang.setText(
                         "Pemulangan berhasil. Silakan lanjutkan Update Tgl. Pulang BPJS.");
             }
             tampilkanDialogStatusBPJSModernV27(
                     "Pemulangan Berhasil",
                     "Data pemulangan pasien di SIMRS sudah berhasil disimpan.",
                     "Pasien berhasil dipulangkan di SIMRS.\n\n"+
                     "Silakan lanjutkan dengan klik tombol Update Tgl. Pulang BPJS.",
                     false);
         }else{
             tampilkanDialogStatusBPJSModernV27(
                     "Pemulangan Berhasil",
                     "Pasien berhasil dipulangkan dari SIMRS.",
                     "Pasien berhasil dipulangkan.",false);
             selesaiHalamanSetelahPemulanganBerhasil();
         }
     }

     private int cariBarisModelRawatInapUntukPulang(String noRawat) {
         if(noRawat==null||noRawat.trim().equals("")){
             return -1;
         }
         int barisView=tbKamIn.getSelectedRow();
         if(barisView>=0){
             try{
                 int barisModel=tbKamIn.convertRowIndexToModel(barisView);
                 if(barisModel>=0&&barisModel<tabMode.getRowCount()){
                     Object nilai=tabMode.getValueAt(barisModel,0);
                     if(nilai!=null&&noRawat.equals(nilai.toString())){
                         return barisModel;
                     }
                 }
             }catch(Exception e){
                 // Fallback pencarian No. Rawat di bawah.
             }
         }
         for(int baris=0;baris<tabMode.getRowCount();baris++){
             Object nilai=tabMode.getValueAt(baris,0);
             if(nilai!=null&&noRawat.equals(nilai.toString())){
                 return baris;
             }
         }
         return -1;
     }

     private void BtnSimpanActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_BtnSimpanActionPerformed

         if(TPasien.getText().trim().equals("")){
             Valid.textKosong(norawat,"pasien");
         }else if(TKdBngsal.getText().trim().equals("")){
             Valid.textKosong(kdkamar,"kamar");
         }else{
             if(norawat.isEditable()==true){
                 if(diagnosaawal.getText().equals("")){
                     Valid.textKosong(diagnosaawal,"diagnosa awal masuk rawat inap");
                 }else{
                     switch (TSttsKamar.getText().trim()) {
                         case "ISI":
                             JOptionPane.showMessageDialog(null,"Maaf, Status kamar sudah terisi silahkan pilih kamar kosong..!!!!");
                             kdkamar.requestFocus();
                             break;
                         case "KOSONG":
                             if(Sequel.menyimpantf("kamar_inap","'"+norawat.getText()+"','"+
                                     kdkamar.getText()+"','"+TTarif.getText()+"','"+
                                     diagnosaawal.getText()+"','"+
                                     diagnosaakhir.getText()+"','"+
                                     CmbTahun.getSelectedItem()+"-"+CmbBln.getSelectedItem()+"-"+CmbTgl.getSelectedItem()+"','"+
                                     cmbJam.getSelectedItem()+":"+cmbMnt.getSelectedItem()+":"+cmbDtk.getSelectedItem()+"','0000-00-00','00:00:00','"+TJmlHari.getText()+"','"+
                                     ttlbiaya.getText()+"','-'","No.Rawat")==true){                                 
                                 Sequel.mengedit("reg_periksa","no_rawat='"+norawat.getText()+"'","status_lanjut='Ranap'");
                                 Sequel.mengedit("kamar","kd_kamar='"+kdkamar.getText()+"'","status='ISI'");                
                                 Sequel.mengedit("permintaan_rawat_inap","no_rawat='"+norawat.getText()+"'","status='Sudah'");
//                                 emptTeks();  
                                 tampil();                                 
                             }                            
                     }
                     norawat.requestFocus();
//                     WindowInputKamar.dispose();
                 }
             }else if(norawat.isEditable()==false){
                 if(cmbStatus.getSelectedItem().equals("-")){
                     Valid.textKosong(cmbStatus,"Status Pulang");
                 }else if(diagnosaakhir.getText().equals("")){
                     Valid.textKosong(diagnosaakhir,"Diagnosa Akhir");
                 }else{
                     // PATCH RSAJ V24: untuk pasien BPJS titipan/kelas aktif yang
                     // tidak sesuai hak kelas, koreksi kamar dilakukan otomatis
                     // sebelum pemulangan. User tetap tidak memperoleh akses manual
                     // ke pilihan 2. Jika user membatalkan, proses pulang berhenti.
                     if(!pastikanHakKelasSebelumPemulanganV24()){
                         return;
                     }

                     // V32: sesudah penyesuaian hak kelas, baca ulang kamar aktif
                     // langsung dari database. Jangan memakai kamar lama dari UI
                     // sebagai kunci checkout.
                     final DataKamarAktifPemulanganV32 kamarAktifPulangV32=
                             ambilKamarAktifPemulanganV32(norawat.getText().trim());
                     if(!kamarAktifPulangV32.valid){
                         tampilkanDialogStatusBPJSModernV27(
                                 "Pemulangan Dibatalkan",
                                 "Kamar aktif pasien tidak dapat dipastikan dengan aman.",
                                 "Sistem tidak menemukan tepat satu kamar aktif untuk pasien ini.\n\n"+
                                 "Pemulangan tidak dilanjutkan agar kamar dan billing tidak salah. " +
                                 "Silakan muat ulang data pasien lalu coba kembali.",true);
                         tampil();
                         return;
                     }
                     if(!kamarHakKelasPemulanganTerakhirV32.equals("")&&
                             !kamarHakKelasPemulanganTerakhirV32.equals(kamarAktifPulangV32.kodeKamar)){
                         tampilkanDialogStatusBPJSModernV27(
                                 "Penyesuaian Kamar Belum Sinkron",
                                 "Pemulangan dihentikan sebelum data BPJS dikirim.",
                                 "Kamar hak kelas yang dipilih adalah "+kamarHakKelasPemulanganTerakhirV32+
                                 ", tetapi kamar aktif di database masih "+kamarAktifPulangV32.kodeKamar+".\n\n"+
                                 "Sistem tidak akan melanjutkan pemulangan sampai kamar aktif sudah benar.",true);
                         tampil();
                         return;
                     }
                     sinkronkanFormPulangDariDatabaseV32(kamarAktifPulangV32);
                     // V34: hitung ulang tepat sebelum UPDATE kamar_inap agar
                     // kamar_inap.lama dan ttl_biaya tidak membawa nilai lama/stale.
                     perbaruiLamaInapPemulanganV34();
                     
                     boolean berhasilMemulangkanPasien = false;
                     final int barisModelPulang=cariBarisModelRawatInapUntukPulang(
                             norawat.getText());
                     
                     if(Sequel.mengedittf("kamar_inap","no_rawat='"+norawat.getText()+"' and kd_kamar='"+kamarAktifPulangV32.kodeKamar+"' and tgl_masuk='"+kamarAktifPulangV32.tglMasuk+"' and jam_masuk='"+kamarAktifPulangV32.jamMasuk+"'",
                             "tgl_keluar='"+CmbTahun.getSelectedItem()+"-"+CmbBln.getSelectedItem()+"-"+CmbTgl.getSelectedItem()+
                             "',trf_kamar='"+TTarif.getText()+"',jam_keluar='"+cmbJam.getSelectedItem()+":"+cmbMnt.getSelectedItem()+":"+cmbDtk.getSelectedItem()+
                             "',ttl_biaya='"+ttlbiaya.getText()+"',stts_pulang='"+cmbStatus.getSelectedItem()+"',diagnosa_akhir='"+diagnosaakhir.getText()+"',lama='"+TJmlHari.getText()+"'")==true){
                         
                         berhasilMemulangkanPasien = true;
                         
                         boolean barisTabelPulangTerhapus=false;
                         if(barisModelPulang>=0&&barisModelPulang<tabMode.getRowCount()){
                             // Khanza kadang menaruh baris anak/kosong tepat setelah baris utama.
                             int barisBerikut=barisModelPulang+1;
                             if(barisBerikut<tabMode.getRowCount()){
                                 Object nilaiBerikut=tabMode.getValueAt(barisBerikut,0);
                                 if(nilaiBerikut==null||nilaiBerikut.toString().trim().equals("")){
                                     tabMode.removeRow(barisBerikut);
                                 }
                             }
                             if(barisModelPulang<tabMode.getRowCount()){
                                 tabMode.removeRow(barisModelPulang);
                                 barisTabelPulangTerhapus=true;
                             }
                         }
                         try {
                             if(cmbStatus.getSelectedItem().equals("Meninggal")){
                                DlgPasienMati formmati = new DlgPasienMati(null, false);                                
                                formmati.setSize(internalFrame1.getWidth() - 20, internalFrame1.getHeight() - 20);
                                formmati.setLocationRelativeTo(internalFrame1);
                                formmati.emptTeks();
                                formmati.setNoRm(TNoRMCari.getText(), TPasienCari.getText(), TNoRwCari.getText());
                                formmati.isCek();
                                SwingUtilities.invokeLater(() -> {
                                    formmati.setVisible(true);
                                    formmati.toFront();
                                    formmati.requestFocus();
                                });
                             }else if(cmbStatus.getSelectedItem().equals("Rujuk")){
                                 DlgRujuk dlgrjk=new DlgRujuk(null,false);
                                 dlgrjk.setSize(internalFrame1.getWidth()-20,internalFrame1.getHeight()-20);
                                 dlgrjk.setLocationRelativeTo(internalFrame1);
                                 dlgrjk.emptTeks();
                                 dlgrjk.isCek();
                                 if(R1.isSelected()==true){
                                     dlgrjk.setNoRm(norawat.getText(),new Date(),new Date()); 
                                 }else if(R2.isSelected()==true){
                                     dlgrjk.setNoRm(norawat.getText(),DTPCari1.getDate(),DTPCari2.getDate()); 
                                 }else if(R3.isSelected()==true){
                                     dlgrjk.setNoRm(norawat.getText(),DTPCari3.getDate(),DTPCari4.getDate()); 
                                 }
                                 dlgrjk.tampil();
                                 dlgrjk.setVisible(true);
                             }
                         } catch (Exception e) {
                         }
                         Sequel.mengedit("kamar","kd_kamar='"+kamarAktifPulangV32.kodeKamar+"'","status='KOSONG'");
                         if(!kamarHakKelasPemulanganTerakhirV32.equals("")){
                             sinkronkanStatusKamarHakSetelahPemulanganV49(
                                     kamarAktifPulangV32.kodeKamar);
                         }

                         // V32: BPJS hanya boleh dijalankan jika hasil pemulangan
                         // lokal sudah terverifikasi pada kamar yang benar.
                         if(!verifikasiPemulanganLokalV32(
                                 norawat.getText().trim(),kamarAktifPulangV32,
                                 cmbStatus.getSelectedItem().toString())){
                             tampil();
                             tampilkanDialogStatusBPJSModernV27(
                                     "Verifikasi Pemulangan Gagal",
                                     "Data BPJS belum dikirim karena hasil lokal belum konsisten.",
                                     "Proses simpan pemulangan sudah dijalankan, tetapi sistem belum dapat " +
                                     "memastikan kamar aktif telah ditutup dengan benar.\n\n"+
                                     "Kamar yang seharusnya ditutup: "+kamarAktifPulangV32.kodeKamar+
                                     " "+kamarAktifPulangV32.namaBangsal+".\n\n"+
                                     "Silakan muat ulang data pasien dan periksa histori kamar sebelum mencoba update BPJS.",
                                     true);
                             return;
                         }
                         if(!barisTabelPulangTerhapus){
                             // Fallback hanya jika baris visual sudah tidak ada; refresh setelah status kamar sinkron.
                             tampil();
                         }
                         // V22: setelah pemulangan lokal sukses, lanjutkan satu klik.
                         // Pasien BPJS otomatis update tanggal pulang di background;
                         // non-BPJS langsung mendapat konfirmasi sukses.
                         lanjutSetelahPemulanganLokalBerhasil();
                     }                  
                 }                
             }          
         }
     }//GEN-LAST:event_BtnSimpanActionPerformed
 
