     private void btnPindahActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_btnPindahActionPerformed
         if(tabMode.getRowCount()==0){
             JOptionPane.showMessageDialog(null,"Maaf, data kamar inap pasien sudah habis...!!!!");
             BtnIn.requestFocus();
         }else if(sedangMemuatData){
             JOptionPane.showMessageDialog(null,"Data rawat inap masih dimuat. Silakan tunggu sampai proses selesai.");
             tbKamIn.requestFocus();
         }else if(tbKamIn.getSelectedRow()<0){
             JOptionPane.showMessageDialog(null,"Maaf, silakan pilih data pasien yang akan dipindahkan terlebih dahulu...!!!");
             tbKamIn.requestFocus();
         }else if(norawat.getText().trim().equals("")){
             JOptionPane.showMessageDialog(null,"Maaf, Silahkan anda pilih dulu data inap pasien yang mau pindah dengan menklik data pada table...!!!");
             tbKamIn.requestFocus();
         }else if(TOut.getText().trim().length()>0){
                  JOptionPane.showMessageDialog(null,"Maaf, pasien ini sudah pulang pada tanggal "+TOut.getText()+" ...!!!");
                  emptTeks();
                  tbKamIn.requestFocus();
         }else if((TOut.getText().length()==0)&&(norawat.getText().length()>0)){            
             int barisTerpilih=tbKamIn.getSelectedRow();
             String noRawatTerpilih=tbKamIn.getValueAt(barisTerpilih,0).toString().trim();
             if(noRawatTerpilih.equals("")){
                 JOptionPane.showMessageDialog(null,"Data pasien bayi gabung tidak dapat dipindahkan dari baris ini.");
                 tbKamIn.requestFocus();
                 return;
             }

             pindahNoRawatAsal=noRawatTerpilih;
             pindahKdKamarAsal=tbKamIn.getValueAt(barisTerpilih,19).toString().trim();
             pindahTglMasukAsal=tbKamIn.getValueAt(barisTerpilih,11).toString().trim();
             pindahJamMasukAsal=tbKamIn.getValueAt(barisTerpilih,12).toString().trim();
             pindahNamaKamarAsal=tbKamIn.getValueAt(barisTerpilih,7).toString().trim();
             pindahDiagnosaAwal=tbKamIn.getValueAt(barisTerpilih,9).toString();
             pindahDiagnosaAkhir=tbKamIn.getValueAt(barisTerpilih,10).toString();
             norawatpindah.setText(pindahNoRawatAsal);
             TNoRMpindah.setText(tbKamIn.getValueAt(barisTerpilih,1).toString());
             TPasienpindah.setText(tbKamIn.getValueAt(barisTerpilih,2).toString());

             kdkamarpindah.setText("");
             TKdBngsalpindah.setText("");
             TBangsalpindah.setText("");
             TSttsKamarpindah.setText("");
             TJmlHaripindah.setText("1");
             TTarifpindah.setText("0");
             ttlbiayapindah.setText("0");
             Rganti3.setSelected(true);
             date = new Date();
             now=dateFormat.format(date);
             CmbTahunpindah.setSelectedItem(now.substring(0,4));
             CmbBlnpindah.setSelectedItem(now.substring(5,7));
             CmbTglpindah.setSelectedItem(now.substring(8,10));
             cmbJampindah.setSelectedItem(now.substring(11,13));
             cmbMntpindah.setSelectedItem(now.substring(14,16));
             cmbDtkpindah.setSelectedItem(now.substring(17,19));  

             // Tarif asal dimuat ulang dari konfigurasi penjamin agar perhitungan
             // tetap sama dengan proses lama, namun menggunakan snapshot kamar.
             kdkamar.setText(pindahKdKamarAsal);
             i=1;
             isKmr();
             pindahTarifAsal=parseAngkaPindah(TTarif.getText());
             lama=Sequel.cariIsiAngka("select lamajam from set_jam_minimal");
             hariawal=Sequel.cariIsi("select hariawal from set_jam_minimal");
             prosesPindahKamar=false;
             terapkanAksesPilihanPindahKamar();
             muatRiwayatKamarPindah();
             muatAuditPembatalanKartuPindah();
             perbaruiTampilanPindahKamar();
             if(timerPencarianRawatInap!=null){
                 timerPencarianRawatInap.stop();
             }
             sesuaikanUkuranWindowPindahKamar();
             tampilkanHalamanPindahKamarTerintegrasi();
         }
     }//GEN-LAST:event_btnPindahActionPerformed
 
