     private void batalkanKamarSaatIniDariKartu() {
         if(prosesPindahKamar){
             return;
         }
         if(!adalahAdminUtamaPindahKamar()){
             JOptionPane.showMessageDialog(DlgKamarInap.this,
                     "Pembatalan pemindahan kamar hanya dapat dilakukan oleh Admin Utama.",
                     "Akses Ditolak",JOptionPane.WARNING_MESSAGE);
             return;
         }
         if(!akses.getkamar_inap()){
             JOptionPane.showMessageDialog(DlgKamarInap.this,
                     "User tidak memiliki hak akses kamar inap.",
                     "Akses Ditolak",JOptionPane.WARNING_MESSAGE);
             return;
         }
         if(auditPembatalanKartuPindah==null){
             JOptionPane.showMessageDialog(DlgKamarInap.this,
                     "Kamar saat ini tidak memiliki snapshot pemindahan terakhir yang dapat dibatalkan.",
                     "Pembatalan Tidak Tersedia",JOptionPane.INFORMATION_MESSAGE);
             muatAuditPembatalanKartuPindah();
             return;
         }
         final String noRawat=pindahNoRawatAsal;
         final String kamarAktif=pindahKdKamarAsal;
         final String tanggalAktif=pindahTglMasukAsal;
         final String jamAktif=pindahJamMasukAsal;
         if(Sequel.cariRegistrasi(noRawat)>0){
             JOptionPane.showMessageDialog(DlgKamarInap.this,
                     "Data billing sudah terverifikasi. Pembatalan pemindahan tidak diperbolehkan.\n"+
                     "Silakan hubungi bagian kasir/keuangan.",
                     "Billing Sudah Terverifikasi",JOptionPane.WARNING_MESSAGE);
             return;
         }

         try{
             pastikanTabelAuditPindahTersedia();
             AuditPindahKamar auditTerbaru=ambilAuditPindahTerakhir(noRawat,false);
             if(auditTerbaru==null){
                 auditPembatalanKartuPindah=null;
                 perbaruiTombolPembatalanKartuPindah();
                 JOptionPane.showMessageDialog(DlgKamarInap.this,
                         "Tidak ditemukan snapshot pemindahan v13/v14 yang masih dapat dibatalkan.\n\n"+
                         "Jika pasien memang sempat berpindah, gunakan tombol Pindah untuk mengembalikan pasien\n"+
                         "agar histori kamar tercatat sebagai kamar A → kamar B → kamar A.",
                         "Snapshot Tidak Tersedia",JOptionPane.INFORMATION_MESSAGE);
                 return;
             }
             if(!auditTerbaru.kdKamarTujuan.equals(kamarAktif)||
                     !auditTerbaru.tanggalMasukTujuan.equals(tanggalAktif)||
                     !auditTerbaru.jamMasukTujuan.equals(jamAktif)){
                 auditPembatalanKartuPindah=null;
                 perbaruiTombolPembatalanKartuPindah();
                 JOptionPane.showMessageDialog(DlgKamarInap.this,
                         "Kamar saat ini sudah tidak sama dengan tujuan pemindahan terakhir.\n"+
                         "Tutup form, muat ulang pasien, lalu periksa kembali.",
                         "Pemindahan Terakhir Tidak Sesuai",JOptionPane.WARNING_MESSAGE);
                 return;
             }
             auditPembatalanKartuPindah=auditTerbaru;

             String alasan=tampilkanKonfirmasiPembatalanPindahModern(auditTerbaru,
                     TNoRMpindah.getText(),TPasienpindah.getText());
             if(alasan==null){
                 return;
             }

             boolean berhasil;
             setKontrolProsesPindahKamar(true);
             try{
                 berhasil=batalkanPindahKamarDenganTransaksi(auditTerbaru.id,noRawat,
                         kamarAktif,tanggalAktif,jamAktif,alasan);
             }finally{
                 setKontrolProsesPindahKamar(false);
             }
             if(berhasil){
                 String kamarDipulihkan=auditTerbaru.namaKamarAsal;
                 JOptionPane.showMessageDialog(DlgKamarInap.this,
                         "Pemindahan terakhir berhasil dibatalkan.\n"+
                         "Pasien kembali aktif di kamar "+kamarDipulihkan+".",
                         "Pembatalan Berhasil",JOptionPane.INFORMATION_MESSAGE);
                 TOut.setText("");
                 kembaliKeDaftarKamarDariPindah();
                 tampil();
             }
         }catch(Exception e){
             JOptionPane.showMessageDialog(DlgKamarInap.this,
                     "Pembatalan belum dapat dibuka.\n\nPenyebab: "+
                     (e.getMessage()==null?e.toString():e.getMessage()),
                     "Pembatalan Pemindahan",JOptionPane.ERROR_MESSAGE);
         }
     }

     private void kdkamarpindahKeyPressed(java.awt.event.KeyEvent evt) {//GEN-FIRST:event_kdkamarpindahKeyPressed
         if(evt.getKeyCode()==KeyEvent.VK_PAGE_DOWN){
             i=2;
             isKmr();
         }else if(evt.getKeyCode()==KeyEvent.VK_ENTER){
             CmbTglpindah.requestFocus();
             i=2;
             isKmr();
         }else if(evt.getKeyCode()==KeyEvent.VK_PAGE_UP){
             BtnSimpanpindah.requestFocus();
             i=2;
             isKmr();
         }else if(evt.getKeyCode()==KeyEvent.VK_UP){
             btnKamar2ActionPerformed(null);
         }
     }//GEN-LAST:event_kdkamarpindahKeyPressed
 
     private void btnKamar2ActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_btnKamar2ActionPerformed
         akses.setform("DlgKamarInap");
         i=2;
         final DlgKamar dialog=getKamar();
         final java.awt.Dialog.ModalityType modalitasSebelumnya=dialog.getModalityType();
         final java.awt.Dialog.ModalExclusionType pengecualianSebelumnya=dialog.getModalExclusionType();
         try{
             // DlgKamar dibuat tanpa owner. Modalitas sementara memastikan
             // pemilih kamar selalu berada di depan halaman DlgKamarInap.
             dialog.setModalExclusionType(java.awt.Dialog.ModalExclusionType.APPLICATION_EXCLUDE);
             dialog.setModalityType(java.awt.Dialog.ModalityType.APPLICATION_MODAL);
             dialog.load();
             dialog.isCek();
             dialog.emptTeks();
             dialog.tampil();
             dialog.setSize(internalFrame1.getWidth()-20,internalFrame1.getHeight()-20);
             dialog.setLocationRelativeTo(DlgKamarInap.this);
             javax.swing.SwingUtilities.invokeLater(new Runnable() {
                 @Override
                 public void run() {
                     dialog.toFront();
                     dialog.requestFocus();
                     dialog.getTable().requestFocusInWindow();
                 }
             });
             dialog.setVisible(true);
         }finally{
             // DlgKamar juga dipakai dari fungsi lain, sehingga seluruh
             // pengaturan sementara wajib dikembalikan setelah dialog ditutup.
             dialog.setModalityType(modalitasSebelumnya);
             dialog.setModalExclusionType(pengecualianSebelumnya);
             DlgKamarInap.this.toFront();
             DlgKamarInap.this.requestFocus();
             kdkamarpindah.requestFocusInWindow();
             perbaruiTampilanPindahKamar();
         }
     }//GEN-LAST:event_btnKamar2ActionPerformed
 
