     private void BtnSimpanpindahActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_BtnSimpanpindahActionPerformed
         if(prosesPindahKamar){
             return;
         }
         if(!akses.getkamar_inap()){
             JOptionPane.showMessageDialog(DlgKamarInap.this,
                     "User tidak memiliki hak akses untuk memindahkan kamar pasien.",
                     "Akses Ditolak",JOptionPane.WARNING_MESSAGE);
             return;
         }

         // PATCH RSAJ V24: jika tujuan adalah ICU/ruang intensif dan kamar
         // aktif belum sesuai hak kelas BPJS, sistem menangani koreksi hak
         // kelas (opsi 2 internal) lalu pindah normal (opsi 3) dalam satu
         // transaksi. Return true berarti alur khusus sudah selesai ditangani.
         if(tanganiPindahIntensifDenganHakKelasV24()){
             return;
         }

         String pesanValidasi=validasiAwalPindahKamar();
         if(!pesanValidasi.equals("")){
             JOptionPane.showMessageDialog(DlgKamarInap.this,pesanValidasi,"Pemindahan Kamar",JOptionPane.WARNING_MESSAGE);
             perbaruiTampilanPindahKamar();
             return;
         }

         int pilihan=getPilihanPindahKamar();
         String namaPilihan=getNamaPilihanPindahKamar(pilihan);
         String waktuPindah=pilihan==2?"Tidak membuat riwayat waktu baru":formatWaktuPindah(getTanggalPindah(),getJamPindah());
         if(!tampilkanKonfirmasiPindahKamarModern(namaPilihan,waktuPindah)){
             fokusPilihanPindahKamar(pilihan);
             return;
         }

         boolean berhasil=false;
         setKontrolProsesPindahKamar(true);
         try{
             berhasil=simpanPindahKamarDenganTransaksi(pilihan);
         }finally{
             setKontrolProsesPindahKamar(false);
         }

         if(berhasil){
             JOptionPane.showMessageDialog(DlgKamarInap.this,
                     "Pasien berhasil dipindahkan ke kamar "+kdkamarpindah.getText()+".",
                     "Pemindahan Berhasil",JOptionPane.INFORMATION_MESSAGE);
             TOut.setText("");
             kembaliKeDaftarKamarDariPindah();
             tampil();
         }
     }//GEN-LAST:event_BtnSimpanpindahActionPerformed

