     private javax.swing.JPanel buatPanelBulatKonfirmasiPindah(
             final java.awt.Color latar,final java.awt.Color garis,final int radius) {
         javax.swing.JPanel panel=new javax.swing.JPanel() {
             private static final long serialVersionUID=1L;

             @Override
             protected void paintComponent(java.awt.Graphics g) {
                 java.awt.Graphics2D g2=(java.awt.Graphics2D)g.create();
                 try{
                     g2.setRenderingHint(java.awt.RenderingHints.KEY_ANTIALIASING,
                             java.awt.RenderingHints.VALUE_ANTIALIAS_ON);
                     g2.setColor(latar);
                     g2.fillRoundRect(0,0,Math.max(0,getWidth()-1),
                             Math.max(0,getHeight()-1),radius,radius);
                 }finally{
                     g2.dispose();
                 }
             }

             @Override
             protected void paintBorder(java.awt.Graphics g) {
                 java.awt.Graphics2D g2=(java.awt.Graphics2D)g.create();
                 try{
                     g2.setRenderingHint(java.awt.RenderingHints.KEY_ANTIALIASING,
                             java.awt.RenderingHints.VALUE_ANTIALIAS_ON);
                     g2.setColor(garis);
                     g2.drawRoundRect(0,0,Math.max(0,getWidth()-1),
                             Math.max(0,getHeight()-1),radius,radius);
                 }finally{
                     g2.dispose();
                 }
             }
         };
         panel.setOpaque(false);
         return panel;
     }

     private void tambahBarisKonfirmasiPindah(javax.swing.JPanel panel,int baris,
             String label,String nilai,java.awt.Font fontLabel,java.awt.Font fontNilai,
             java.awt.Color warnaLabel,java.awt.Color warnaNilai) {
         java.awt.GridBagConstraints glabel=new java.awt.GridBagConstraints();
         glabel.gridx=0;
         glabel.gridy=baris;
         glabel.weightx=0;
         glabel.anchor=java.awt.GridBagConstraints.NORTHWEST;
         glabel.insets=new java.awt.Insets(baris==0?0:6,0,0,9);
         javax.swing.JLabel lblNama=new javax.swing.JLabel(label);
         lblNama.setFont(fontLabel);
         lblNama.setForeground(warnaLabel);
         lblNama.setPreferredSize(new java.awt.Dimension(60,17));
         panel.add(lblNama,glabel);

         java.awt.GridBagConstraints gnilai=new java.awt.GridBagConstraints();
         gnilai.gridx=1;
         gnilai.gridy=baris;
         gnilai.weightx=1;
         gnilai.fill=java.awt.GridBagConstraints.HORIZONTAL;
         gnilai.anchor=java.awt.GridBagConstraints.NORTHWEST;
         gnilai.insets=new java.awt.Insets(baris==0?0:6,0,0,0);
         javax.swing.JLabel lblNilai=new javax.swing.JLabel(nilai==null||nilai.trim().equals("")?"-":nilai.trim());
         lblNilai.setFont(fontNilai);
         lblNilai.setForeground(warnaNilai);
         panel.add(lblNilai,gnilai);
     }

     /** V21 - tinggi tombol tetap 30 px, lebar mengikuti teks + ikon. */
     private void aturUkuranTombolSesuaiTeks(javax.swing.JButton tombol) {
         if(tombol==null){
             return;
         }
         java.awt.Font font=tombol.getFont();
         java.awt.FontMetrics fm=tombol.getFontMetrics(font);
         String teks=tombol.getText()==null?"":tombol.getText();
         int lebar=fm.stringWidth(teks)+24;
         if(tombol.getIcon()!=null){
             lebar+=tombol.getIcon().getIconWidth()+tombol.getIconTextGap();
         }
         lebar=Math.max(70,lebar);
         java.awt.Dimension ukuran=new java.awt.Dimension(lebar,30);
         tombol.setPreferredSize(ukuran);
         tombol.setMinimumSize(ukuran);
     }

     private javax.swing.JButton buatTombolKonfirmasiPindah(
             final String teks,final boolean utama,int lebar) {
         javax.swing.JButton tombol=new javax.swing.JButton(teks) {
             private static final long serialVersionUID=1L;

             @Override
             protected void paintComponent(java.awt.Graphics g) {
                 java.awt.Graphics2D g2=(java.awt.Graphics2D)g.create();
                 try{
                     g2.setRenderingHint(java.awt.RenderingHints.KEY_ANTIALIASING,
                             java.awt.RenderingHints.VALUE_ANTIALIAS_ON);
                     java.awt.Color warna;
                     if(!isEnabled()){
                         warna=new java.awt.Color(229,233,239);
                     }else if(utama){
                         warna=getModel().isPressed()?new java.awt.Color(10,83,132):
                                 (getModel().isRollover()?new java.awt.Color(15,98,154):new java.awt.Color(20,112,176));
                     }else{
                         warna=getModel().isPressed()?new java.awt.Color(226,232,240):
                                 (getModel().isRollover()?new java.awt.Color(241,245,249):java.awt.Color.WHITE);
                     }
                     g2.setColor(warna);
                     g2.fillRoundRect(0,0,getWidth()-1,getHeight()-1,12,12);
                     if(!utama&&isEnabled()){
                         g2.setColor(new java.awt.Color(203,213,225));
                         g2.drawRoundRect(0,0,getWidth()-1,getHeight()-1,12,12);
                     }
                     if(isFocusOwner()){
                         g2.setColor(new java.awt.Color(94,176,226));
                         g2.drawRoundRect(2,2,getWidth()-5,getHeight()-5,10,10);
                     }
                 }finally{
                     g2.dispose();
                 }
                 super.paintComponent(g);
             }
         };
         tombol.setFont(new java.awt.Font("Segoe UI Semibold",java.awt.Font.BOLD,11));
         tombol.setForeground(utama?java.awt.Color.WHITE:new java.awt.Color(51,65,85));
         tombol.setPreferredSize(new java.awt.Dimension(lebar,30));
         tombol.setBorder(javax.swing.BorderFactory.createEmptyBorder(0,11,0,11));
         tombol.setContentAreaFilled(false);
         tombol.setBorderPainted(false);
         tombol.setFocusPainted(false);
         tombol.setOpaque(false);
         tombol.setRolloverEnabled(true);
         tombol.setCursor(new java.awt.Cursor(java.awt.Cursor.HAND_CURSOR));
         return tombol;
     }

     private AuditPindahKamar ambilAuditPindahTerakhir(
             String noRawat,boolean dikunci) throws SQLException {
         String sql="select a.*,"+
                 "coalesce(concat(a.kd_kamar_asal,' ',ba.nm_bangsal),a.kd_kamar_asal) as nama_kamar_asal,"+
                 "coalesce(concat(a.kd_kamar_tujuan,' ',bt.nm_bangsal),a.kd_kamar_tujuan) as nama_kamar_tujuan,"+
                 "date_format(a.dibuat_pada,'%d-%m-%Y %H:%i:%s') as waktu_audit "+
                 "from "+TABEL_AUDIT_PINDAH_KAMAR+" a "+
                 "left join kamar ka on ka.kd_kamar=a.kd_kamar_asal "+
                 "left join bangsal ba on ba.kd_bangsal=ka.kd_bangsal "+
                 "left join kamar kt on kt.kd_kamar=a.kd_kamar_tujuan "+
                 "left join bangsal bt on bt.kd_bangsal=kt.kd_bangsal "+
                 "where a.no_rawat=? and a.status_audit='AKTIF' "+
                 "order by a.id desc limit 1"+(dikunci?" for update":"");
         try(PreparedStatement perintah=koneksi.prepareStatement(sql)){
             perintah.setString(1,noRawat);
             try(ResultSet hasil=perintah.executeQuery()){
                 if(!hasil.next()){
                     return null;
                 }
                 AuditPindahKamar data=new AuditPindahKamar();
                 data.id=hasil.getLong("id");
                 data.pilihan=hasil.getInt("pilihan");
                 data.asal.noRawat=amanStringPindah(hasil.getString("no_rawat"));
                 data.asal.kdKamar=amanStringPindah(hasil.getString("kd_kamar_asal"));
                 data.asal.tarifKamar=hasil.getDouble("trf_kamar_asal");
                 data.asal.diagnosaAwal=amanStringPindah(hasil.getString("diagnosa_awal_asal"));
                 data.asal.diagnosaAkhir=amanStringPindah(hasil.getString("diagnosa_akhir_asal"));
                 data.asal.tanggalMasuk=amanStringPindah(hasil.getString("tgl_masuk_asal"));
                 data.asal.jamMasuk=amanStringPindah(hasil.getString("jam_masuk_asal"));
                 data.asal.tanggalKeluar=amanStringPindah(hasil.getString("tgl_keluar_asal"));
                 data.asal.jamKeluar=amanStringPindah(hasil.getString("jam_keluar_asal"));
                 data.asal.lama=hasil.getDouble("lama_asal");
                 data.asal.totalBiaya=hasil.getDouble("ttl_biaya_asal");
                 data.asal.statusPulang=amanStringPindah(hasil.getString("stts_pulang_asal"));
                 data.kdKamarTujuan=amanStringPindah(hasil.getString("kd_kamar_tujuan"));
                 data.tarifKamarTujuan=hasil.getDouble("trf_kamar_tujuan");
                 data.tanggalMasukTujuan=amanStringPindah(hasil.getString("tgl_masuk_tujuan"));
                 data.jamMasukTujuan=amanStringPindah(hasil.getString("jam_masuk_tujuan"));
                 data.statusKamarAsalSebelum=amanStringPindah(
                         hasil.getString("status_kamar_asal_sebelum"));
                 data.statusKamarTujuanSebelum=amanStringPindah(
                         hasil.getString("status_kamar_tujuan_sebelum"));
                 data.penghuniLainAsalSebelum=amanStringPindah(
                         hasil.getString("penghuni_lain_asal_sebelum"));
                 data.dibuatOleh=amanStringPindah(hasil.getString("dibuat_oleh"));
                 data.dibuatPada=amanStringPindah(hasil.getString("waktu_audit"));
                 data.namaKamarAsal=amanStringPindah(hasil.getString("nama_kamar_asal"));
                 data.namaKamarTujuan=amanStringPindah(hasil.getString("nama_kamar_tujuan"));
                 return data;
             }
         }
     }

     private String amanStringPindah(String nilai) {
         return nilai==null?"":nilai.trim();
     }

