     private javax.swing.JPanel buatKartuKamarPembatalanPindah(
             AuditPindahKamar audit,boolean dipulihkan) {
         java.awt.Color warna=dipulihkan?
                 new java.awt.Color(35,142,65):new java.awt.Color(190,55,55);
         javax.swing.JLabel badge=buatBadgeTimelineKamarPindah(
                 dipulihkan?"AKTIF KEMBALI":"DIBATALKAN",
                 dipulihkan?new java.awt.Color(232,249,235):new java.awt.Color(255,239,239),
                 warna);
         badge.setPreferredSize(new java.awt.Dimension(
                 dipulihkan?105:90,25));
         javax.swing.JPanel kartu=buatKartuDasarTimelinePindah(
                 dipulihkan?"KAMAR DIPULIHKAN":"KAMAR SAAT INI",badge);
         kartu.setPreferredSize(new java.awt.Dimension(360,155));
         kartu.setMinimumSize(new java.awt.Dimension(330,155));

         String nama=dipulihkan?audit.namaKamarAsal:audit.namaKamarTujuan;
         String tanggal=dipulihkan?audit.asal.tanggalMasuk:audit.tanggalMasukTujuan;
         String jam=dipulihkan?audit.asal.jamMasuk:audit.jamMasukTujuan;
         double tarif=dipulihkan?audit.asal.tarifKamar:audit.tarifKamarTujuan;
         javax.swing.JLabel labelNama=new javax.swing.JLabel(nama.equals("")?"-":nama);
         labelNama.setToolTipText(nama);
         labelNama.setFont(new java.awt.Font("Segoe UI Semibold",java.awt.Font.BOLD,11));
         labelNama.setForeground(new java.awt.Color(24,42,66));
         javax.swing.JLabel labelWaktu=new javax.swing.JLabel(formatWaktuPindah(tanggal,jam));
         labelWaktu.setFont(new java.awt.Font("Segoe UI",java.awt.Font.PLAIN,10));
         labelWaktu.setForeground(new java.awt.Color(24,42,66));
         javax.swing.JLabel labelTarif=new javax.swing.JLabel("Rp"+formatAngkaPindah(tarif));
         labelTarif.setFont(new java.awt.Font("Segoe UI",java.awt.Font.PLAIN,10));
         labelTarif.setForeground(new java.awt.Color(24,42,66));

         javax.swing.JPanel isi=new javax.swing.JPanel(new java.awt.GridBagLayout());
         isi.setOpaque(false);
         java.awt.GridBagConstraints g=new java.awt.GridBagConstraints();
         g.gridx=0;g.fill=java.awt.GridBagConstraints.HORIZONTAL;g.weightx=1;
         javax.swing.JPanel namaPanel=buatKotakNamaKamarTimelinePindah(labelNama,
                 dipulihkan?new java.awt.Color(241,251,244):new java.awt.Color(255,244,244),
                 dipulihkan?new java.awt.Color(167,220,178):new java.awt.Color(241,188,188),
                 warna);
         namaPanel.setPreferredSize(new java.awt.Dimension(325,54));
         g.gridy=0;g.insets=new java.awt.Insets(0,0,5,0);
         isi.add(namaPanel,g);
         g.gridy=1;g.insets=new java.awt.Insets(0,0,2,0);
         isi.add(buatBarisInfoKamarPindah(IKON_PINDAH_JAM,"Masuk",labelWaktu),g);
         g.gridy=2;g.insets=new java.awt.Insets(0,0,0,0);
         isi.add(buatBarisInfoKamarPindah(IKON_PINDAH_UANG,"Tarif / hari",labelTarif),g);
         kartu.add(isi,java.awt.BorderLayout.CENTER);
         return kartu;
     }

     private int getPilihanPindahKamar() {
         // V38: pilihan yang dipilih user dipakai apa adanya untuk opsi 1-4.
         if(Rganti1.isSelected()) return 1;
         if(Rganti2.isSelected()) return 2;
         if(Rganti4.isSelected()) return 4;
         return 3;
     }

     private String getNamaPilihanPindahKamar(int pilihan) {
         switch(pilihan){
             case 1:return PILIHAN_PINDAH_1;
             case 2:return PILIHAN_PINDAH_2;
             case 4:return PILIHAN_PINDAH_4;
             default:return PILIHAN_PINDAH_3;
         }
     }

     private void fokusPilihanPindahKamar(int pilihan) {
         switch(pilihan){
             case 1:Rganti1.requestFocusInWindow();break;
             case 2:Rganti2.requestFocusInWindow();break;
             case 4:Rganti4.requestFocusInWindow();break;
             default:Rganti3.requestFocusInWindow();break;
         }
     }

     private void setKontrolProsesPindahKamar(boolean berjalan) {
         prosesPindahKamar=berjalan;
         kdkamarpindah.setEditable(!berjalan);
         btnKamar2.setEnabled(!berjalan);
         terapkanAksesPilihanPindahKamar();
         BtnCloseInpindah.setEnabled(!berjalan);
         perbaruiTombolPembatalanKartuPindah();
         DlgKamarInap.this.setCursor(berjalan?Cursor.getPredefinedCursor(Cursor.WAIT_CURSOR):Cursor.getDefaultCursor());
         perbaruiTampilanPindahKamar();
     }

     /**
      * Seluruh mutasi pemindahan dilakukan dalam satu transaksi. Tidak ada
      * helper Sequel yang dipakai di bagian ini karena helper lama menangkap
      * exception sendiri sehingga kegagalan query tidak dapat memicu rollback.
      */
     private boolean simpanPindahKamarDenganTransaksi(int pilihan) {
         // V38: pilihan 1-4 mengikuti pilihan user yang mempunyai akses kamar_inap.
         // Validasi kamar, status, waktu, transaksi atomik, dan rollback tetap sama.
         boolean autoCommitSebelumnya=true;
         boolean transaksiDimulai=false;
         String kamarTujuan=kdkamarpindah.getText().trim();
         String tanggalPindah=getTanggalPindah();
         String jamPindah=getJamPindah();
         int lamaKamarAsal=0;
         double tarifAsal=0,tarifTujuan=0,totalKamarAsal=0,totalKamarTujuan=0;
         boolean kamarAsalMasihDipakaiPasienLain=false;
         String penghuniLainAsalSebelum="";

         try{
             if(koneksi==null||koneksi.isClosed()){
                 throw new SQLException("Koneksi database tidak tersedia.");
             }
             autoCommitSebelumnya=koneksi.getAutoCommit();
             if(!autoCommitSebelumnya){
                 throw new SQLException("Koneksi database sedang digunakan oleh transaksi lain. Silakan ulangi beberapa saat lagi.");
             }
             pastikanTabelPindahMendukungTransaksi();
             pastikanTabelAuditPindahTersedia();

             koneksi.setAutoCommit(false);
             transaksiDimulai=true;

             // Kunci seluruh kamar aktif pasien dan pastikan snapshot asal masih sama.
             int jumlahKamarAktif=0;
             boolean kamarAsalMasihAktif=false;
             String diagnosaAwalDB=pindahDiagnosaAwal;
             String diagnosaAkhirDB=pindahDiagnosaAkhir;
             try(PreparedStatement cekAktif=koneksi.prepareStatement(
                     "select kd_kamar,date_format(tgl_masuk,'%Y-%m-%d') as tgl_masuk,"+
                     "time_format(jam_masuk,'%H:%i:%s') as jam_masuk,diagnosa_awal,diagnosa_akhir " +
                     "from kamar_inap where no_rawat=? and stts_pulang='-' for update")){
                 cekAktif.setString(1,pindahNoRawatAsal);
                 try(ResultSet hasil=cekAktif.executeQuery()){
                     while(hasil.next()){
                         jumlahKamarAktif++;
                         if(hasil.getString("kd_kamar").equals(pindahKdKamarAsal)&&
                                 hasil.getString("tgl_masuk").equals(pindahTglMasukAsal)&&
                                 hasil.getString("jam_masuk").equals(pindahJamMasukAsal)){
                             kamarAsalMasihAktif=true;
                             diagnosaAwalDB=hasil.getString("diagnosa_awal");
                             diagnosaAkhirDB=hasil.getString("diagnosa_akhir");
                         }
                     }
                 }
             }
             if(jumlahKamarAktif!=1){
                 throw new SQLException("Pasien harus memiliki tepat satu kamar aktif. Ditemukan "+jumlahKamarAktif+" kamar aktif.");
             }
             if(!kamarAsalMasihAktif){
                 throw new SQLException("Data kamar asal sudah berubah. Tutup dialog lalu pilih ulang pasien.");
             }
             if(!norawatpindah.getText().trim().equals(pindahNoRawatAsal)){
                 throw new SQLException("Identitas pasien pada dialog sudah berubah. Proses dibatalkan.");
             }

             String statusKamarAsal=getStatusKamarTerkunci(pindahKdKamarAsal);
             String statusKamarTujuan=getStatusKamarTerkunci(kamarTujuan);
             if(statusKamarAsal.equals("")){
                 throw new SQLException("Kamar asal tidak ditemukan.");
             }
             // PATCH RSAJ V11:
             // Khanza asli tidak menjadikan kamar.status milik kamar asal
             // sebagai syarat pemindahan. Sumber kebenaran pasien adalah
             // record aktif kamar_inap yang sudah dikunci di atas. Nilai
             // status yang tertinggal/tidak sinkron akan dinormalkan setelah
             // mutasi berhasil, bukan dipakai untuk menggagalkan pemindahan.
             if(!statusKamarAsal.equals("ISI")){
                 System.out.println("Sinkronisasi pindah kamar V11: status kamar asal "+
                         statusKamarAsal+" tetapi record pasien masih aktif.");
             }
             if(!statusKamarTujuan.equals("KOSONG")){
                 throw new SQLException("Kamar tujuan sudah tidak kosong. Silakan pilih kamar lain.");
             }
             // PATCH RSAJ V44:
             // Baris kamar sudah dikunci oleh getStatusKamarTerkunci(), sehingga
             // status KOSONG menjadi acuan transaksi dan tetap aman terhadap
             // pemindahan bersamaan. Record kamar_inap lama yang masih bertanda
             // aktif hanya dicatat sebagai ketidaksinkronan dan tidak lagi
             // menggagalkan pemindahan ke kamar yang sah berstatus KOSONG.
             if(adaPasienAktifDiKamar(kamarTujuan,"")){
                 System.out.println("Sinkronisasi pindah kamar V44: kamar tujuan "+
                         kamarTujuan+" berstatus KOSONG tetapi masih memiliki record "+
                         "kamar_inap aktif. Pemindahan dilanjutkan mengikuti status kamar.");
             }
             // Khanza mendukung dobel bed: satu kode kamar dapat memiliki
             // pasien aktif lain. Kondisi ini bukan kesalahan pemindahan.
             // Baris pasien lain dikunci dan status kamar asal tetap ISI.
             penghuniLainAsalSebelum=getDaftarPasienAktifLainTerkunci(
                     pindahKdKamarAsal,pindahNoRawatAsal);
             kamarAsalMasihDipakaiPasienLain=!penghuniLainAsalSebelum.equals("");

             LocalDateTime waktuPindah=null;
             if(pilihan!=2){
                 waktuPindah=getDateTimePindah();
                 LocalDateTime waktuMasuk=getDateTimeMasukAsalPindah();
                 if(waktuPindah.isBefore(waktuMasuk)){
                     throw new SQLException("Waktu pindah lebih awal dari waktu masuk kamar asal.");
                 }
                 LocalDateTime waktuServer=getWaktuServerTransaksi();
                 if(waktuPindah.isAfter(waktuServer)){
                     throw new SQLException("Waktu pindah melebihi waktu server "+
                             waktuServer.format(DateTimeFormatter.ofPattern("dd-MM-yyyy HH:mm:ss"))+".");
                 }
                 if(adaRiwayatBeririsan(tanggalPindah,jamPindah)){
                     throw new SQLException("Waktu pindah beririsan dengan riwayat kamar lain milik pasien.");
                 }
                 lamaKamarAsal=hitungLamaKamarPindah(waktuMasuk,waktuPindah);
             }

             tarifAsal=getTarifKamarTransaksi(pindahKdKamarAsal,pindahNoRawatAsal);
             tarifTujuan=getTarifKamarTransaksi(kamarTujuan,pindahNoRawatAsal);
             totalKamarTujuan=tarifTujuan;

             // Snapshot dibuat setelah seluruh data dikunci tetapi sebelum
             // mutasi pertama. Audit berada pada transaksi yang sama: bila
             // pemindahan gagal, snapshot ini ikut di-rollback.
             SnapshotKamarInapPindah snapshotAsal=ambilSnapshotKamarAsalTerkunci(
                     pindahNoRawatAsal,pindahKdKamarAsal,
                     pindahTglMasukAsal,pindahJamMasukAsal);
             String tanggalMasukTujuanAudit=pilihan==2?
                     pindahTglMasukAsal:tanggalPindah;
             String jamMasukTujuanAudit=pilihan==2?
                     pindahJamMasukAsal:jamPindah;
             simpanAuditPindahTransaksi(pilihan,snapshotAsal,kamarTujuan,
                     tarifTujuan,tanggalMasukTujuanAudit,jamMasukTujuanAudit,
                     statusKamarAsal,statusKamarTujuan,penghuniLainAsalSebelum);

             switch(pilihan){
                 case 1:
                     insertKamarBaruTransaksi(pindahNoRawatAsal,kamarTujuan,tarifTujuan,
                             diagnosaAwalDB,diagnosaAkhirDB,tanggalPindah,jamPindah,1,totalKamarTujuan);
                     break;
                 case 2:
                     try(PreparedStatement gantiKamar=koneksi.prepareStatement(
                             "update kamar_inap set kd_kamar=?,trf_kamar=?,lama=?,ttl_biaya=? " +
                             "where no_rawat=? and kd_kamar=? and tgl_masuk=? and jam_masuk=? and stts_pulang='-'")){
                         gantiKamar.setString(1,kamarTujuan);
                         gantiKamar.setDouble(2,tarifTujuan);
                         gantiKamar.setInt(3,1);
                         gantiKamar.setDouble(4,totalKamarTujuan);
                         gantiKamar.setString(5,pindahNoRawatAsal);
                         gantiKamar.setString(6,pindahKdKamarAsal);
                         gantiKamar.setString(7,pindahTglMasukAsal);
                         gantiKamar.setString(8,pindahJamMasukAsal);
                         pastikanSatuBaris(gantiKamar.executeUpdate(),"mengganti kamar aktif pada pilihan 2");
                     }
                     break;
                 case 4:
                     double tarifTertinggi=Math.max(tarifAsal,tarifTujuan);
                     totalKamarAsal=lamaKamarAsal*tarifTertinggi;
                     tutupKamarAsalTransaksi(tarifTertinggi,tanggalPindah,jamPindah,lamaKamarAsal,totalKamarAsal);
                     insertKamarBaruTransaksi(pindahNoRawatAsal,kamarTujuan,tarifTujuan,
                             diagnosaAwalDB,diagnosaAkhirDB,tanggalPindah,jamPindah,1,totalKamarTujuan);
                     break;
                 default:
                     totalKamarAsal=lamaKamarAsal*tarifAsal;
                     tutupKamarAsalTransaksi(tarifAsal,tanggalPindah,jamPindah,lamaKamarAsal,totalKamarAsal);
                     insertKamarBaruTransaksi(pindahNoRawatAsal,kamarTujuan,tarifTujuan,
                             diagnosaAwalDB,diagnosaAkhirDB,tanggalPindah,jamPindah,1,totalKamarTujuan);
                     break;
             }

             String statusKamarAsalAkhir=
                     kamarAsalMasihDipakaiPasienLain?"ISI":"KOSONG";
             ubahStatusKamarTransaksi(pindahKdKamarAsal,statusKamarAsalAkhir);
             ubahStatusKamarTransaksi(kamarTujuan,"ISI");
             // Pilihan 1 memang menghapus riwayat lama sesuai fungsi aslinya,
             // tetapi penghapusan ditempatkan paling akhir setelah kamar baru
             // dan kedua status kamar dipastikan berhasil di dalam transaksi.
             if(pilihan==1){
                 try(PreparedStatement hapusAsal=koneksi.prepareStatement(
                         "delete from kamar_inap where no_rawat=? and kd_kamar=? and tgl_masuk=? and jam_masuk=? and stts_pulang='-'")){
                     isiKunciKamarAsal(hapusAsal);
                     pastikanSatuBaris(hapusAsal.executeUpdate(),"menghapus kamar lama pada pilihan 1");
                 }
             }
             verifikasiHasilPindahTransaksi(pilihan,kamarTujuan,tanggalPindah,
                     jamPindah,statusKamarAsalAkhir);
             koneksi.commit();
             return true;
         }catch(Exception e){
             boolean rollbackBerhasil=!transaksiDimulai;
             if(transaksiDimulai){
                 try{
                     koneksi.rollback();
                     rollbackBerhasil=true;
                 }catch(Exception rollbackError){
                     rollbackBerhasil=false;
                     System.out.println("Rollback pindah kamar : "+rollbackError);
                 }
             }
             boolean dataAsalUtuh=rollbackBerhasil&&
                     (!transaksiDimulai||verifikasiDataAsalSetelahRollback(kamarTujuan));
             System.out.println("Pemindahan kamar dibatalkan : "+e);
             String penyebab=e.getMessage()==null?e.toString():e.getMessage();
             if(dataAsalUtuh){
                 JOptionPane.showMessageDialog(DlgKamarInap.this,
                         "Pemindahan kamar dibatalkan. Data kamar asal tetap utuh.\n\nPenyebab: "+penyebab,
                         "Pemindahan Gagal",JOptionPane.ERROR_MESSAGE);
             }else{
                 JOptionPane.showMessageDialog(DlgKamarInap.this,
                         "Terjadi gangguan dan kondisi akhir data tidak dapat dipastikan otomatis.\n"+
                         "Jangan ulangi pemindahan. Segera minta petugas IT memeriksa riwayat kamar pasien.\n\nPenyebab: "+penyebab,
                         "Perlu Pemeriksaan Data",JOptionPane.ERROR_MESSAGE);
             }
             return false;
         }finally{
             if(transaksiDimulai){
                 try{
                     koneksi.setAutoCommit(autoCommitSebelumnya);
                 }catch(Exception e){
                     System.out.println("Mengembalikan auto commit pindah kamar : "+e);
                 }
             }
         }
     }

     /**
      * Membatalkan hanya snapshot pemindahan paling akhir. Seluruh pemulihan
      * record kamar, status kedua kamar, dan status audit berada dalam satu
      * transaksi sehingga kegagalan tidak meninggalkan data setengah jadi.
      */
     private boolean batalkanPindahKamarDenganTransaksi(long idAudit,
             String noRawat,String kamarAktif,String tanggalAktif,
             String jamAktif,String alasan) {
         if(!adalahAdminUtamaPindahKamar()){
             JOptionPane.showMessageDialog(DlgKamarInap.this,
                     "Pembatalan pemindahan hanya dapat dilakukan oleh Admin Utama.",
                     "Akses Ditolak",JOptionPane.WARNING_MESSAGE);
             return false;
         }
         if(Sequel.cariRegistrasi(noRawat)>0){
             JOptionPane.showMessageDialog(DlgKamarInap.this,
                     "Data billing sudah terverifikasi. Pembatalan tidak dilakukan.",
                     "Billing Sudah Terverifikasi",JOptionPane.WARNING_MESSAGE);
             return false;
         }

         boolean autoCommitSebelumnya=true;
         boolean transaksiDimulai=false;
         AuditPindahKamar audit=null;
         try{
             if(koneksi==null||koneksi.isClosed()){
                 throw new SQLException("Koneksi database tidak tersedia.");
             }
             autoCommitSebelumnya=koneksi.getAutoCommit();
             if(!autoCommitSebelumnya){
                 throw new SQLException("Koneksi database sedang digunakan oleh transaksi lain. Silakan ulangi beberapa saat lagi.");
             }
             pastikanTabelPindahMendukungTransaksi();
             pastikanTabelAuditPindahTersedia();

             koneksi.setAutoCommit(false);
             transaksiDimulai=true;

             audit=ambilAuditPindahTerakhir(noRawat,true);
             if(audit==null){
                 throw new SQLException("Snapshot pemindahan terakhir sudah tidak aktif atau tidak ditemukan.");
             }
             if(audit.id!=idAudit){
                 throw new SQLException("Pemindahan terakhir telah berubah. Muat ulang data lalu periksa kembali.");
             }
             if(!audit.asal.noRawat.equals(noRawat)||
                     !audit.kdKamarTujuan.equals(kamarAktif)||
                     !audit.tanggalMasukTujuan.equals(tanggalAktif)||
                     !audit.jamMasukTujuan.equals(jamAktif)){
                 throw new SQLException("Kamar aktif tidak lagi sesuai dengan snapshot pembatalan.");
             }
             if(audit.asal.kdKamar.equals(audit.kdKamarTujuan)){
                 throw new SQLException("Kamar asal dan tujuan pada audit tidak valid.");
             }
             if(!audit.statusKamarTujuanSebelum.equalsIgnoreCase("KOSONG")){
                 throw new SQLException("Snapshot status kamar tujuan tidak valid untuk dipulihkan.");
             }

             // Kunci registrasi sehingga verifikasi billing tidak berubah di
             // tengah pemulihan. Pemeriksaan cariRegistrasi tetap dilakukan
             // sebelum transaksi untuk mengikuti mekanisme Khanza asli.
             try(PreparedStatement cekBilling=koneksi.prepareStatement(
                     "select status_bayar from reg_periksa where no_rawat=? for update")){
                 cekBilling.setString(1,noRawat);
                 try(ResultSet hasil=cekBilling.executeQuery()){
                     if(!hasil.next()){
                         throw new SQLException("Data registrasi pasien tidak ditemukan.");
                     }
                     String statusBayar=amanStringPindah(hasil.getString("status_bayar"));
                     if(statusBayar.equalsIgnoreCase("Sudah Bayar")){
                         throw new SQLException("Billing pasien sudah berstatus Sudah Bayar.");
                     }
                 }
             }

             int jumlahAktif=0;
             boolean tujuanSesuai=false;
             try(PreparedStatement cekAktif=koneksi.prepareStatement(
                     "select kd_kamar,cast(tgl_masuk as char) as tgl_masuk,"+
                     "time_format(jam_masuk,'%H:%i:%s') as jam_masuk from kamar_inap "+
                     "where no_rawat=? and stts_pulang='-' for update")){
                 cekAktif.setString(1,noRawat);
                 try(ResultSet hasil=cekAktif.executeQuery()){
                     while(hasil.next()){
                         jumlahAktif++;
                         if(audit.kdKamarTujuan.equals(hasil.getString("kd_kamar"))&&
                                 audit.tanggalMasukTujuan.equals(hasil.getString("tgl_masuk"))&&
                                 audit.jamMasukTujuan.equals(hasil.getString("jam_masuk"))){
                             tujuanSesuai=true;
                         }
                     }
                 }
             }
             if(jumlahAktif!=1||!tujuanSesuai){
                 throw new SQLException("Pasien tidak lagi memiliki tepat satu kamar tujuan aktif yang sesuai audit.");
             }

             String statusAsalSekarang=getStatusKamarTerkunci(audit.asal.kdKamar);
             String statusTujuanSekarang=getStatusKamarTerkunci(audit.kdKamarTujuan);
             if(statusAsalSekarang.equals("")||statusTujuanSekarang.equals("")){
                 throw new SQLException("Kamar asal atau kamar tujuan sudah tidak ditemukan.");
             }
             if(!statusTujuanSekarang.equalsIgnoreCase("ISI")){
                 throw new SQLException("Status kamar tujuan bukan ISI. Periksa konsistensi kamar terlebih dahulu.");
             }

             String penghuniLainAsal=getDaftarPasienAktifLainTerkunci(
                     audit.asal.kdKamar,noRawat);
             if(!penghuniLainAsal.equals(audit.penghuniLainAsalSebelum)){
                 throw new SQLException("Penghuni lain kamar asal telah berubah sejak pemindahan. "+
                         "Pembatalan otomatis tidak aman dilakukan.");
             }
             String penghuniLainTujuan=getDaftarPasienAktifLainTerkunci(
                     audit.kdKamarTujuan,noRawat);
             if(!penghuniLainTujuan.equals("")){
                 throw new SQLException("Kamar tujuan kini dipakai pasien aktif lain. "+
                         "Pembatalan otomatis tidak aman dilakukan.");
             }

             verifikasiRecordAsalSiapDipulihkan(audit);
             if(audit.pilihan==2){
                 pulihkanSnapshotKamarDenganUpdate(audit.asal,
                         audit.kdKamarTujuan,audit.tanggalMasukTujuan,
                         audit.jamMasukTujuan,"-");
             }else{
                 hapusKamarTujuanPembatalan(audit);
                 if(audit.pilihan==1){
                     pulihkanSnapshotKamarDenganInsert(audit.asal);
                 }else if(audit.pilihan==3||audit.pilihan==4){
                     pulihkanSnapshotKamarDenganUpdate(audit.asal,
                             audit.asal.kdKamar,audit.asal.tanggalMasuk,
                             audit.asal.jamMasuk,"Pindah Kamar");
                 }else{
                     throw new SQLException("Nomor pilihan pemindahan pada audit tidak dikenali.");
                 }
             }

             ubahStatusKamarTransaksi(audit.asal.kdKamar,"ISI");
             ubahStatusKamarTransaksi(audit.kdKamarTujuan,"KOSONG");

             try(PreparedStatement perintah=koneksi.prepareStatement(
                     "update "+TABEL_AUDIT_PINDAH_KAMAR+" set status_audit='DIBATALKAN',"+
                     "dibatalkan_oleh=?,dibatalkan_pada=now(),alasan_pembatalan=? "+
                     "where id=? and status_audit='AKTIF'")){
                 perintah.setString(1,getPenggunaAuditPindah());
                 perintah.setString(2,alasan.trim());
                 perintah.setLong(3,audit.id);
                 pastikanSatuBaris(perintah.executeUpdate(),
                         "menandai audit pemindahan sebagai dibatalkan");
             }

             verifikasiHasilPembatalanPindahTransaksi(audit);
             koneksi.commit();
             return true;
         }catch(Exception e){
             boolean rollbackBerhasil=!transaksiDimulai;
             if(transaksiDimulai){
                 try{
                     koneksi.rollback();
                     rollbackBerhasil=true;
                 }catch(Exception rollbackError){
                     rollbackBerhasil=false;
                     System.out.println("Rollback pembatalan pindah kamar : "+rollbackError);
                 }
             }
             boolean pemindahanTetapUtuh=!transaksiDimulai||
                     (rollbackBerhasil&&verifikasiPemindahanSetelahRollbackPembatalan(
                             idAudit,noRawat,kamarAktif,tanggalAktif,jamAktif));
             String penyebab=e.getMessage()==null?e.toString():e.getMessage();
             System.out.println("Pembatalan pemindahan kamar gagal : "+e);
             if(pemindahanTetapUtuh){
                 JOptionPane.showMessageDialog(DlgKamarInap.this,
                         "Pembatalan tidak dilakukan. Pemindahan terakhir tetap utuh.\n\n"+
                         "Penyebab: "+penyebab,
                         "Pembatalan Gagal",JOptionPane.ERROR_MESSAGE);
             }else{
                 JOptionPane.showMessageDialog(DlgKamarInap.this,
                         "Kondisi akhir data tidak dapat dipastikan otomatis.\n"+
                         "Jangan mengulangi proses. Segera minta petugas IT memeriksa audit dan riwayat kamar.\n\n"+
                         "Penyebab: "+penyebab,
                         "Perlu Pemeriksaan Data",JOptionPane.ERROR_MESSAGE);
             }
             return false;
         }finally{
             if(transaksiDimulai){
                 try{
                     koneksi.setAutoCommit(autoCommitSebelumnya);
                 }catch(Exception e){
                     System.out.println("Mengembalikan auto commit pembatalan pindah kamar : "+e);
                 }
             }
         }
     }

     private void verifikasiRecordAsalSiapDipulihkan(AuditPindahKamar audit)
             throws SQLException {
         if(audit.pilihan==2){
             return;
         }
         int jumlah=0;
         String status="",tanggalKeluar="",jamKeluar="";
         try(PreparedStatement perintah=koneksi.prepareStatement(
                 "select stts_pulang,coalesce(cast(tgl_keluar as char),'0000-00-00') as tgl_keluar,"+
                 "coalesce(time_format(jam_keluar,'%H:%i:%s'),'00:00:00') as jam_keluar "+
                 "from kamar_inap where no_rawat=? and kd_kamar=? and tgl_masuk=? "+
                 "and jam_masuk=? for update")){
             perintah.setString(1,audit.asal.noRawat);
             perintah.setString(2,audit.asal.kdKamar);
             perintah.setString(3,audit.asal.tanggalMasuk);
             perintah.setString(4,audit.asal.jamMasuk);
             try(ResultSet hasil=perintah.executeQuery()){
                 while(hasil.next()){
                     jumlah++;
                     status=amanStringPindah(hasil.getString("stts_pulang"));
                     tanggalKeluar=amanStringPindah(hasil.getString("tgl_keluar"));
                     jamKeluar=amanStringPindah(hasil.getString("jam_keluar"));
                 }
             }
         }
         if(audit.pilihan==1){
             if(jumlah!=0){
                 throw new SQLException("Record kamar asal pilihan 1 sudah muncul kembali atau berubah.");
             }
             return;
         }
         if(jumlah!=1||!status.equals("Pindah Kamar")||
                 !tanggalKeluar.equals(audit.tanggalMasukTujuan)||
                 !jamKeluar.equals(audit.jamMasukTujuan)){
             throw new SQLException("Riwayat kamar asal telah berubah sejak pemindahan.");
         }
     }

     private void hapusKamarTujuanPembatalan(AuditPindahKamar audit)
             throws SQLException {
         try(PreparedStatement perintah=koneksi.prepareStatement(
                 "delete from kamar_inap where no_rawat=? and kd_kamar=? "+
                 "and tgl_masuk=? and jam_masuk=? and stts_pulang='-'")){
             perintah.setString(1,audit.asal.noRawat);
             perintah.setString(2,audit.kdKamarTujuan);
             perintah.setString(3,audit.tanggalMasukTujuan);
             perintah.setString(4,audit.jamMasukTujuan);
             pastikanSatuBaris(perintah.executeUpdate(),
                     "menghapus record kamar tujuan saat pembatalan");
         }
     }

     private void pulihkanSnapshotKamarDenganInsert(SnapshotKamarInapPindah data)
             throws SQLException {
         String sql="insert into kamar_inap(no_rawat,kd_kamar,trf_kamar,"+
                 "diagnosa_awal,diagnosa_akhir,tgl_masuk,jam_masuk,tgl_keluar,"+
                 "jam_keluar,lama,ttl_biaya,stts_pulang) values(?,?,?,?,?,?,?,?,?,?,?,?)";
         try(PreparedStatement perintah=koneksi.prepareStatement(sql)){
             int kolom=1;
             perintah.setString(kolom++,data.noRawat);
             perintah.setString(kolom++,data.kdKamar);
             perintah.setDouble(kolom++,data.tarifKamar);
             perintah.setString(kolom++,data.diagnosaAwal);
             perintah.setString(kolom++,data.diagnosaAkhir);
             perintah.setString(kolom++,data.tanggalMasuk);
             perintah.setString(kolom++,data.jamMasuk);
             perintah.setString(kolom++,data.tanggalKeluar);
             perintah.setString(kolom++,data.jamKeluar);
             perintah.setDouble(kolom++,data.lama);
             perintah.setDouble(kolom++,data.totalBiaya);
             perintah.setString(kolom++,data.statusPulang);
             pastikanSatuBaris(perintah.executeUpdate(),
                     "memulihkan record kamar asal pilihan 1");
         }
     }

     private void pulihkanSnapshotKamarDenganUpdate(SnapshotKamarInapPindah data,
             String kondisiKamar,String kondisiTanggal,String kondisiJam,
             String kondisiStatus) throws SQLException {
         String sql="update kamar_inap set kd_kamar=?,trf_kamar=?,diagnosa_awal=?,"+
                 "diagnosa_akhir=?,tgl_masuk=?,jam_masuk=?,tgl_keluar=?,jam_keluar=?,"+
                 "lama=?,ttl_biaya=?,stts_pulang=? where no_rawat=? and kd_kamar=? "+
                 "and tgl_masuk=? and jam_masuk=? and stts_pulang=?";
         try(PreparedStatement perintah=koneksi.prepareStatement(sql)){
             int kolom=1;
             perintah.setString(kolom++,data.kdKamar);
             perintah.setDouble(kolom++,data.tarifKamar);
             perintah.setString(kolom++,data.diagnosaAwal);
             perintah.setString(kolom++,data.diagnosaAkhir);
             perintah.setString(kolom++,data.tanggalMasuk);
             perintah.setString(kolom++,data.jamMasuk);
             perintah.setString(kolom++,data.tanggalKeluar);
             perintah.setString(kolom++,data.jamKeluar);
             perintah.setDouble(kolom++,data.lama);
             perintah.setDouble(kolom++,data.totalBiaya);
             perintah.setString(kolom++,data.statusPulang);
             perintah.setString(kolom++,data.noRawat);
             perintah.setString(kolom++,kondisiKamar);
             perintah.setString(kolom++,kondisiTanggal);
             perintah.setString(kolom++,kondisiJam);
             perintah.setString(kolom++,kondisiStatus);
             pastikanSatuBaris(perintah.executeUpdate(),
                     "memulihkan snapshot kamar asal");
         }
     }

     private void verifikasiHasilPembatalanPindahTransaksi(
             AuditPindahKamar audit) throws SQLException {
         int asalAktif=0,tujuanAktif=0;
         try(PreparedStatement perintah=koneksi.prepareStatement(
                 "select kd_kamar,cast(tgl_masuk as char) as tgl_masuk,"+
                 "time_format(jam_masuk,'%H:%i:%s') as jam_masuk from kamar_inap "+
                 "where no_rawat=? and stts_pulang='-' for update")){
             perintah.setString(1,audit.asal.noRawat);
             try(ResultSet hasil=perintah.executeQuery()){
                 while(hasil.next()){
                     if(audit.asal.kdKamar.equals(hasil.getString("kd_kamar"))&&
                             audit.asal.tanggalMasuk.equals(hasil.getString("tgl_masuk"))&&
                             audit.asal.jamMasuk.equals(hasil.getString("jam_masuk"))){
                         asalAktif++;
                     }
                     if(audit.kdKamarTujuan.equals(hasil.getString("kd_kamar"))){
                         tujuanAktif++;
                     }
                 }
             }
         }
         if(asalAktif!=1||tujuanAktif!=0){
             throw new SQLException("Verifikasi pembatalan gagal: kamar asal belum aktif tunggal atau kamar tujuan masih aktif.");
         }
         if(!getStatusKamarTerkunci(audit.asal.kdKamar).equals("ISI")||
                 !getStatusKamarTerkunci(audit.kdKamarTujuan).equals("KOSONG")){
             throw new SQLException("Verifikasi pembatalan gagal: status kamar belum konsisten.");
         }
         try(PreparedStatement perintah=koneksi.prepareStatement(
                 "select status_audit from "+TABEL_AUDIT_PINDAH_KAMAR+
                 " where id=? for update")){
             perintah.setLong(1,audit.id);
             try(ResultSet hasil=perintah.executeQuery()){
                 if(!hasil.next()||!"DIBATALKAN".equals(
                         amanStringPindah(hasil.getString("status_audit")))){
                     throw new SQLException("Verifikasi pembatalan gagal: audit belum ditandai dibatalkan.");
                 }
             }
         }
     }

     private boolean verifikasiPemindahanSetelahRollbackPembatalan(long idAudit,
             String noRawat,String kamarAktif,String tanggalAktif,String jamAktif) {
         try{
             int targetAktif=0,auditAktif=0;
             try(PreparedStatement perintah=koneksi.prepareStatement(
                     "select count(*) from kamar_inap where no_rawat=? and kd_kamar=? "+
                     "and tgl_masuk=? and jam_masuk=? and stts_pulang='-'")){
                 perintah.setString(1,noRawat);
                 perintah.setString(2,kamarAktif);
                 perintah.setString(3,tanggalAktif);
                 perintah.setString(4,jamAktif);
                 try(ResultSet hasil=perintah.executeQuery()){
                     if(hasil.next()){
                         targetAktif=hasil.getInt(1);
                     }
                 }
             }
             try(PreparedStatement perintah=koneksi.prepareStatement(
                     "select count(*) from "+TABEL_AUDIT_PINDAH_KAMAR+
                     " where id=? and status_audit='AKTIF'")){
                 perintah.setLong(1,idAudit);
                 try(ResultSet hasil=perintah.executeQuery()){
                     if(hasil.next()){
                         auditAktif=hasil.getInt(1);
                     }
                 }
             }
             return targetAktif==1&&auditAktif==1;
         }catch(Exception e){
             System.out.println("Verifikasi rollback pembatalan pindah kamar : "+e);
             return false;
         }
     }

     /**
      * Setelah rollback, pastikan pasien masih aktif pada record asal dan
      * belum tercatat aktif pada kamar tujuan. Pemeriksaan ini juga menangani
      * kondisi langka ketika koneksi terputus tepat saat commit dijalankan.
      */
     private boolean verifikasiDataAsalSetelahRollback(String kamarTujuan) {
         try(PreparedStatement perintah=koneksi.prepareStatement(
                 "select " +
                 "sum(case when kd_kamar=? and tgl_masuk=? and jam_masuk=? and stts_pulang='-' then 1 else 0 end) as asal_aktif,"+
                 "sum(case when kd_kamar=? and stts_pulang='-' then 1 else 0 end) as tujuan_aktif " +
                 "from kamar_inap where no_rawat=?")){
             perintah.setString(1,pindahKdKamarAsal);
             perintah.setString(2,pindahTglMasukAsal);
             perintah.setString(3,pindahJamMasukAsal);
             perintah.setString(4,kamarTujuan);
             perintah.setString(5,pindahNoRawatAsal);
             try(ResultSet hasil=perintah.executeQuery()){
                 return hasil.next()&&hasil.getInt("asal_aktif")==1&&hasil.getInt("tujuan_aktif")==0;
             }
         }catch(Exception pemeriksaanError){
             System.out.println("Verifikasi rollback pindah kamar : "+pemeriksaanError);
             return false;
         }
     }

     private String getStatusKamarTerkunci(String kodeKamar) throws SQLException {
         try(PreparedStatement perintah=koneksi.prepareStatement(
                 "select status from kamar where kd_kamar=? for update")){
             perintah.setString(1,kodeKamar);
             try(ResultSet hasil=perintah.executeQuery()){
                 return hasil.next()?hasil.getString("status").trim():"";
             }
         }
     }

     private SnapshotKamarInapPindah ambilSnapshotKamarAsalTerkunci(
             String noRawat,String kodeKamar,String tanggalMasuk,String jamMasuk)
             throws SQLException {
         String sql="select no_rawat,kd_kamar,trf_kamar,"+
                 "coalesce(diagnosa_awal,'') as diagnosa_awal,"+
                 "coalesce(diagnosa_akhir,'') as diagnosa_akhir,"+
                 "cast(tgl_masuk as char) as tgl_masuk,"+
                 "time_format(jam_masuk,'%H:%i:%s') as jam_masuk,"+
                 "coalesce(cast(tgl_keluar as char),'0000-00-00') as tgl_keluar,"+
                 "coalesce(time_format(jam_keluar,'%H:%i:%s'),'00:00:00') as jam_keluar,"+
                 "lama,ttl_biaya,stts_pulang from kamar_inap where no_rawat=? "+
                 "and kd_kamar=? and tgl_masuk=? and jam_masuk=? for update";
         try(PreparedStatement perintah=koneksi.prepareStatement(sql)){
             perintah.setString(1,noRawat);
             perintah.setString(2,kodeKamar);
             perintah.setString(3,tanggalMasuk);
             perintah.setString(4,jamMasuk);
             try(ResultSet hasil=perintah.executeQuery()){
                 if(!hasil.next()){
                     throw new SQLException("Snapshot kamar asal tidak ditemukan.");
                 }
                 SnapshotKamarInapPindah data=new SnapshotKamarInapPindah();
                 data.noRawat=hasil.getString("no_rawat");
                 data.kdKamar=hasil.getString("kd_kamar");
                 data.tarifKamar=hasil.getDouble("trf_kamar");
                 data.diagnosaAwal=hasil.getString("diagnosa_awal");
                 data.diagnosaAkhir=hasil.getString("diagnosa_akhir");
                 data.tanggalMasuk=hasil.getString("tgl_masuk");
                 data.jamMasuk=hasil.getString("jam_masuk");
                 data.tanggalKeluar=hasil.getString("tgl_keluar");
                 data.jamKeluar=hasil.getString("jam_keluar");
                 data.lama=hasil.getDouble("lama");
                 data.totalBiaya=hasil.getDouble("ttl_biaya");
                 data.statusPulang=hasil.getString("stts_pulang");
                 if(data.tanggalKeluar==null||data.tanggalKeluar.trim().equals("")){
                     data.tanggalKeluar="0000-00-00";
                 }
                 if(data.jamKeluar==null||data.jamKeluar.trim().equals("")){
                     data.jamKeluar="00:00:00";
                 }
                 if(!"-".equals(data.statusPulang)){
                     throw new SQLException("Snapshot kamar asal bukan record aktif.");
                 }
                 if(hasil.next()){
                     throw new SQLException("Snapshot kamar asal tidak unik.");
                 }
                 return data;
             }
         }
     }

     private long simpanAuditPindahTransaksi(int pilihan,
             SnapshotKamarInapPindah asal,String kamarTujuan,double tarifTujuan,
             String tanggalMasukTujuan,String jamMasukTujuan,
             String statusKamarAsal,String statusKamarTujuan,
             String penghuniLainAsal) throws SQLException {
         String sql="insert into "+TABEL_AUDIT_PINDAH_KAMAR+"("+
                 "no_rawat,pilihan,kd_kamar_asal,trf_kamar_asal,"+
                 "diagnosa_awal_asal,diagnosa_akhir_asal,tgl_masuk_asal,"+
                 "jam_masuk_asal,tgl_keluar_asal,jam_keluar_asal,lama_asal,"+
                 "ttl_biaya_asal,stts_pulang_asal,kd_kamar_tujuan,"+
                 "trf_kamar_tujuan,tgl_masuk_tujuan,jam_masuk_tujuan,"+
                 "status_kamar_asal_sebelum,status_kamar_tujuan_sebelum,"+
                 "penghuni_lain_asal_sebelum,status_audit,dibuat_oleh,dibuat_pada) "+
                 "values(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,'AKTIF',?,now())";
         try(PreparedStatement perintah=koneksi.prepareStatement(
                 sql,java.sql.Statement.RETURN_GENERATED_KEYS)){
             int kolom=1;
             perintah.setString(kolom++,asal.noRawat);
             perintah.setInt(kolom++,pilihan);
             perintah.setString(kolom++,asal.kdKamar);
             perintah.setDouble(kolom++,asal.tarifKamar);
             perintah.setString(kolom++,asal.diagnosaAwal);
             perintah.setString(kolom++,asal.diagnosaAkhir);
             perintah.setString(kolom++,asal.tanggalMasuk);
             perintah.setString(kolom++,asal.jamMasuk);
             perintah.setString(kolom++,asal.tanggalKeluar);
             perintah.setString(kolom++,asal.jamKeluar);
             perintah.setDouble(kolom++,asal.lama);
             perintah.setDouble(kolom++,asal.totalBiaya);
             perintah.setString(kolom++,asal.statusPulang);
             perintah.setString(kolom++,kamarTujuan);
             perintah.setDouble(kolom++,tarifTujuan);
             perintah.setString(kolom++,tanggalMasukTujuan);
             perintah.setString(kolom++,jamMasukTujuan);
             perintah.setString(kolom++,statusKamarAsal);
             perintah.setString(kolom++,statusKamarTujuan);
             perintah.setString(kolom++,penghuniLainAsal);
             perintah.setString(kolom++,getPenggunaAuditPindah());
             pastikanSatuBaris(perintah.executeUpdate(),"menyimpan audit pemindahan kamar");
             try(ResultSet kunci=perintah.getGeneratedKeys()){
                 if(kunci.next()&&kunci.getLong(1)>0){
                     return kunci.getLong(1);
                 }
             }
         }
         throw new SQLException("Nomor audit pemindahan tidak berhasil dibuat.");
     }

     private String getPenggunaAuditPindah() {
         String pengguna=akses.getkode();
         if(pengguna==null||pengguna.trim().equals("")){
             pengguna="Tidak diketahui";
         }
         pengguna=pengguna.trim();
         return pengguna.length()>100?pengguna.substring(0,100):pengguna;
     }

     private void pastikanTabelPindahMendukungTransaksi() throws SQLException {
         int ditemukan=0;
         try(PreparedStatement perintah=koneksi.prepareStatement(
                 "select table_name,engine from information_schema.tables " +
                 "where table_schema=database() and table_name in('kamar_inap','kamar')")){
             try(ResultSet hasil=perintah.executeQuery()){
                 while(hasil.next()){
                     ditemukan++;
                     String engine=hasil.getString("engine");
                     if(engine==null||!engine.equalsIgnoreCase("InnoDB")){
                         throw new SQLException("Tabel "+hasil.getString("table_name")+
                                 " belum menggunakan InnoDB, sehingga rollback tidak dapat dijamin.");
                     }
                 }
             }
         }
         if(ditemukan!=2){
             throw new SQLException("Struktur tabel kamar atau kamar_inap tidak dapat diverifikasi.");
         }
     }

     private void pastikanTabelAuditPindahTersedia() throws SQLException {
         try(PreparedStatement perintah=koneksi.prepareStatement(
                 "select engine from information_schema.tables where table_schema=database() "+
                 "and table_name=?")){
             perintah.setString(1,TABEL_AUDIT_PINDAH_KAMAR);
             try(ResultSet hasil=perintah.executeQuery()){
                 if(!hasil.next()){
                     throw new SQLException("Tabel audit pemindahan belum tersedia. "+
                             "Jalankan skrip migrasi_pindah_kamar_v14.sql terlebih dahulu.");
                 }
                 String engine=hasil.getString("engine");
                 if(engine==null||!engine.equalsIgnoreCase("InnoDB")){
                     throw new SQLException("Tabel "+TABEL_AUDIT_PINDAH_KAMAR+
                             " harus menggunakan InnoDB agar audit ikut rollback.");
                 }
             }
         }
     }

     private boolean adaPasienAktifDiKamar(String kodeKamar,String noRawatDikecualikan) throws SQLException {
         String sql="select no_rawat from kamar_inap where kd_kamar=? and stts_pulang='-'"+
                 (noRawatDikecualikan.equals("")?"":" and no_rawat<>?")+" for update";
         try(PreparedStatement perintah=koneksi.prepareStatement(sql)){
             perintah.setString(1,kodeKamar);
             if(!noRawatDikecualikan.equals("")){
                 perintah.setString(2,noRawatDikecualikan);
             }
             try(ResultSet hasil=perintah.executeQuery()){
                 return hasil.next();
             }
         }
     }

     /**
      * Mengunci dan mengembalikan daftar no_rawat penghuni lain secara urut.
      * Nilai ini membuat pembatalan tetap aman pada kamar dobel-bed: keadaan
      * penghuni lain harus persis sama seperti sebelum pemindahan.
      */
     private String getDaftarPasienAktifLainTerkunci(
             String kodeKamar,String noRawatDikecualikan) throws SQLException {
         String sql="select no_rawat from kamar_inap where kd_kamar=? and stts_pulang='-'"+
                 (noRawatDikecualikan==null||noRawatDikecualikan.equals("")?
                         "":" and no_rawat<>?")+" order by no_rawat for update";
         StringBuilder daftar=new StringBuilder();
         try(PreparedStatement perintah=koneksi.prepareStatement(sql)){
             perintah.setString(1,kodeKamar);
             if(noRawatDikecualikan!=null&&!noRawatDikecualikan.equals("")){
                 perintah.setString(2,noRawatDikecualikan);
             }
             try(ResultSet hasil=perintah.executeQuery()){
                 while(hasil.next()){
                     if(daftar.length()>0){
                         daftar.append('|');
                     }
                     daftar.append(hasil.getString("no_rawat").trim());
                 }
             }
         }
         return daftar.toString();
     }

     private LocalDateTime getWaktuServerTransaksi() throws SQLException {
         try(PreparedStatement perintah=koneksi.prepareStatement("select now()")){
             try(ResultSet hasil=perintah.executeQuery()){
                 if(hasil.next()){
                     java.sql.Timestamp waktu=hasil.getTimestamp(1);
                     if(waktu!=null){
                         return waktu.toLocalDateTime();
                     }
                 }
             }
         }
         throw new SQLException("Waktu server database tidak dapat dibaca.");
     }

     private boolean adaRiwayatBeririsan(String tanggalPindah,String jamPindah) throws SQLException {
         String waktu=tanggalPindah+" "+jamPindah;
         String sql="select 1 from kamar_inap where no_rawat=? " +
                 "and not(kd_kamar=? and tgl_masuk=? and jam_masuk=?) " +
                 "and (timestamp(tgl_masuk,jam_masuk)>=str_to_date(?,'%Y-%m-%d %H:%i:%s') " +
                 "or stts_pulang='-' or tgl_keluar is null or jam_keluar is null or tgl_keluar='0000-00-00' " +
                 "or timestamp(tgl_keluar,jam_keluar)>str_to_date(?,'%Y-%m-%d %H:%i:%s')) " +
                 "limit 1 for update";
         try(PreparedStatement perintah=koneksi.prepareStatement(sql)){
             perintah.setString(1,pindahNoRawatAsal);
             perintah.setString(2,pindahKdKamarAsal);
             perintah.setString(3,pindahTglMasukAsal);
             perintah.setString(4,pindahJamMasukAsal);
             perintah.setString(5,waktu);
             perintah.setString(6,waktu);
             try(ResultSet hasil=perintah.executeQuery()){
                 return hasil.next();
             }
         }
     }

     private int hitungLamaKamarPindah(LocalDateTime waktuMasuk,LocalDateTime waktuPindah) {
         long selisihHari=java.time.temporal.ChronoUnit.DAYS.between(
                 waktuMasuk.toLocalDate(),waktuPindah.toLocalDate());
         if(selisihHari==0){
             long selisihDetik=java.time.temporal.ChronoUnit.SECONDS.between(waktuMasuk,waktuPindah);
             return selisihDetik>(long)(lama*3600)?1:0;
         }
         long hasil=selisihHari+(hariawal.equals("Yes")?1:0);
         return hasil>Integer.MAX_VALUE?Integer.MAX_VALUE:(int)hasil;
     }

     private double getTarifKamarTransaksi(String kodeKamar,String noRawat) throws SQLException {
         String sql="select coalesce(sh.tarif,k.trf_kamar) as tarif from kamar k " +
                 "left join reg_periksa rp on rp.no_rawat=? " +
                 "left join set_harga_kamar sh on sh.kd_kamar=k.kd_kamar and sh.kd_pj=rp.kd_pj " +
                 "where k.kd_kamar=? limit 1";
         try(PreparedStatement perintah=koneksi.prepareStatement(sql)){
             perintah.setString(1,noRawat);
             perintah.setString(2,kodeKamar);
             try(ResultSet hasil=perintah.executeQuery()){
                 if(hasil.next()){
                     return hasil.getDouble("tarif");
                 }
             }
         }
         throw new SQLException("Tarif kamar "+kodeKamar+" tidak ditemukan.");
     }

     private void insertKamarBaruTransaksi(String noRawat,String kodeKamar,double tarif,
             String diagnosaAwal,String diagnosaAkhir,String tanggalMasuk,String jamMasuk,
             int lamaInap,double totalBiaya) throws SQLException {
         String sql="insert into kamar_inap(no_rawat,kd_kamar,trf_kamar,diagnosa_awal,diagnosa_akhir,"+
                 "tgl_masuk,jam_masuk,tgl_keluar,jam_keluar,lama,ttl_biaya,stts_pulang) " +
                 "values(?,?,?,?,?,?,?,'0000-00-00','00:00:00',?,?,'-')";
         try(PreparedStatement perintah=koneksi.prepareStatement(sql)){
             perintah.setString(1,noRawat);
             perintah.setString(2,kodeKamar);
             perintah.setDouble(3,tarif);
             perintah.setString(4,diagnosaAwal==null?"":diagnosaAwal);
             perintah.setString(5,diagnosaAkhir==null?"":diagnosaAkhir);
             perintah.setString(6,tanggalMasuk);
             perintah.setString(7,jamMasuk);
             perintah.setInt(8,lamaInap);
             perintah.setDouble(9,totalBiaya);
             pastikanSatuBaris(perintah.executeUpdate(),"menyimpan kamar tujuan");
         }
     }

     private void isiKunciKamarAsal(PreparedStatement perintah) throws SQLException {
         perintah.setString(1,pindahNoRawatAsal);
         perintah.setString(2,pindahKdKamarAsal);
         perintah.setString(3,pindahTglMasukAsal);
         perintah.setString(4,pindahJamMasukAsal);
     }

     private void tutupKamarAsalTransaksi(double tarif,String tanggalKeluar,String jamKeluar,
             int lamaInap,double totalBiaya) throws SQLException {
         String sql="update kamar_inap set trf_kamar=?,tgl_keluar=?,jam_keluar=?,lama=?,ttl_biaya=?,"+
                 "stts_pulang='Pindah Kamar' where no_rawat=? and kd_kamar=? and tgl_masuk=? " +
                 "and jam_masuk=? and stts_pulang='-'";
         try(PreparedStatement perintah=koneksi.prepareStatement(sql)){
             perintah.setDouble(1,tarif);
             perintah.setString(2,tanggalKeluar);
             perintah.setString(3,jamKeluar);
             perintah.setInt(4,lamaInap);
             perintah.setDouble(5,totalBiaya);
             perintah.setString(6,pindahNoRawatAsal);
             perintah.setString(7,pindahKdKamarAsal);
             perintah.setString(8,pindahTglMasukAsal);
             perintah.setString(9,pindahJamMasukAsal);
             pastikanSatuBaris(perintah.executeUpdate(),"menutup kamar asal");
         }
     }

     private void ubahStatusKamarTransaksi(String kodeKamar,String status) throws SQLException {
         try(PreparedStatement perintah=koneksi.prepareStatement(
                 "update kamar set status=? where kd_kamar=?")){
             perintah.setString(1,status);
             perintah.setString(2,kodeKamar);
             perintah.executeUpdate();
         }
         String hasil=getStatusKamarTerkunci(kodeKamar);
         if(!hasil.equals(status)){
             throw new SQLException("Status kamar "+kodeKamar+" gagal diubah menjadi "+status+".");
         }
     }

     private void verifikasiHasilPindahTransaksi(int pilihan,String kamarTujuan,
             String tanggalPindah,String jamPindah,String statusKamarAsalAkhir)
             throws SQLException {
         int jumlahAktif=0;
         boolean tujuanAktif=false;
         boolean waktuTujuanSesuai=pilihan==2;
         try(PreparedStatement perintah=koneksi.prepareStatement(
                 "select kd_kamar,date_format(tgl_masuk,'%Y-%m-%d') as tgl_masuk,"+
                 "time_format(jam_masuk,'%H:%i:%s') as jam_masuk from kamar_inap " +
                 "where no_rawat=? and stts_pulang='-' for update")){
             perintah.setString(1,pindahNoRawatAsal);
             try(ResultSet hasil=perintah.executeQuery()){
                 while(hasil.next()){
                     jumlahAktif++;
                     if(hasil.getString("kd_kamar").equals(kamarTujuan)){
                         tujuanAktif=true;
                         if(pilihan!=2&&hasil.getString("tgl_masuk").equals(tanggalPindah)&&
                                 hasil.getString("jam_masuk").equals(jamPindah)){
                             waktuTujuanSesuai=true;
                         }
                     }
                 }
             }
         }
         if(jumlahAktif!=1||!tujuanAktif){
             throw new SQLException("Verifikasi gagal: pasien tidak memiliki tepat satu kamar tujuan yang aktif.");
         }
         if(!waktuTujuanSesuai){
             throw new SQLException("Verifikasi gagal: waktu masuk kamar tujuan tidak sesuai waktu pindah.");
         }

         if(pilihan==1){
             try(PreparedStatement perintah=koneksi.prepareStatement(
                     "select count(*) from kamar_inap where no_rawat=? and kd_kamar=? and tgl_masuk=? and jam_masuk=?")){
                 isiKunciKamarAsal(perintah);
                 try(ResultSet hasil=perintah.executeQuery()){
                     if(!hasil.next()||hasil.getInt(1)!=0){
                         throw new SQLException("Verifikasi gagal: kamar lama pilihan 1 belum terhapus.");
                     }
                 }
             }
         }else if(pilihan==3||pilihan==4){
             try(PreparedStatement perintah=koneksi.prepareStatement(
                     "select count(*) from kamar_inap where no_rawat=? and kd_kamar=? and tgl_masuk=? and jam_masuk=? " +
                     "and stts_pulang='Pindah Kamar' and tgl_keluar=? and jam_keluar=?")){
                 isiKunciKamarAsal(perintah);
                 perintah.setString(5,tanggalPindah);
                 perintah.setString(6,jamPindah);
                 try(ResultSet hasil=perintah.executeQuery()){
                     if(!hasil.next()||hasil.getInt(1)!=1){
                         throw new SQLException("Verifikasi gagal: waktu keluar kamar asal tidak sama dengan waktu masuk kamar tujuan.");
                     }
                 }
             }
         }

         // PATCH RSAJ V11: kamar asal tidak selalu KOSONG. Pada kamar yang
         // masih ditempati pasien aktif lain, status akhir yang benar adalah
         // ISI. Verifikasi harus mengikuti hasil perhitungan tersebut.
         if(!getStatusKamarTerkunci(pindahKdKamarAsal).equals(statusKamarAsalAkhir)||
                 !getStatusKamarTerkunci(kamarTujuan).equals("ISI")){
             throw new SQLException("Verifikasi gagal: status kamar asal seharusnya "+
                     statusKamarAsalAkhir+" atau status kamar tujuan belum ISI.");
         }
     }

     private void pastikanSatuBaris(int jumlah,String proses) throws SQLException {
         if(jumlah!=1){
             throw new SQLException("Gagal "+proses+". Jumlah data yang berubah: "+jumlah+".");
         }
     }

     private String escapeHtmlPindah(String nilai) {
         if(nilai==null) return "";
         return nilai.replace("&","&amp;").replace("<","&lt;").replace(">","&gt;")
                 .replace("\"","&quot;").replace("'","&#39;");
     }
 
