     private void MnDepositActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_MnDepositActionPerformed
         if(tabMode.getRowCount()==0){
             JOptionPane.showMessageDialog(null,"Maaf, table masih kosong...!!!!");
             TCari.requestFocus();
         }else{
             if(tbKamIn.getSelectedRow()>-1){
                 if(tbKamIn.getValueAt(tbKamIn.getSelectedRow(),0).toString().equals("")){
                     try {
                         psanak=koneksi.prepareStatement(
                             "select ranap_gabung.no_rawat2 from ranap_gabung where ranap_gabung.no_rawat=?");
                         try {
                             psanak.setString(1,tbKamIn.getValueAt(tbKamIn.getSelectedRow()-1,0).toString());
                             rs2=psanak.executeQuery();
                             if(rs2.next()){
                                 getBilling().deposit.setSize(internalFrame1.getWidth()-20,internalFrame1.getHeight()-20);
                                 getBilling().deposit.setLocationRelativeTo(internalFrame1);
                                 if(R1.isSelected()==true){
                                     getBilling().deposit.setNoRm(rs2.getString("no_rawat2"),new Date(),new Date());
                                 }else if(R2.isSelected()==true){
                                     getBilling().deposit.setNoRm(rs2.getString("no_rawat2"),DTPCari1.getDate(),DTPCari2.getDate());
                                 }else if(R3.isSelected()==true){
                                     getBilling().deposit.setNoRm(rs2.getString("no_rawat2"),DTPCari3.getDate(),DTPCari4.getDate());
                                 }
                                 getBilling().deposit.tampil();
                                 getBilling().deposit.setVisible(true);
                             }else{
                                 JOptionPane.showMessageDialog(null,"Maaf, Silahkan anda pilih dulu pasien...!!!");
                                 tbKamIn.requestFocus();
                             }
                         }catch(Exception ex){
                             System.out.println("Notifikasi : "+ex);
                         }finally{
                             if(rs2 != null){
                                 rs2.close();
                             }
                             if(psanak != null){
                                 psanak.close();
                             }
                         }
                     } catch (Exception e) {
                         System.out.println(e);
                     }
                 }else{
                     getBilling().deposit.setSize(internalFrame1.getWidth()-20,internalFrame1.getHeight()-20);
                     getBilling().deposit.setLocationRelativeTo(internalFrame1);
                     if(R1.isSelected()==true){
                         getBilling().deposit.setNoRm(norawat.getText(),new Date(),new Date());
                     }else if(R2.isSelected()==true){
                         getBilling().deposit.setNoRm(norawat.getText(),DTPCari1.getDate(),DTPCari2.getDate());
                     }else if(R3.isSelected()==true){
                         getBilling().deposit.setNoRm(norawat.getText(),DTPCari3.getDate(),DTPCari4.getDate());
                     }
                     getBilling().deposit.tampil();
                     getBilling().deposit.setVisible(true);
                 }
             }
         } 
     }//GEN-LAST:event_MnDepositActionPerformed
 
