     private String getNoRawatBerkasTerpilih() {
         String noRawatTerpilih = "";
         if (tbKamIn.getSelectedRow() > -1) {
             noRawatTerpilih = tbKamIn.getValueAt(tbKamIn.getSelectedRow(), 0).toString().trim();
             if (noRawatTerpilih.equals("") && tbKamIn.getSelectedRow() > 0) {
                 try {
                     psanak = koneksi.prepareStatement("select ranap_gabung.no_rawat2 from ranap_gabung where ranap_gabung.no_rawat=?");
                     try {
                         psanak.setString(1, tbKamIn.getValueAt(tbKamIn.getSelectedRow() - 1, 0).toString());
                         rs2 = psanak.executeQuery();
                         if (rs2.next()) {
                             noRawatTerpilih = rs2.getString("no_rawat2");
                         }
                     } catch (Exception ex) {
                         System.out.println("Notifikasi : " + ex);
                     } finally {
                         if (rs2 != null) {
                             rs2.close();
                         }
                         if (psanak != null) {
                             psanak.close();
                         }
                     }
                 } catch (Exception ex) {
                     System.out.println("Notifikasi : " + ex);
                 }
             }
         }
         return noRawatTerpilih;
     }

     /** Data satu berkas hasil Lab/Radiologi yang ditampilkan pada browser. */
     private void bukaDlgHasilPenunjang(String jenis) {
         String noRawatTerpilih = getNoRawatBerkasTerpilih();
         if (noRawatTerpilih.equals("")) {
             JOptionPane.showMessageDialog(null, "Maaf, silahkan pilih dulu data pasien...!!!");
             tbKamIn.requestFocus();
             return;
         }
         DlgHasilPenunjang.buka(this, noRawatTerpilih, jenis);
     }

     private void refreshTombolHasilLabRad() {
         DlgHasilPenunjang.refreshTombolAsync(getNoRawatBerkasTerpilih(), BtnHasilLab, BtnHasilRad, panelCari, 23);
     }

     

