    private void BtnResumeRI2ActionPerformed(java.awt.event.ActionEvent evt) {                                             
    //MODIF MUSTAFA
    if (tabMode.getRowCount() == 0) {
        JOptionPane.showMessageDialog(null, "Maaf, tabel masih kosong...!!!!");
        TCari.requestFocus();
    } else {
        if (tbKamIn.getSelectedRow() > -1) {
            if (tbKamIn.getValueAt(tbKamIn.getSelectedRow(), 0).toString().equals("")) {
                try {
                    psanak = koneksi.prepareStatement(
                        "SELECT ranap_gabung.no_rawat2 " +
                        "FROM ranap_gabung " +
                        "WHERE ranap_gabung.no_rawat = ?"
                    );
                    try {
                        psanak.setString(1, tbKamIn.getValueAt(tbKamIn.getSelectedRow() - 1, 0).toString());
                        rs2 = psanak.executeQuery();
                        if (rs2.next()) {
                            // Cek apakah SEP sudah ada
                            ps = koneksi.prepareStatement(
                                "SELECT * " +
                                "FROM bridging_sep " +
                                "WHERE bridging_sep.no_rawat = ?"
                            );
                            ps.setString(1, rs2.getString("no_rawat2"));
                            rs = ps.executeQuery();
                            if (rs.next()) {
                                // Cek kondisi jnspelayanan menggunakan query CASE
                                ps = koneksi.prepareStatement(
                                    "SELECT * " +
                                    "FROM bridging_sep " +
                                    "WHERE bridging_sep.no_rawat = ? " +
                                    "  AND bridging_sep.jnspelayanan = ( " +
                                    "      CASE " +
                                    "          WHEN EXISTS ( " +
                                    "              SELECT 1 " +
                                    "              FROM reg_periksa " +
                                    "              WHERE reg_periksa.no_rawat = bridging_sep.no_rawat " +
                                    "                AND reg_periksa.status_lanjut = 'Ranap' " +
                                    "                AND reg_periksa.kd_poli = 'IGDK' " +
                                    "          ) THEN '1' " +
                                    "          WHEN EXISTS ( " +
                                    "              SELECT 1 " +
                                    "              FROM reg_periksa " +
                                    "              WHERE reg_periksa.no_rawat = bridging_sep.no_rawat " +
                                    "                AND reg_periksa.status_lanjut = 'Ranap' " +
                                    "                AND reg_periksa.kd_poli <> 'IGDK' " +
                                    "          ) THEN '1' " +
                                    "      END " +
                                    "  );"
                                );
                                ps.setString(1, rs2.getString("no_rawat2"));
                                rs = ps.executeQuery();
                                if (rs.next()) {
                                    // Jika query mengembalikan data, lanjutkan membuka BPJSSuratKontrol
                                    this.setCursor(Cursor.getPredefinedCursor(Cursor.WAIT_CURSOR));
                                    BPJSSuratKontrol form = new BPJSSuratKontrol(null, false);
                                    form.setNoRm(
                                        rs.getString("no_rawat"),
                                        rs.getString("no_sep"),
                                        rs.getString("no_kartu"),
                                        rs.getString("nomr"),
                                        rs.getString("nama_pasien"),
                                        rs.getString("tanggal_lahir"),
                                        rs.getString("jkel"),
                                        rs.getString("nmdiagnosaawal")
                                    );
                                    form.setSize(internalFrame1.getWidth() - 20, internalFrame1.getHeight() - 20);
                                    form.setLocationRelativeTo(internalFrame1);
                                    form.setVisible(true);
                                    this.setCursor(Cursor.getDefaultCursor());
                                } else {
                                    JOptionPane.showMessageDialog(null, "Pasien tersebut belum terbit SEP dengan kondisi yang sesuai, silahkan hubungi bagian terkait..!!");
                                    TCari.requestFocus();
                                }
                            } else {
                                JOptionPane.showMessageDialog(null, "Pasien tersebut belum terbit SEP, silahkan hubungi bagian terkait..!!");
                                TCari.requestFocus();
                            }
                        } else {
                            JOptionPane.showMessageDialog(null, "Maaf, Silahkan anda pilih dulu pasien...!!!");
                            tbKamIn.requestFocus();
                        }
                    } catch (Exception ex) {
                        System.out.println("Notifikasi : " + ex);
                    } finally {
                        if (rs2 != null) {
                            rs2.close();
                        }
                        if (psanak != null) {
                            psanak.close();
                        }
                    }
                } catch (Exception e) {
                    System.out.println(e);
                }
            } else {
                // Pengecekan SEP untuk kondisi lain
                try {
                    ps = koneksi.prepareStatement(
                        "SELECT * " +
                        "FROM bridging_sep " +
                        "WHERE bridging_sep.no_rawat = ?"
                    );
                    ps.setString(1, norawat.getText());
                    rs = ps.executeQuery();
                    if (rs.next()) {
                        // Cek kondisi jnspelayanan menggunakan query CASE
                        ps = koneksi.prepareStatement(
                            "SELECT * " +
                            "FROM bridging_sep " +
                            "WHERE bridging_sep.no_rawat = ? " +
                            "  AND bridging_sep.jnspelayanan = ( " +
                            "      CASE " +
                            "          WHEN EXISTS ( " +
                            "              SELECT 1 " +
                            "              FROM reg_periksa " +
                            "              WHERE reg_periksa.no_rawat = bridging_sep.no_rawat " +
                            "                AND reg_periksa.status_lanjut = 'Ranap' " +
                            "                AND reg_periksa.kd_poli = 'IGDK' " +
                            "          ) THEN '1' " +
                            "          WHEN EXISTS ( " +
                            "              SELECT 1 " +
                            "              FROM reg_periksa " +
                            "              WHERE reg_periksa.no_rawat = bridging_sep.no_rawat " +
                            "                AND reg_periksa.status_lanjut = 'Ranap' " +
                            "                AND reg_periksa.kd_poli <> 'IGDK' " +
                            "          ) THEN '1' " +
                            "      END " +
                            "  );"
                        );
                        ps.setString(1, norawat.getText());
                        rs = ps.executeQuery();
                        if (rs.next()) {
                            // Jika query mengembalikan data, lanjutkan membuka BPJSSuratKontrol
                            this.setCursor(Cursor.getPredefinedCursor(Cursor.WAIT_CURSOR));
                            BPJSSuratKontrol form = new BPJSSuratKontrol(null, false);
                            form.setNoRm(
                                rs.getString("no_rawat"),
                                rs.getString("no_sep"),
                                rs.getString("no_kartu"),
                                rs.getString("nomr"),
                                rs.getString("nama_pasien"),
                                rs.getString("tanggal_lahir"),
                                rs.getString("jkel"),
                                rs.getString("nmdiagnosaawal")
                            );
                            form.setSize(internalFrame1.getWidth() - 20, internalFrame1.getHeight() - 20);
                            form.setLocationRelativeTo(internalFrame1);
                            form.setVisible(true);
                            this.setCursor(Cursor.getDefaultCursor());
                        } else {
                            JOptionPane.showMessageDialog(null, "Pasien tersebut belum terbit SEP dengan kondisi yang sesuai, silahkan hubungi bagian terkait..!!");
                            TCari.requestFocus();
                        }
                    } else {
                        JOptionPane.showMessageDialog(null, "Pasien tersebut belum terbit SEP, silahkan hubungi bagian terkait..!!");
                        TCari.requestFocus();
                    }
                } catch (Exception e) {
                    System.out.println("Notif : " + e);
                }
            }
        }
    }
    //END MODIF MUSTAFA
}

