    private void MnTerindikasiTBActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_MnTerindikasiTBActionPerformed
        String noRawat = TNoRwCari.getText().trim();   // dari DlgKasirRalan
        if (noRawat.isEmpty()) {
            JOptionPane.showMessageDialog(this, "No. Rawat belum diisi/dipilih.");
            TNoRwCari.requestFocus();
            return;
        }

        try {
            // cari parent Frame kalau ada; kalau tidak ada, biarkan null
            java.awt.Frame parent = null;
            java.awt.Window w = javax.swing.SwingUtilities.getWindowAncestor(this);
            if (w instanceof java.awt.Frame) parent = (java.awt.Frame) w;

            VerifikasiTB dlg = new VerifikasiTB(parent, true);  // JDialog modal
            dlg.setNoRawat(noRawat);                            // mapping: TNoRwCari -> TNoRwCari
            dlg.setLocationRelativeTo(this);                    // center relatif form ini
            dlg.setVisible(true);                               // tampilkan
        } catch (Exception e) {
            System.out.println("Notifikasi MnTerindikasiTB : " + e.getMessage());
            JOptionPane.showMessageDialog(this, "Gagal membuka Verifikasi TB.\n" + e.getMessage());
        }
    }//GEN-LAST:event_MnTerindikasiTBActionPerformed

