    private void btnDiagnosaActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_btnDiagnosaActionPerformed
        if(norawat.getText().trim().equals("")){
            JOptionPane.showMessageDialog(null,"Maaf, Silahkan anda pilih dulu pasien...!!!");
            tbKamIn.requestFocus();
        }else{
            akses.setform("DlgKamarInap");
            getDiagnosa().setSize(internalFrame1.getWidth()-20,internalFrame1.getHeight()-20);
            getDiagnosa().setLocationRelativeTo(internalFrame1);
            getDiagnosa().isCek();
            if(R1.isSelected()==true){
                getDiagnosa().setNoRm(norawat.getText(),new Date(),new Date(),"Ranap");
            }else if(R2.isSelected()==true){
                getDiagnosa().setNoRm(norawat.getText(),DTPCari1.getDate(),DTPCari2.getDate(),"Ranap");
            }else if(R3.isSelected()==true){
                getDiagnosa().setNoRm(norawat.getText(),DTPCari3.getDate(),DTPCari4.getDate(),"Ranap");
            }
            getDiagnosa().panelDiagnosa1.tampil();
            getDiagnosa().setVisible(true);
        }
    }//GEN-LAST:event_btnDiagnosaActionPerformed

