    // TODO DOBEL BED INIT BARU: pembuka dialog dobel bed baru dengan perubahan minimal di file ini
    private void bukaInputDobelBedInitBaru() {
        if(tabMode.getRowCount()==0){
            JOptionPane.showMessageDialog(null,"Maaf, table masih kosong...!!!!");
            TCari.requestFocus();
            return;
        }

        if(tbKamIn.getSelectedRow()==-1){
            JOptionPane.showMessageDialog(null,"Maaf, silahkan pilih dulu pasien pada tabel...!!!");
            tbKamIn.requestFocus();
            return;
        }

        if(tbKamIn.getValueAt(tbKamIn.getSelectedRow(),0).toString().trim().equals("")){
            JOptionPane.showMessageDialog(null,"Maaf, pilih baris utama pasien terlebih dahulu...!!!");
            tbKamIn.requestFocus();
            return;
        }

        if(dobelBedInitBaru==null){
            dobelBedInitBaru = new DlgInputDobelBed(this);
        }

        dobelBedInitBaru.bukaDariKamarInap(
            tbKamIn.getValueAt(tbKamIn.getSelectedRow(),0).toString(),
            tbKamIn.getValueAt(tbKamIn.getSelectedRow(),1).toString(),
            tbKamIn.getValueAt(tbKamIn.getSelectedRow(),2).toString(),
            tbKamIn.getValueAt(tbKamIn.getSelectedRow(),19).toString(),
            tbKamIn.getValueAt(tbKamIn.getSelectedRow(),11).toString(),
            tbKamIn.getValueAt(tbKamIn.getSelectedRow(),12).toString()
        );
    }

