private void jadwalkanTampilPencarian() {
    if (timerPencarianRawatInap == null) {
        timerPencarianRawatInap = new javax.swing.Timer(300, new ActionListener() {
            @Override
            public void actionPerformed(ActionEvent e) {
                timerPencarianRawatInap.stop();
                tampil();
            }
        });
        timerPencarianRawatInap.setRepeats(false);
    }
    timerPencarianRawatInap.restart();
}

private String buatKunciMuatData() {
    try {
        return R1.isSelected()+"|"+R2.isSelected()+"|"+R3.isSelected()+"|"+
                Valid.SetTgl(DTPCari1.getSelectedItem()+"")+"|"+
                Valid.SetTgl(DTPCari2.getSelectedItem()+"")+"|"+
                Valid.SetTgl(DTPCari3.getSelectedItem()+"")+"|"+
                Valid.SetTgl(DTPCari4.getSelectedItem()+"")+"|"+
                cmbStatusBayar.getSelectedItem()+"|"+BangsalCari.getText()+"|"+
                TCari.getText().trim()+"|"+terbitsep+"|"+updatepulangbpjs+"|"+order;
    } catch (Exception ex) {
        return String.valueOf(System.nanoTime());
    }
}

private void tampil() {
    final String kunciPermintaan = buatKunciMuatData();
    if (sedangMemuatData) {
        // isCek() dan windowOpened dapat meminta data yang sama hampir bersamaan.
        // Muat ulang hanya bila filter benar-benar berubah saat worker masih berjalan.
        if (!kunciPermintaan.equals(kunciMuatDataAktif)) {
            muatUlangData = true;
        }
        return;
    }

    sedangMemuatData = true;
    muatUlangData = false;
    kunciMuatDataAktif = kunciPermintaan;
    Valid.tabelKosong(tabMode);
    cacheKelasRawat.clear();
    cacheKelasRawatAnak.clear();
    tampilkanKelasRawat("");
    LCount.setText("Memuat...");

    // Seluruh nilai komponen Swing disalin di EDT sebelum worker berjalan.
    final boolean filterAktif = R1.isSelected();
    final boolean filterTanggalMasuk = R2.isSelected();
    final String tanggalMasukAwal = Valid.SetTgl(DTPCari1.getSelectedItem() + "");
    final String tanggalMasukAkhir = Valid.SetTgl(DTPCari2.getSelectedItem() + "");
    final String tanggalKeluarAwal = Valid.SetTgl(DTPCari3.getSelectedItem() + "");
    final String tanggalKeluarAkhir = Valid.SetTgl(DTPCari4.getSelectedItem() + "");
    final String statusBayarSaatIni = cmbStatusBayar.getSelectedItem().toString().replaceAll("Semua", "");
    final String bangsalSaatIni = BangsalCari.getText();
    final String kataCari = TCari.getText().trim();
    final String kodePengguna = akses.getkode();
    final String filterSepSaatIni = terbitsep;
    final String filterPulangSaatIni = updatepulangbpjs;
    final String urutanSaatIni = order;
    final double persenBayiSaatIni = persenbayi;
    final long mulaiMuat = System.nanoTime();

    new SwingWorker<Void,Object[]>() {
        private int jumlahBaris = 0;

        @Override
        protected Void doInBackground() {
            PreparedStatement perintah = null;
            PreparedStatement perintahAnak = null;
            ResultSet hasil = null;
            ResultSet hasilAnak = null;
            try {
                String kondisiKamar;
                if (filterAktif) {
                    kondisiKamar = " kamar_inap.stts_pulang='-' and reg_periksa.status_bayar like '%" +
                            statusBayarSaatIni + "%' ";
                    if (!bangsalSaatIni.equals("")) {
                        kondisiKamar = " kamar_inap.stts_pulang='-' and bangsal.nm_bangsal='" +
                                bangsalSaatIni + "' and reg_periksa.status_bayar like '%" +
                                statusBayarSaatIni + "%' ";
                    }
                } else if (filterTanggalMasuk) {
                    kondisiKamar = " kamar_inap.tgl_masuk between '" + tanggalMasukAwal +
                            "' and '" + tanggalMasukAkhir +
                            "' and reg_periksa.status_bayar like '%" + statusBayarSaatIni + "%' ";
                    if (!bangsalSaatIni.equals("")) {
                        kondisiKamar = " kamar_inap.tgl_masuk between '" + tanggalMasukAwal +
                                "' and '" + tanggalMasukAkhir + "' and bangsal.nm_bangsal='" +
                                bangsalSaatIni + "' and reg_periksa.status_bayar like '%" +
                                statusBayarSaatIni + "%' ";
                    }
                } else {
                    kondisiKamar = " kamar_inap.tgl_keluar between '" + tanggalKeluarAwal +
                            "' and '" + tanggalKeluarAkhir +
                            "' and reg_periksa.status_bayar like '%" + statusBayarSaatIni + "%' ";
                    if (!bangsalSaatIni.equals("")) {
                        kondisiKamar = " kamar_inap.tgl_keluar between '" + tanggalKeluarAwal +
                                "' and '" + tanggalKeluarAkhir + "' and bangsal.nm_bangsal='" +
                                bangsalSaatIni + "' and reg_periksa.status_bayar like '%" +
                                statusBayarSaatIni + "%' ";
                    }
                }

                boolean penggunaDokter = false;
                boolean penggunaMppAktif = false;
                try (PreparedStatement cekDokter = koneksi.prepareStatement(
                        "SELECT COUNT(d.kd_dokter) FROM dokter d WHERE d.kd_dokter=?")) {
                    cekDokter.setString(1,kodePengguna);
                    try (ResultSet hasilCekDokter = cekDokter.executeQuery()) {
                        penggunaDokter = hasilCekDokter.next() && hasilCekDokter.getInt(1)>0;
                    }
                }
                if (penggunaDokter) {
                    try (PreparedStatement cekMpp = koneksi.prepareStatement(
                            "SELECT COUNT(mp.id) FROM dokter_mpp mp WHERE mp.kd_dokter=? AND mp.`status`=1")) {
                        cekMpp.setString(1,kodePengguna);
                        try (ResultSet hasilCekMpp = cekMpp.executeQuery()) {
                            penggunaMppAktif = hasilCekMpp.next() && hasilCekMpp.getInt(1)>0;
                        }
                    }
                }

                final boolean batasiDpjp = penggunaDokter && !penggunaMppAktif;
                String kondisiData;
                if (!kataCari.equals("")) {
                    kondisiData = kondisiKamar +
                            "and (kamar_inap.no_rawat like '%" + kataCari +
                            "%' or reg_periksa.no_rkm_medis like '%" + kataCari +
                            "%' or pasien.nm_pasien like '%" + kataCari +
                            "%' or concat(pasien.alamat,', ',kelurahan.nm_kel,', ',kecamatan.nm_kec,', ',kabupaten.nm_kab) like '%" +
                            kataCari + "%' or kamar_inap.kd_kamar like '%" + kataCari +
                            "%' or bangsal.nm_bangsal like '%" + kataCari +
                            "%' or kamar_inap.diagnosa_awal like '%" + kataCari +
                            "%' or kamar_inap.diagnosa_akhir like '%" + kataCari +
                            "%' or kamar_inap.tgl_masuk like '%" + kataCari +
                            "%' or dokter.nm_dokter like '%" + kataCari +
                            "%' or kamar_inap.stts_pulang like '%" + kataCari +
                            "%' or kamar_inap.tgl_keluar like '%" + kataCari +
                            "%' or penjab.png_jawab like '%" + kataCari +
                            "%' or pasien.agama like '%" + kataCari + "%') ";
                    if (batasiDpjp) {
                        kondisiData += "AND dj.kd_dokter like '%" + kodePengguna + "%' ";
                    } else {
                        kondisiData += filterSepSaatIni + filterPulangSaatIni;
                    }
                } else if (batasiDpjp) {
                    kondisiData = kondisiKamar + "and dj.kd_dokter='" + kodePengguna + "' ";
                } else {
                    kondisiData = kondisiKamar + " " + filterSepSaatIni + filterPulangSaatIni;
                }

                String acuanTanggal =
                        "IF(kamar_inap.tgl_keluar='0000-00-00' OR kamar_inap.stts_pulang='-', CURDATE(), kamar_inap.tgl_keluar)";
                String lamaTampil =
                        "IF(DATEDIFF(" + acuanTanggal + ", kamar_inap.tgl_masuk)=0,1,DATEDIFF(" +
                        acuanTanggal + ", kamar_inap.tgl_masuk))";
                String joinDpjp = batasiDpjp
                        ? "INNER JOIN dpjp_ranap dj ON kamar_inap.no_rawat=dj.no_rawat "
                        : "";

                perintah = koneksi.prepareStatement(
                        "SELECT DISTINCT kamar_inap.no_rawat, reg_periksa.no_rkm_medis, pasien.nm_pasien, pasien.no_peserta as no_peserta_pasien, " +
                        "CONCAT(pasien.alamat, ', ', kelurahan.nm_kel, ', ', kecamatan.nm_kec, ', ', kabupaten.nm_kab) AS alamat, " +
                        "reg_periksa.p_jawab, reg_periksa.hubunganpj, penjab.png_jawab, " +
                        "CONCAT(kamar_inap.kd_kamar, ' ', bangsal.nm_bangsal) AS kamar, kamar_inap.trf_kamar, kamar_inap.diagnosa_awal, " +
                        "kamar_inap.diagnosa_akhir, kamar_inap.tgl_masuk, kamar_inap.jam_masuk, " +
                        "IF(kamar_inap.tgl_keluar='0000-00-00','',kamar_inap.tgl_keluar) AS tgl_keluar, " +
                        "IF(kamar_inap.jam_keluar='00:00:00','',kamar_inap.jam_keluar) AS jam_keluar, " +
                        "kamar_inap.ttl_biaya, kamar_inap.stts_pulang, " + lamaTampil +
                        " AS lama_tampil, COALESCE(NULLIF(GROUP_CONCAT(DISTINCT dokter_dpjp.nm_dokter ORDER BY dokter_dpjp.nm_dokter SEPARATOR '   |   '),''),dokter.nm_dokter) AS dokter_tampil, kamar_inap.kd_kamar, reg_periksa.kd_pj, " +
                        "CONCAT(reg_periksa.umurdaftar, ' ', reg_periksa.sttsumur) AS umur, " +
                        "reg_periksa.status_bayar, MAX(bs_main.no_sep) AS no_sep, " +
                        "MAX(bs_main.klsrawat) AS klsrawat, pasien.agama, " +
                        "IF(plg.rencana_pulang IS NOT NULL, '1', '0') AS rencana_pulang, IF(rg_flag.no_rawat IS NULL,0,1) AS ada_anak " +
                        "FROM kamar_inap " +
                        "INNER JOIN reg_periksa ON kamar_inap.no_rawat=reg_periksa.no_rawat " +
                        "INNER JOIN pasien ON reg_periksa.no_rkm_medis=pasien.no_rkm_medis " +
                        "INNER JOIN kamar ON kamar_inap.kd_kamar=kamar.kd_kamar " +
                        "INNER JOIN bangsal ON kamar.kd_bangsal=bangsal.kd_bangsal " +
                        "INNER JOIN kelurahan ON pasien.kd_kel=kelurahan.kd_kel " +
                        "INNER JOIN kecamatan ON pasien.kd_kec=kecamatan.kd_kec " +
                        "INNER JOIN kabupaten ON pasien.kd_kab=kabupaten.kd_kab " +
                        "INNER JOIN dokter ON reg_periksa.kd_dokter=dokter.kd_dokter " +
                        "LEFT JOIN dpjp_ranap dpjp_semua ON kamar_inap.no_rawat=dpjp_semua.no_rawat " +
                        "LEFT JOIN dokter dokter_dpjp ON dpjp_semua.kd_dokter=dokter_dpjp.kd_dokter " +
                        "INNER JOIN penjab ON reg_periksa.kd_pj=penjab.kd_pj " +
                        "LEFT JOIN perencanaan_pemulangan plg ON reg_periksa.no_rawat=plg.no_rawat " +
                        "LEFT JOIN (SELECT DISTINCT no_rawat FROM ranap_gabung) rg_flag ON rg_flag.no_rawat=kamar_inap.no_rawat " +
                        joinDpjp +
                        "LEFT JOIN bridging_sep bs_main ON bs_main.no_rawat=reg_periksa.no_rawat AND bs_main.jnspelayanan='1' " +
                        "WHERE " + kondisiData +
                        " GROUP BY kamar_inap.no_rawat,kamar_inap.tgl_masuk,kamar_inap.jam_masuk " +
                        urutanSaatIni
                );

                perintahAnak = koneksi.prepareStatement(
                        "SELECT DISTINCT pasien.no_rkm_medis,pasien.nm_pasien,ranap_gabung.no_rawat2, " +
                        "CONCAT(reg_periksa.umurdaftar,' ',reg_periksa.sttsumur) AS umur,pasien.no_peserta, " +
                        "CONCAT(pasien.alamatpj,', ',pasien.kelurahanpj,', ',pasien.kecamatanpj,', ',pasien.kabupatenpj) AS alamat, " +
                        "pasien.agama,bsr.no_sep,bsr.klsrawat,IF(plg.rencana_pulang IS NOT NULL,'1','0') AS rencana_pulang " +
                        "FROM reg_periksa " +
                        "INNER JOIN pasien ON pasien.no_rkm_medis=reg_periksa.no_rkm_medis " +
                        "INNER JOIN ranap_gabung ON ranap_gabung.no_rawat2=reg_periksa.no_rawat " +
                        "LEFT JOIN (SELECT bs.no_rawat,MAX(bs.no_sep) AS no_sep,MAX(bs.klsrawat) AS klsrawat FROM bridging_sep bs " +
                        "WHERE bs.jnspelayanan='1' GROUP BY bs.no_rawat) bsr ON bsr.no_rawat=reg_periksa.no_rawat " +
                        "LEFT JOIN perencanaan_pemulangan plg ON reg_periksa.no_rawat=plg.no_rawat " +
                        "WHERE ranap_gabung.no_rawat=?"
                );

                hasil = perintah.executeQuery();
                while (hasil.next()) {
                    final String noRawat = hasil.getString("no_rawat");
                    String kelasRawat = hasil.getString("klsrawat");
                    cacheKelasRawat.put(noRawat, kelasRawat == null ? "" : kelasRawat.trim());
                    String noPesertaPasien = hasil.getString("no_peserta_pasien");
                    cacheNoKartuPasien.put(hasil.getString("no_rkm_medis"), noPesertaPasien == null ? "" : noPesertaPasien);
                    String dokterTampil = hasil.getString("dokter_tampil");
                    if (dokterTampil == null || dokterTampil.trim().equals("")) {
                        dokterTampil = "";
                    }

                    jumlahBaris++;
                    publish(new Object[]{
                        hasil.getString("no_rawat"),hasil.getString("no_rkm_medis"),
                        hasil.getString("nm_pasien")+" ("+hasil.getString("umur")+")",
                        hasil.getString("alamat"),hasil.getString("p_jawab"),
                        hasil.getString("hubunganpj"),hasil.getString("png_jawab"),
                        hasil.getString("kamar"),Valid.SetAngka(hasil.getDouble("trf_kamar")),
                        hasil.getString("diagnosa_awal"),hasil.getString("diagnosa_akhir"),
                        hasil.getString("tgl_masuk"),hasil.getString("jam_masuk"),
                        hasil.getString("tgl_keluar"),hasil.getString("jam_keluar"),
                        Valid.SetAngka(hasil.getDouble("ttl_biaya")),hasil.getString("stts_pulang"),
                        hasil.getString("lama_tampil"),dokterTampil,hasil.getString("kd_kamar"),
                        hasil.getString("status_bayar"),hasil.getString("agama"),
                        hasil.getString("no_sep"),hasil.getString("rencana_pulang")
                    });

                    if (hasil.getInt("ada_anak") == 1) {
                        perintahAnak.setString(1,noRawat);
                        hasilAnak = perintahAnak.executeQuery();
                    } else {
                        hasilAnak = null;
                    }
                    if (hasilAnak != null && hasilAnak.next()) {
                        String kelasRawatAnak = hasilAnak.getString("klsrawat");
                        cacheKelasRawatAnak.put(hasilAnak.getString("no_rkm_medis"),
                                kelasRawatAnak == null ? "" : kelasRawatAnak.trim());
                        String noPesertaAnak = hasilAnak.getString("no_peserta");
                        cacheNoKartuPasien.put(hasilAnak.getString("no_rkm_medis"), noPesertaAnak == null ? "" : noPesertaAnak);
                        jumlahBaris++;
                        publish(new Object[]{
                            "",hasilAnak.getString("no_rkm_medis"),
                            hasilAnak.getString("nm_pasien")+" ("+hasilAnak.getString("umur")+")",
                            hasil.getString("alamat"),hasil.getString("p_jawab"),
                            hasil.getString("hubunganpj"),hasil.getString("png_jawab"),
                            hasil.getString("kamar"),
                            Valid.SetAngka(hasil.getDouble("trf_kamar")*(persenBayiSaatIni/100)),
                            "","",hasil.getString("tgl_masuk"),hasil.getString("jam_masuk"),
                            hasil.getString("tgl_keluar"),hasil.getString("jam_keluar"),
                            Valid.SetAngka(hasil.getDouble("ttl_biaya")*(persenBayiSaatIni/100)),
                            hasil.getString("stts_pulang"),hasil.getString("lama_tampil"),
                            dokterTampil,hasil.getString("kd_kamar"),hasil.getString("status_bayar"),
                            hasil.getString("agama"),hasil.getString("no_sep"),
                            hasil.getString("rencana_pulang")
                        });
                    }
                    if (hasilAnak != null) {
                        hasilAnak.close();
                        hasilAnak = null;
                    }
                }
            } catch (Exception e) {
                System.out.println("Notifikasi muat Rawat Inap : " + e);
            } finally {
                try {
                    if (hasilAnak != null) hasilAnak.close();
                    if (hasil != null) hasil.close();
                    if (perintahAnak != null) perintahAnak.close();
                    if (perintah != null) perintah.close();
                } catch (Exception e) {
                    System.out.println("Notifikasi tutup query Rawat Inap : " + e);
                }
            }
            return null;
        }

        @Override
        protected void process(List<Object[]> data) {
            for (Object[] baris : data) {
                tabMode.addRow(baris);
            }
            LCount.setText("" + tabMode.getRowCount());
        }

        @Override
        protected void done() {
            sedangMemuatData = false;
            LCount.setText("" + tabMode.getRowCount());
            System.out.println("[PERFORMA MODUL] Data Rawat Inap selesai dalam " +
                    ((System.nanoTime()-mulaiMuat)/1_000_000L) + " ms (" +
                    jumlahBaris + " baris)");
            if (muatUlangData) {
                muatUlangData = false;
                kunciMuatDataAktif = "";
                tampil();
            } else {
                kunciMuatDataAktif = "";
            }
        }
    }.execute();
}

