             TNoSEP.setText(tbKamIn.getValueAt(tbKamIn.getSelectedRow(),22).toString());             
             tampilkanKelasRawat(noRawatTerpilih.trim().equals("")
                     ? cacheKelasRawatAnak.get(noRMTerpilih)
                     : cacheKelasRawat.get(noRawatTerpilih));
