private void cekStatusBayarBPJS(String noRawat) {

    if (sudahCekStatusBayar) {
        System.out.println("DEBUG: Lewat, sudah pernah cekStatusBayarBPJS");
        return; // hindari dobel
    }
    sudahCekStatusBayar = true;

    Connection koneksi = koneksiDB.condb(); // Koneksi DB lo
    PreparedStatement ps = null;
    ResultSet rs = null;

    try {
        String sql = "SELECT kd_pj FROM reg_periksa WHERE no_rawat = ?";
        ps = koneksi.prepareStatement(sql);
        ps.setString(1, noRawat);
        rs = ps.executeQuery();

        if (rs.next()) {
            String kd_pj = rs.getString("kd_pj");
            boolean isBPJS = "BPJ".equalsIgnoreCase(kd_pj);

            // Atur visibilitas komponen hanya kalau BPJS
            BtnUpPlgBPJS.setVisible(isBPJS);
            StatusPulang.setVisible(isBPJS);
            SEP.setVisible(isBPJS);
            jLabel46.setVisible(isBPJS);

            // Kalau BPJS, lanjut atur isinya
            if (isBPJS) {
                tampilkanNoSEP(noRawat);
            } else {
                SEP.setText(""); // Kosongkan kalau bukan BPJS
            }

            // Cek apakah status meninggal
            boolean isMeninggal = cmbStatus.getSelectedItem() != null &&
                                  cmbStatus.getSelectedItem().toString().equalsIgnoreCase("Meninggal");

            // HANYA ubah tombol jika bukan saat memuat form
//            if (!sedangMemuatForm) {
//                BtnUpPlgBPJS.setEnabled(!isMeninggal);
//                StatusPulang.setEnabled(!isMeninggal);
//            }
            
            // Tambahkan di paling akhir sebelum keluar dari try
            cekStatusMeninggal();
        }
    } catch (Exception e) {
        System.out.println("Error cekStatusBayarBPJS: " + e);
    } finally {
        try {
            if (rs != null) rs.close();
            if (ps != null) ps.close();
        } catch (Exception e) {
            System.out.println("Error close resource: " + e);
        }
    }
    System.out.println("DEBUG: cekStatusBayarBPJS dipanggil, sedangMemuatForm = " + sedangMemuatForm + ", sudahCekStatusBayar = " + sudahCekStatusBayar);


}
    
private void tampilkanNoSEP(String noRawat) {
    Connection koneksi = koneksiDB.condb();
    PreparedStatement ps = null;
    ResultSet rs = null;

    try {
        String sql = "SELECT no_sep FROM bridging_sep WHERE no_rawat = ? AND jnspelayanan = '1'";
        ps = koneksi.prepareStatement(sql);
        ps.setString(1, noRawat);
        rs = ps.executeQuery();

        if (rs.next()) {
            SEP.setText(rs.getString("no_sep"));
        } else {
            SEP.setText(""); // Kosongin kalau nggak ketemu
        }
    } catch (Exception e) {
        System.out.println("Error tampilkanNoSEP: " + e);
    } finally {
        try {
            if (rs != null) rs.close();
            if (ps != null) ps.close();
        } catch (Exception e) {
            System.out.println("Error close resource: " + e);
        }
    }
}

private void cekStatusMeninggal() {
//    System.out.println("DEBUG: cekStatusMeninggal dijalankan, sedangMemuatForm = " + sedangMemuatForm);
    if (sedangMemuatForm) return;

    String status = cmbStatus.getSelectedItem() != null ? cmbStatus.getSelectedItem().toString() : "";
    boolean isMeninggal = status.equalsIgnoreCase("Meninggal");

    if (isMeninggal) {
        BtnUpPlgBPJS.setEnabled(false);
        StatusPulang.setEnabled(false);
//        System.out.println("DEBUG: Status = Meninggal, tombol dinonaktifkan");
    } else {
        // Di sini tombol tidak diaktifkan langsung
        BtnUpPlgBPJS.setEnabled(false); // <- default tetap mati
        StatusPulang.setEnabled(true);
//        System.out.println("DEBUG: Status bukan Meninggal, tombol tetap nonaktif sampai simpan berhasil");
    }
}

// ===== Util: auto-pack kolom JTable sesuai konten =====
private void autoPackColumns(JTable table, int extraMargin, int maxRowsToMeasure, int... skipCols) {
    java.util.Set<Integer> skip = new java.util.HashSet<>();
    for (int c : skipCols) skip.add(c);

    JTableHeader header = table.getTableHeader();
    TableColumnModel colModel = table.getColumnModel();
    int rowCount = table.getRowCount();
    int colCount = colModel.getColumnCount();

    // (Opsional) batas maksimum per kolom agar UI tidak melebar berlebihan
    java.util.Map<Integer,Integer> maxCap = new java.util.HashMap<>();
    maxCap.put(3, 360);   // Alamat
    maxCap.put(7, 220);   // Kamar
    maxCap.put(8, 100);   // Tarif Kamar
    maxCap.put(9, 220);   // Dx Awal
    maxCap.put(10, 220);  // Dx Akhir
    maxCap.put(15, 120);  // Ttl Biaya
    maxCap.put(18, 260);  // Dokter P.J.
    maxCap.put(22, 180);  // No.SEP

    for (int col = 0; col < colCount; col++) {
        if (skip.contains(col)) continue;

        TableColumn column = colModel.getColumn(col);

        // lebar header
        TableCellRenderer hr = column.getHeaderRenderer();
        if (hr == null) hr = header.getDefaultRenderer();
        Component hc = hr.getTableCellRendererComponent(table, column.getHeaderValue(), false, false, -1, col);
        int maxWidth = hc.getPreferredSize().width;

        // lebar isi (sampling biar nggak berat)
        int toMeasure = Math.min(maxRowsToMeasure, Math.max(1, rowCount));
        int step = Math.max(1, rowCount / toMeasure);
        int measured = 0;
        for (int row = 0; row < rowCount && measured < toMeasure; row += step, measured++) {
            TableCellRenderer cr = table.getCellRenderer(row, col);
            Object val = table.getValueAt(row, col);
            Component cc = cr.getTableCellRendererComponent(table, val, false, false, row, col);
            maxWidth = Math.max(maxWidth, cc.getPreferredSize().width);
        }

        maxWidth += extraMargin; // ruang napas

        Integer cap = maxCap.get(col);
        if (cap != null) maxWidth = Math.min(maxWidth, cap);

        maxWidth = Math.max(maxWidth, column.getMinWidth());
        column.setPreferredWidth(maxWidth);
    }
}

// ===== Util: sembunyikan kolom by view index =====
private void hideColumn(JTable table, int viewIndex) {
    TableColumn col = table.getColumnModel().getColumn(viewIndex);
    col.setMinWidth(0);
    col.setMaxWidth(0);
    col.setPreferredWidth(0);
}


